/* 自动生成，勿手改。生成器：make_talk.js（源：build_talk.py + translate_talk.js） */
window.TALK = {"meta":{"src":"whwhwhwhwh56/buffett-library（股东大会问答，1994-2025）","note":"英文字幕的中译，只能转述，不可逐字引用","built":"2026-11-02","years":[1994,1995,1996,1997,1998,1999,2000,2001,2002,2003,2004,2005,2006,2007,2008,2009,2010,2011,2012,2013,2014,2015,2016,2017,2018,2019,2020,2021,2022,2023,2024,2025],"utterances":9598,"words":1049677,"sentWordsMedian":17,"segments":380},"segs":[{"y":1994,"at":0,"ask":"我叫Michael Mullen，来自奥马哈。您能谈谈衍生品的使用吗？我注意到Dell Computer的股票周五跌了两个半点，跟亏损和衍生品有关。","ans":"你当然最近也看到了，最近Procter & Gamble的一个公告。现在，我不知道P&G衍生品的细节，但我至少了解到，一开始是利率互换，最后变成了P&G对美国大量债券、还有我想是另一个国家的债券写了看跌期权。你任何时候从卖肥皂变成对债券写看跌期权，你就跨了一大步。而且它……借入巨额资金的能力，加上要么很快暴富要么很快变穷的机会，历史上在某个时点就是惹麻烦的配方。而且那……衍生品不会消失。它们有有用的用途什么的，但我只是说它有那种潜力，我们已经看到了一点。我想不出我们做过什么……你能想到我们做的什么接近衍生品的事吗，肯定是直接的？","kind":0},{"y":1994,"at":"00:17:24","ask":"我叫Hugh Stevenson，是亚特兰大的股东。我的问题涉及公司对Cap Cities股票的投资。我过去的理解是，那被视为四个，quote","ans":"嗯，我们把Washington Post Company、Cap Cities、GEICO和Coke归类为永久持有的类别。而且……但在这四个中的三个身上，Washington Post Company，我不记得了，大概七八年前吧，GEICO是几年前，现在是Cap Cities，我们在公司回购股份的要约中参与了。前两个，Post和GEICO，我们是按比例参与的。那个不可行，而且顺便说，税务上也不再那么有吸引力了。","kind":3},{"y":1994,"at":0,"ask":"我是奥马哈的佩格·加拉格尔。巴菲特先生，你有没有兴趣去影响美联储的格林斯潘先生，让他停止加息？","ans":"但是……我不……我觉得他做的那些事大概还算合适。我觉得他可能有点意外，当他小幅推高短期利率的时候，长期利率的反应。我猜他本来是希望，这只是我个人的猜测，在周期早期对短期利率采取的那种行动……可能会让人对长期利率更有信心，从而让收益率曲线平缓一些。我不知道是不是这样，他可能对此也有点意外。但他那份工作不容易，所以我自己不会去事后质疑他。查理，你怎么看他？","kind":2},{"y":1994,"at":0,"ask":"巴菲特先生，我叫Bill Ackman，来自纽约市，我的问题是关于Salomon Brothers作为投资标的的吸引力。你之前谈到了杠杆和杠杆的危险。Salomon是一门生意","ans":"就像你指出的，这类生意用了很多杠杆。它并不……一方面它用的没看起来那么多，另一方面它用的比看起来还多。但……考验将是，第一，他们是否以某种方式控制那门生意，使杠杆不会变得危险，第二，他们在使用杠杆时能赚到什么样的股本回报率。当你必然暴露于少量系统性风险和大量借来的钱时，你当然应该预期赚到比一个……一个极其普通的生意更高的股本回报率。但我不知道你有没有见过Bob和Deryck，不过我觉得，杠杆交到他们手里，你会比交给任何你能想象到的其他人更放心。Charlie？","kind":0},{"y":1994,"at":"01:09:10","ask":"我是Harriet Morton，来自华盛顿州西雅图。我想知道，当您考虑一项收购时，您如何看待产品的有用性，在看待任何生意时。","ans":"是的。嗯，显然我们看市场说的效用是什么，而市场……市场已经非常重度地投票支持Dexter Shoe，举个例子。举个例子，我不知道多少……1958年左右他们生产多少双鞋，但年复一年人们本质上投票支持那个产品的效用。全世界每天消费大约7.5亿份8盎司的Coca-Cola Company某种产品的 servings，而我们中有些人认为效用非常高。我一天不喝几份就过不去。但其他人可能评价不同。但本质上，人们会渴，如果这是他们解决口渴的方式，比……而且他们更喜欢这个而不是其他形式，那我会给这个产品的效用打高分。","kind":1},{"y":1994,"at":"01:20:55","ask":"","ans":"我对那些生意了解不多。我们观众里至少有一个人持有大量Reebok。但我不是在表达任何负面看法。我只是，我不理解……我不理解它们的竞争地位，以及它们竞争地位在10年或20年期间保持永久的可能性，不像我认为我理解Brown和Dexter的地位那样。这不意味着我认为它较差，不意味着我认为我们有更好的生意或什么的。我认为我们有非常好的生意。但我不……我不……我没做过功课，而且我不确定如果我做了功课我就能理解它们。我认为它们坦白说更难理解，更难搞清楚，比我们这类难。但对那些对那种生意有更好洞察力的人来说，它们可能更容易。","kind":2},{"y":1994,"at":0,"ask":"我是加州科罗纳德尔马的黛安·韦斯特。巴菲特先生，我知道您说过您不读别人对市场或经济的看法，但您或查理对你们怎么想……有没有什么看法","ans":"你们作为伯克希尔的股东，除非你是借钱买的股票，或者打算在很短时间内卖掉，否则股票变便宜对你们是好事，因为这意味着我们可以替你们做更明智的事，比不便宜的时候强。所以我……但我们不知道会怎样……我们也不在乎别人怎么想。我是说，这……最不在乎的就是我们自己。查理？","kind":0},{"y":1994,"at":"01:43:59","ask":"我是加州科罗纳德尔马的黛安·韦斯特。巴菲特先生，我知道您说过您不读别人对市场或经济的看法，但您或查理对你们怎么想……有没有什么看法","ans":"我们不知道，我们也不去想事情什么时候会发生。我们想的是会发生什么。这挺……弄清楚会发生什么并不太难。在我们看来，弄清楚什么时候发生是不可能的。所以我们专注于会发生什么。这家公司，在1890年前后，整个公司卖了2000美元。现在它的市值大概有500多亿美元。当年有人可能会对1890年买下它的人说：“你知道，你将来会……你会经历两次世界大战，你知道，你会遇到1907年的恐慌。所有这些都会发生。等一等是不是更好的主意？”","kind":0},{"y":1994,"at":0,"ask":"我的问题是，现在我们看到各种分析师说，按照他们的个人意见，你应该调整你的……更多现金、更多股票、更多债券，因为……伯克希尔哈撒韦怎么看择时","ans":"我想我得承认，如果我们手头有很多钱，我们会比平时笨一点。我是说，这容易让人变得粗心。但我要说，最好的收购通常是在你不得不卖掉一些东西来筹钱的时候做的，因为那会稍微抬高你在做心理决策时要跨过的门槛。但我们有，我不知道财报会显示多少，但肯定有超过10亿美元的现金在手，那不是我们主动选的。那是……你可以把它看成管理层失败的指标，等我们能买到用掉这些钱的企业或企业的小部分时，我们会很高兴。4区。","kind":0},{"y":1994,"at":0,"ask":"巴菲特先生，芒格先生，我叫戴夫·兰卡斯。我是《商业保险》杂志的高级编辑。有两个问题问你们。能不能稍微解释一下你们的主要保险业务，是什么推高了承保","ans":"在再保险业务上，我觉得我们的再保险业务和很多其他公司——你知道，不是全部——比如百慕大那些公司的本质区别，就跟我们在证券操作上和其他人的区别差不多。我们随时愿意以我们认为合理的价格提供大量再保险，但如果我们觉得不合理，就不做。就像我们有可用现金，就会去买合理的证券，但我们对单纯待在股市里没兴趣。我们想拥有对我们来说合理的证券。","kind":0},{"y":1994,"at":0,"ask":"在我看来，1993年股价最高和最低之间的波幅比过去那些年大得多。你愿意评论一下吗？","ans":"我们，我们处理这个问题的最好方式就是给股东和潜在股东提供我们能给的所有信息，并遵循我们认为会吸引有长期眼光的投资导向的人加入我们、而不鼓励其他人的政策。但偶尔，你知道，我们没法保证那个结果。有件事我觉得挺有意思，我不知道是三个月前还是什么时候，但我碰巧跟那个做市商聊，很棒的做市商，Jimmy Maguire。他得走了，但他早些时候在会场这儿。","kind":4},{"y":1994,"at":"02:53:53","ask":"你预期Berkshire会成为标准普尔500的成分股或道琼斯成分股吗？","ans":"嗯，我觉得它成为道琼斯成分股不太可能。我不知道标普500的标准是什么，但我猜有些原因让我们不符合。我不知道他们是不是对流通股数量有疑问，或者，我从来没跟标普核实过。如果我们是不在标普里的市值最大的公司，我不会感到意外，虽然我也不知道是不是这样，但他们可能有些标准，各种各样的，把Berkshire排除在外。","kind":2},{"y":1994,"at":"03:03:48","ask":"好，抱歉。就Berkshire那些因此具有流动性的大的非永久持仓而言，我只是想知道，当你决定卖出其中一部分时，你管理市场冲击的策略是什么","ans":"对，对。关于我们可能卖的东西，以及我们卖的时候市场会怎样。那要看情况。我是说，可能是很大的冲击，也可能是可以忽略的冲击，取决于市场状况。取决于我们是否可能向一些机构大宗卖出。取决于，可能是，你知道，可能有要约收购之类的，我们会通过那种方式卖出。所以很难衡量，但这确实是个劣势。规模是个劣势，你这个基本观点完全正确，买入和卖出都是，我们不知道有什么办法能绕开。所以我们在预期里就把它算进去了，你知道，那种，我们需要看到的。而且我们，我们卖得如此不频繁，所以它不算是个致命的负面因素，但它是我们有的、你们没有的一个负面因素。2区。","kind":0},{"y":1994,"at":0,"ask":"Buffett先生，我是Barry Ziskin，来自亚利桑那州Mesa。长期仰慕者。观众的问题是关于Guinness的。我记得在一份我非常尊敬的出版物上读到，Outstanding Investor Digest，Henry Emerson，纽约，","ans":"你应该试着做一大堆货币互换，去把那一整股流转换成美元吗？我们基本上不认为值得。我们不认为我们对货币的看法有任何好处。我们不认为，我们认为市场可能知道，嗯，我们知道它知道得一样多，可能对货币知道得更多。但我们不知道，我们并不比市场更了解货币。所以对冲有成本，即使利率结构可能使曲线向前看显得平坦，所以实际上没有升水，仍然有成本，其中有成本。现在，它是一个相对有效的市场，所以成本不大，但我们看不出有任何理由用我们视为完全五五开的东西去承担那些成本。","kind":0},{"y":1994,"at":0,"ask":"我是纽约的Byron Wien。你说过，你把经营决策下放，但资本配置决策集中。你在奥马哈有什么样的员工来帮你做资本配置决策？","ans":"你想，一个CEO在任10年，他的企业股本回报率比如说是12%，他分出三分之一，那意味着他每年有8%的股本增长。我是说，想想他在任期间配置了多少资本，随着时间推移这是个巨大的因素。但可能相对很少的CEO要么受过资本配置的训练，要么是基于资本配置能力被选上来的。我是说，他们是通过其他路径上来的。所以我说过，这就像，你知道，一个人弹了一辈子钢琴，然后到了卡内基音乐厅，他们递给他一把小提琴。我是说，这跟大多数公司里通往CEO职位的路径上的那些职能，是不同的职能。","kind":0},{"y":1994,"at":0,"ask":"我是纽约的拜伦·维恩。您说过您把经营决策下放，但资本配置决策是集中的。您在奥马哈有什么样的团队来帮您做资本配置决策","ans":"很多CEO到了那个位置，觉得可以通过设一个团队来做，或者请咨询顾问之类的来解决。在我们看来，你知道，那是个糟糕的错误，因为这件事，如果不是CEO的关键职能，那也是所有公司里，比如说80%或90%的公司里两三个关键职能之一。你自己做不了，就会犯很多错误。就算你自己做，也可能犯很多错误。但你要是，你知道，你不会希望公司里任何其他同样重要的位置上的人基本上说：“我不知道怎么做这个，所以我让别人来做”，而这偏偏是他的核心职责。但商业里就是这样。","kind":0},{"y":1995,"at":0,"ask":"我们该怎么办，董事长？现在Berkshire投资的大多数公司都不是热门股，不在高科技板块。过去几年我们看到，销售似乎有显著增长","ans":"在……我觉得那些原则，我觉得本·格雷厄姆的原则用在高科技公司上完全有效。只是我们不知道怎么去做，但这不代表别人不知道怎么去做。我猜如果比尔·盖茨在想——你知道，他懂而我不懂的东西，他在投资决策上会用跟我差不多的思维方式。他只是理解那个生意。我可能觉得自己懂可口可乐或吉列，而他可能有能力理解很多别的生意，那些生意对他来说就像可口可乐或吉列对我来说一样清晰。我觉得一旦他认定了那些，他在决定怎么行动时用的标准会跟我差不多。","kind":0},{"y":1995,"at":"01:09:59","ask":"提问前先说一句。1994年11月24日的《财富》杂志有一篇专题文章，标题是“美国最伟大的财富创造者”，讲的是市场增加值这个概念，还有……","ans":"对，对。资本作为定价模型，这个……我不知道现在用得多不多。当然，你知道，这些东西都是一波一波地流行。管理上有，投资上也有。我是说，房地产，你知道，可能流行过，或者国际投资。你可以翻翻《养老金与投资》杂志，挺不错的一本杂志，但你就能看到这些风潮一阵一阵地过，然后有人办研讨会什么的，你知道，投资银行家就造产品来满足需求。管理上也有这些风潮。我是说，显然听客户的话之类的，那……没有比这更有道理的了，但你很难写一本300页的书就只说“听客户的话”。","kind":0},{"y":1995,"at":0,"ask":"当然我的球队是……或者说曾经是迈阿密飓风队，我……对，我衣服里面穿着绿橙色的。不过如果我们输了，我很高兴是输给Nebraska和Tom Osborne。我有个请求想问Warren……","ans":"我们在这方面有很大优势，跟几乎所有其他公司都不一样，我们现在和将来都愿意、渴望买下好生意的一部分，或者全部。我是说，大多数管理层有……大多数投资者只能买生意的一部分，而大多数管理者心理上或者习惯上是要拥有一个自己能管的完整的东西。我们呢，你知道，就像，我记得Woody Allen几年前说过，双性恋的好处是周六晚上约到人的机会翻倍。对，但我们在那方面两个方向都可以走，我们的继任者也会这样。所以非常……Charlie，你有什么要说的吗？","kind":0},{"y":1995,"at":"01:50:26","ask":"","ans":"对，我没读过那本书。我不太想跟股东们承认这个，我……这本书……我觉得它大概排在第，不知道，第七第八还是多少，在《纽约时报》畅销榜上，已经上榜几个月了。是一个投资团体，显然他们……在向全世界分享他们成功的秘诀。我一向对那些向全世界分享投资高见的人持怀疑态度。不过我们目前没受到威胁。好，第6区。","kind":4},{"y":1995,"at":0,"ask":"Buffett先生，我叫Liz Pruss，来自纽约市。我想问，关于你的收购标准，我知道其中一部分是Berkshire Hathaway不会参与敌意收购。我想知道那个理念……","ans":"嗯，就Berkshire的情况来说，Malcolm Chace，当时的董事长，完全支持我们买Berkshire的股票，但Seabury Stanton，总裁，不会支持，而Seabury是，是，是在管业务的人。所以那不是，不是敌意的，但Seabury不会支持，而Malcolm会支持。所以我不知道，我不知道今天如果有人走进Gillette或Cap Cities之类的地方会是什么情况。我不觉得那会发生，但我没有，我在这一点上没有任何政策。","kind":4},{"y":1995,"at":"02:44:12","ask":"是的，我是Neil McMahon，来自纽约市，也是Sequoia的股东。本·格雷厄姆的投资理念鼓励换手率。看看Berkshire的持仓、集中度和长期持有，你还是15%的Phil Fisher加85%的格雷厄姆吗？","ans":"我不知道那个百分比会是多少。在我前面提到的那三点上，我是100%的本·格雷厄姆，而那几点真的来自……我非常，我最早读Phil Fisher那两本书大概是在1960年前后，受他影响很大，我觉得那是两本了不起的书。我觉得Phil是个了不起的人。所以我想我大概给过那个百分比，我记得我第一次用那个说法是在《福布斯》上，当时Jim Michaels写信给我，我想我，你知道，就是那种事，我随口说了个数字。但我觉得，我觉得我更愿意把自己看成是100%的本·格雷厄姆加100%的Phil Fisher，而在他们不……他们其实并不互相矛盾，只是侧重点差别很大。","kind":0},{"y":1995,"at":"03:03:10","ask":"你好。我叫Lee Dubrov，来自西弗吉尼亚州摩根敦。自从Salomon那档子事之后，好像你吸引了越来越多的媒体关注。在这方面，有很多表现……","ans":"嗯，我确实比以前收到更多邮件了，所以我们在这方面稍微多建了点流程。但我就是，我做我喜欢做的事，就是演讲。我大概被邀请、被要求演讲的次数可能是10年前的20倍，但我做的次数还是一样。我，你看，我有，我对自己做这些事有自己的筛选流程。也一样，你看，我被邀请去，你看，我不知道多少个晚宴致敬会之类的。","kind":4},{"y":1995,"at":"03:32:44","ask":"我是Roger Hill，来自威斯康星州拉辛。先生们，换个节奏。能不能谈谈你们对当前国际汇市状况的看法？你觉得我们有美元问题，还是日本","ans":"那大概……那是个很好的问题，但麻烦在于，每当我说那是个很好的问题，大概都是因为我不知道答案。那个，我，你知道，那个我不知道答案。坦白说，外汇让我困惑。我是说，你知道，我会从购买力平价的角度去想，因为那是自然的思路，但购买力平价作为判断汇率在短期、近期、中期、甚至可能长期会怎么走的指南，并不太管用，因为世界会以不同方式调整。有时候它通过高通胀来适应一种下沉的货币。通常是这样。对我们美元倒还没这样，但我们只是相对少数几个重要货币在下沉。这个问题我给不了你什么好答案，抱歉。6区。","kind":2},{"y":1995,"at":"03:52:16","ask":"以你们过去的增长速度继续增长很难，因为公司已经变得太大了，我想你能不能稍微展开讲讲。我的第二个问题完全不相关，但我……","ans":"嗯，说第一个问题，你说会很难，其实是根本不可能。我是说，这就是答案。我们没法以120亿美元的基数让钱以23%复利增长。我们不知道怎么做到，任何人要是觉得我们能接近那个水平，那就是个错误。我们还是觉得我们能把钱做得还行，但我们不是从120亿的基数起步的，我们也从没见过世界上有谁能以那种速度复利。所以那部分就算了，但我们可以做一些聪明的事。","kind":2},{"y":1995,"at":"03:54:59","ask":"很难继续以你过去那种速度增长，因为公司已经变得太大了，我想知道你能不能稍微展开讲讲。我的第二个问题完全不相关，但我……","ans":"我同意这一点。但那些放在对数坐标纸上、往回追溯15年的东西，那是对美国存在的很多大企业最好的一次性描述。我无法想象任何做普通股投资业务的人书架上没有那东西。如果你脑子里大致有各个行业、各种生意那些东西长什么样，那你就有了一个衡量的背景。","kind":0},{"y":1995,"at":"04:21:55","ask":"嗨，我叫Mark Wheeler。我来自俄勒冈州波特兰，我在你的篮子里放了几颗鸡蛋。我祖母总说别把所有鸡蛋放在一个篮子里。我有个问题。我想你几年前回答过这个","ans":"嗯，那最好找个经纪人把这个账户翻个底朝天。如果他拿管理费，激励还小一点。但你说的那种情况下该做哪个决定，我没法回答你。不过我曾经，我想说，如果你买Berkshire，你确实应该只想着非常长期地持有它，这点你说得对。我是说，我们根本不知道Berkshire明年内在会怎么样、市场上会怎么样。坦白说，你知道，我们不，我们关心的是内在那一块。我们不关心市场那一面。我们确实关心内在价值的积累。而且，你知道，到最后，我们不觉得，当我们持有Berkshire的时候，我们不觉得所有鸡蛋都在一个篮子里。我是说，因为我们有很多好生意。","kind":0},{"y":1995,"at":"04:29:01","ask":"嗨，我是来自旧金山的Philip King。我还有一个关于估值的问题，更具体地说是市盈率和利率的关系。我理解你不想定一个死板的估值公式，但我……","ans":"对，嗯，主要起决定作用的不是今天盈利的倍数。你看，我们买可口可乐，比如1988年和89年，这只股票，每股11美元，最低到9，最高到13，但平均大约11美元。今年每股收益，我们说，大多数估计在2.30到2.40美元之间。所以还不到今年盈利的五倍，但我们买的时候，那个倍数其实挺高的。关键是未来。就像我在那儿写的，Wayne Gretzky说的，要滑向冰球将要去的地方，而不是它现在在的地方。所以当前的倍数要和资本再投资、以及资本投资的回报率相互作用，才能决定一个东西现在有没有吸引力。","kind":1},{"y":1995,"at":"04:32:52","ask":"好吧，至少我想向你指出，你确实在大约五六年里拿到了股息，那笔钱被再投资了，也许回报比USA什么的还好，那也不算太……","ans":"是啊，你说得对，本来可能更糟，但那是个错误。但我们，我们收了五年，对吧？我猜。是啊，我们拿到的时候是五年不错的股息率。但，但就像有人说的，你在意的不是本金上的回报，而是本金的回报。而我们，但我们情况更好，我们显然比买了普通股好得多，甚至比买某些其他股票还好，但对我来说那仍然是个大错误。","kind":0},{"y":1995,"at":0,"ask":"我想你会喜欢这个说法。显然你明白这个问题。我理解你这些年来的立场，也理解拆股不增加价值这个事实。不过在这种情况下，它可能","ans":"所以我们，我们几乎可以肯定我们会得到，我们只是，我们不知道，我们不知道那会到什么程度。我们几乎可以肯定我们会得到一个股东群体，他们的成熟程度、和我们目标的同步程度，都达不到现在这个水平。这几乎是肯定的。而Berkshire股票真正不需要的就是更多需求。我是说，那不是，除非内在价值增长，否则我们并不想让股价卖得更高。","kind":2},{"y":1996,"at":0,"ask":"","ans":"所以，我们的希望是，我们吸引来的B类股东和这个房间里的人素质一样，他们有那种投资态度，觉得自己买的是一个企业的一部分，期望无限期持有，也许是余生都持有，而不是把它当成一张可能因为是新股之类的东西而热门的纸片。这样，对现在股票满意的人可以保持完全一样的处境，这也是我要做的，查理要做的。","kind":0},{"y":1996,"at":0,"ask":"","ans":"但如果你稍微想一想，你能想象一个管理层走出去对全世界说，我们在新股里卖给你们的东西，被严重低估了？如果你走出去对公众说，我们卖给你们值一美元的东西，我们要以80美分卖给你们，那你对现有股东说什么？那会让我非常不高兴。","kind":0},{"y":1996,"at":0,"ask":"","ans":"我们不希望人们买Berkshire的时候，以为他们买的是被低估的东西，因为并不是。我们在招股说明书第四条注意事项里说了，我们希望人们买它，只有当他们预期要长期持有的时候。Charlie和我要长期持有，事实上，你们可能哪天看到我们坐在这儿，连旁边那家伙是谁都不知道了，不过我们还是会装装样子的。那个，我们，你知道，这就是我们对Berkshire的态度。我们不希望那种觉得它是个热门股、或者一年后能卖更高价的人进来，因为我们压根不知道一年后它卖得更高还是更低。从来就不知道。","kind":0},{"y":1996,"at":0,"ask":"你的问题似乎是，你吸引了相当多潜在股东，他们没有方法估算内在价值或对Berkshire未来前景形成预期。你有没有……","ans":"所以你的处境是一样的，只要你是跟踪我们这类企业、理解行业状况等等。我们会继续这样做。我们基本上把你们当作我们的合伙人，我们告诉……我们尽量告诉你们，如果你们在经营这个地方，作为合伙人会想知道什么。我们会继续这样做。我们不会告诉你一个数字，因为我们不知道那个数字。我们心里有一个区间。事情会随着时间改变那个区间。如果我们试图公布那个区间，可能会惹上各种麻烦。而且，Charlie和我不会得出完全相同的区间，但会非常接近。我们稍后会多谈一点。我们现在有来自另一个房间第七和第八区的问题，所以我们先接第七区，请。","kind":5},{"y":1996,"at":"01:55:52","ask":"我得说你们俩看起来都挺不错的。谁减得最多，你们的饮食秘诀是什么？然后更……更严肃的问题是浮存金。你前面稍微提到了一点，但你经常说","ans":"是啊。那个……查理和我减得差不多，每人大概20磅。保险业务给我们提供了浮存金。浮存金就是我们持有但不属于我们的钱。就像银行有存款一样。银行有存款，那钱不属于它，但它持有那笔钱。现在，银行持有存款的时候，除了活期存……活期存款，其他都有明确的成本和利率。然后还有运营系统和吸收资金的成本，这也……必须分摊到活期和定期存款上。所以获取他们所谓的存款、我们所谓的浮存金，是有成本的。","kind":0},{"y":1996,"at":0,"ask":"我是……我能想到一些……我们有些人可能想做的来保护我们可观的投资，比如说，从Blue Chip Stamps时代就持有Berkshire了。但不管怎样，我们可以下一个止损单，可能会撤出……","ans":"而当我不在的时候，合乎逻辑的……在某个时点，取决于具体什么时候发生，但Charlie比我大一点，很可能又会分成两个人的职能，但不完全是我和Charlie运作的方式。也就是说，会有一个人负责投资和资本配置。我在年报里提到了Lou Simpson的位置，因为他比我年轻。然后有一个人负责运营。我们现在组织里已经有这个人了。现在，我不知道我去世时情况会怎样，因为可能是20分钟后，也可能是20年后。所以当那个……所以我不能具体点名。我们现在这两个职能的人都有了。20年后我们也会有这两个职能的人。我不知道……我不知道会不会是同样的人。","kind":2},{"y":1996,"at":0,"ask":"我……我能想到一些……我们有些人可能想保护我们可观的投​​资，比如说从Blue Chip Stamps时代就持有Berkshire的人。但不管怎样，我们可以下一个止损单，可能会撤出……","ans":"我们有一些非常好的企业，你看，没人买See's Candy是因为觉得我坐在Omaha的某个办公室里，也没人买GEICO的保险单是因为……我的名字挂在那儿当董事长或CEO。这些企业是了不起的企业。它们会继续很好，到那时会有资本配置的问题，就像现在一样，还会有留住优秀经理人并公平对待他们的问题。那是可以解决的问题。这就是从Kiewit Plaza看到的未来。查理？","kind":2},{"y":1996,"at":0,"ask":"我是Joe，我是伦敦的Joe Condon。Buffett先生和Munger先生都在年报和之前的股东大会上回答过我的问题。这是我第一次来。我的问题关于投资几家伟大的高科技","ans":"现在，如果你要赌某个人能看清楚并且做我们自己做不到的事，我宁愿赌Bill Gates，而不是任何别人，但那个，我不想赌任何别人。我是说，归根结底我们想自己弄明白我们认为一个生意要往哪儿走。如果有人告诉我们这生意要变很多，在Wall Street他们特别喜欢跟你这么说，那个，你知道，那是大机会。顺便说一句，Wall Street自己要大变的时候他们可不觉得是大机会，但他们，你知道，那是大机会。我们根本不觉得那是机会。我是说，我们，那把我们吓坏了，因为我们不知道事情会怎么变、会变成什么样。","kind":0},{"y":1996,"at":0,"ask":"我是Joe，我是伦敦的Joe Condon。Buffett先生和Munger先生都在年报和之前的股东大会上回答过我的问题。这是我第一次来。我的问题关于投资几家伟大的高科技","ans":"我们在看，你知道，人们嚼口香糖的时候，我们很清楚他们20年前怎么嚼的、20年后会怎么嚼，而且我们真没看到多少技术进入嚼口香糖这门艺术，你知道。所以那个，只要，只要我们不非得做那些别的决定，我们干嘛要去做呢？我是说，你知道，如果，我，各种各样我们不懂的东西，那既然我们能赌简单的东西，为什么要去赌我们不懂的东西呢？1区。","kind":0},{"y":1996,"at":0,"ask":"这些生意是不是很难预测5年或10年后的样子，比如制鞋生意？","ans":"我希望会有一些新的生意，我希望是大生意，但我不觉得我们现在这个生意里会有很多意外。我的猜测里会有一个意外。我不知道那会是什么，但我是说，你知道，你，生活里就是这样。但不会有一连串的意外。而如果你，如果我们去买，我们拥有一家基本金属生意，或者很多很多我能想到的零售生意，或者汽车生意，我不确定我知不知道5年或10年后我们在竞争格局里会站在什么位置。它，我不会想去试着进来取代See's Candies，比如说。","kind":2},{"y":1996,"at":0,"ask":"我是芝加哥的Randall Bellows。感谢这个马拉松式的问答时段。我们很享受。谢谢。我的问题是关于证券业务的，总的来说是华尔街公司，具体来说你觉得……","ans":"你花几百万美元买下当地脑外科医生和他的诊所，第二天，你知道，你拥有什么？而且，如果你买当地脑外科医生，你不会付任何真正的盈利倍数，因为他几天后就会醒悟，真正是他，而不是你拿着那张小股票证书在产生盈利，那是他的声誉，而他不在乎。你想象一下Berkshire Hathaway做脑外科广告，你知道我们会做多少生意。所以企业是他的，即使股票证书在你手里。","kind":0},{"y":1996,"at":0,"ask":"Glenn Rollins，佐治亚州亚特兰大。你在致股东信中说到，对于全资子公司，当它们向你上缴资本时你会给予更高的回报率，同样你也向它们收取更高的……","ans":"说实话，我们觉得企业奖励高管时完全不考虑资本成本，这很糟糕。我是说，一个10年的固定价格期权，你想想，等于给人一笔10年的无息贷款。你不会这么做的。如果一家公司保留了很大一部分利润，然后你给出一个10年的固定价格期权，你知道，他们什么都不用做，光放储蓄账户里就能赚钱。所以我们喜欢附加资本成本。如果Berkshire对我和查理有期权——这不会发生——但也不是不合逻辑，也不是不合逻辑，我们对整个公司负责。可以有一种薪酬安排，跟整个企业的表现挂钩，对我们俩来说那是合理的。","kind":0},{"y":1996,"at":0,"ask":"John Lichter，来自科罗拉多州博尔德。有没有一些值得推荐的书？另外，关于Eisner和Disney，您会怎么定义Michael Eisner的能力圈，还有你们……","ans":"如果你问这个，我会推荐Phil Fisher在1960年前后写的前两本书，《Common Sense and Uncommon Profits》和第二本。那些是很好的书。你知道，我显然首先推荐《The Intelligent Investor》，第8章和第20章是真正该读的。两个，嗯，投资里所有重要的想法其实都在那本书里，因为一共也就大概三个想法，而那两个，其中两个在那两章里重点讲了。其实我觉得John Train的《Money Masters》是一本，一本有意思的书。我不知道，Charlie，你还能想到别的吗，我们想推荐的？","kind":0},{"y":1996,"at":0,"ask":"Edward Barr，肯塔基州列克星敦。您刚才带我们讨论了Disney的竞争地位，您也讨论了股票回购。我想知道您能不能也带我们讨论一下……","ans":"而且那是，我们喜欢，我们喜欢像银行业这样的生意，前提是我们有合适的人在管，会把生意管对。我们有一个，我不知道Bob Wilmers在不在场，但他经营First Empire，我们在那里有一笔相当大的投资，Bob就是管得对。你知道，我不担心Bob或者First Empire会出什么意外。如果能增长，而且合逻辑，他就会增长。如果做某件事不合逻辑，他就会放过。他没有那种自我强迫，逼着自己非得做点什么，而且他经营着一家非常棒的……","kind":0},{"y":1996,"at":"04:38:29","ask":"Dorothy Craig，来自西雅图。我注意到年报里你们最近的收……收……收……年报里你们最近的收……收……收购……","ans":"嗯，这个，它，一方面，我们是从一个比较小的基数开始的。但那个，我们，GEICO的收购，你知道，增加了大约30亿美元的收入，其实还不止，稍微多一点，但多不了太多。而R.C. Willey和Helzberg's今年大概增加了6亿美元左右。因为我们原来的基数大概是35亿美元，那三笔收购确实让收入翻倍了。我们不会有太多年份发生这种事。让收入翻倍或者增长20%不是我们的任何目标。它来了，如果合逻辑，我们就做很多，如果没什么合逻辑的东西出现，我们就什么都不做。所以它，这里面有很多偶然。但去年，你知道，发生了不少，我很想看到明年也发生很多，但我们现在不知道。","kind":3},{"y":1996,"at":"05:00:05","ask":"嗨，我叫Mike Nolan，来自新泽西。我和我妻子从1984年起就是股东，而且是很开心的股东。谢谢你们两位。今天两个问题。零售店行业：鉴于Berkshire出色的23%年复合","ans":"而且那两家公司的平均净资产回报率都比你说的行业数字好得多。第二点，你知道，我们没办法在未来做到23.6%。所以我们不用我们的历史，如果我们把历史平均值当作新投资的标尺，我们就什么新投资都不做了，因为我们不知道怎么在未来做到23.6%。但我们喜欢，我们喜欢，我们把零售生意看作非常难的生意。我们喜欢那两家公司的记录、它们的市场地位和它们的管理层。当我们找到那样的生意，我们对经营它的人感到很放心，我们就会做这笔交易。但我们不会指望这么做长期能赚到23.6%。","kind":0},{"y":1997,"at":0,"ask":"Buffett先生，我叫Pete Banner，来自科罗拉多州博尔德，我是股东。最近Greenspan先生发表了他关于 exuberance 的评论，没过多久你就在年报里出来了","ans":"所以我觉得指出这一点是恰当的：不管一家企业多么出色，总存在一种风险，就是你付出的价格会让企业需要几年才能赶上，或者说，让企业赶上股价，股价可能跑到企业前面去。我不知道对那些公司或任何其他公司来说那个点在哪里，但我确实说过，我认为市场上大多数证券存在这种情况的风险相当高，包括像 inevitable 这样的公司。但那番话的目的是确保人们不要把我对那些公司的评论，不管价格如何，就当作无条件的买入建议。我们无意卖出那两只股票。即使它们以比现在高得多的价格出售，我们也不会卖。","kind":0},{"y":1997,"at":0,"ask":"第一部分是，你能不能定义一下，给我们你对股市风险的定义，以及它如何不同……","ans":"Ben Graham用了市场先生这个例子，就是我们用过，我在报告里也照搬了。我从所有好的作家那里照搬。Ben说，你知道，你就想象当你买一只股票时，你实际上是买进了一家企业，你有一个殷勤的合伙人每天来找你，给你一个价格，你可以按这个价格买入或卖出，价格是一样的。在私人企业里从来没人能得到这个，每天有一方给你买卖报价。但在股市里你就能得到。这是个巨大的优势。而且，如果你的这个合伙人是个酗酒的躁郁症患者，那优势就更大了。我是说，他越疯狂，你赚的钱就越多。","kind":4},{"y":1997,"at":"01:00:15","ask":"我是B类股东。我想请你评论一下我们做的一些分析。如果有人用你的投资哲学，构建一个六到八只股票的高度集中组合，并且采用你的买入并持有……","ans":"是啊，嗯，如果Intel或者Microsoft比Coke和Gillette表现好一倍，那回报当然能到两倍。我是说，问题在于你能不能识别出你懂并且非常有把握的生意。如果你懂那些生意——很多人懂，但Charlie和我不懂——你就得去评估它们，如果你决定了，你会做得很好。但有一整类公司，很大一类公司，Charlie和我就是不知道怎么估值，这我们不困扰。我是说，你知道，我们不知道，我们不知道怎么算可可豆会怎么走，或者俄罗斯卢布，或者，我是说，各种金融工具，我们就是觉得自己没那个知识去评估。而且说真的，你知道，指望一个人懂世界上每一门生意，可能有点太过分了。","kind":0},{"y":1997,"at":0,"ask":"我是B类股东。我想请你评论一下我们做的一些分析。如果有人用你的投资哲学，构建一个六到八只股票的高度集中组合，并且采用你的买入并持有……","ans":"但我对那些生意了解得不够，没法像我对Gillette和Coca-Cola的生意那么有把握那样，确信那些仓位是极好的。你可能比我更懂那些生意，因为你的背景，或者你脑子就是那么长的。但我不懂，所以我只能守住我真正认为自己能看懂的东西。如果别处能赚更多钱，我觉得赚那些钱的人理应赚到。Charlie？","kind":0},{"y":1997,"at":0,"ask":"我是Fred Cooker，来自科罗拉多州博尔德，这是一个关于内在价值的问题，是问你们两位的，因为你们写过也许你们会得出不同的答案。你们写和 spe","ans":"你描述的那些筛选条件，有很多筛选条件在对我们说，我们不知道那家企业10年或20年后值多少，我们甚至没法做一个有根据的 yes。显然，我们不认为我们知道到小数点后三位或两位或诸如此类，具体会产出什么，但对某些类型的企业，我们有高度的信心我们大致在范围内。筛选条件的设计就是为了确保我们处在那些类型的企业里。我们基本上用长期无风险利率，也就是政府债券类型的利率，来考虑我们应该用什么来折现。","kind":0},{"y":1997,"at":0,"ask":"好。对。市场先生现在给道琼斯估值在七千点以上，标普大约800。按你的估值模型，在当前的利率、当前的通胀率和当前的增长率下，公允估值是多少","ans":"过了一阵子，就像我之前说的，人们就单纯被价格上涨这个概念迷住了，不再回头去想背后的道理，那时候就可能出现非常危险的情况，可能出现泡沫。而且，你知道，它，我完全不知道市场会往哪走，但它，你当时有那种可能造成真正过度的条件，就像1973年和74年有过过度一样，回到那时候你可以用两毛钱买一块钱的东西。你在另一个方向也有过度。你知道，国家也没消失什么的。","kind":0},{"y":1997,"at":0,"ask":"我是来自密歇根州格罗斯波因特的查尔斯·帕塞尔斯。很高兴来到这里。我是伯克希尔的新股东，很遗憾这么说，但是，但这并不减少我对过去业绩的钦佩或我对未来的信心","ans":"所以这只是游戏的一部分，会有各种各样的超级大灾。会有，你知道，巨大的地震，飓风会比大地震多，当那个时候到来，我们会开一张大支票。但那不，你知道，这种事件之后价格可能会更坚挺，也可能不会。安德鲁发生后，价格并没有像你预期的那样坚挺。安德鲁对人们来说是个巨大的意外。岔开一句，你知道，保险业的人以为他们都有这些模型，有些是再保险经纪人做的，有些是各种研究机构做的，就是他们在某些情况下会损失多少，而面对安德鲁或北岭地震，他们错得不能再离谱了。幸运的是，我们不依赖那些。我们，我不知道我们到底依赖什么，但我们不依赖那些在……","kind":2},{"y":1997,"at":0,"ask":"是的，我叫金清华。我来自新墨西哥州，我是股东。我有两个问题。第一，那封91年的信，你写道投资者最终会重复他们的错误。那么你做什么来防止自己犯","ans":"前面关于，你知道，我说过的从错误中学习，最好的办法是从别人的错误中学习。我是说，你知道，就像，你知道，巴顿过去常说，你知道，为国捐躯是一种荣誉，确保让别人得到那个荣誉，你知道。（笑声）所以我们的方法是，真的是试图间接地学习。但有很多错误我重复过，我可以告诉你。最大的一个可能是，所有最大的类别随着时间推移，就是不愿意为一家我知道真正出色的生意多付一点钱，或者在我知道它出色的时候继续以更高的价格买入。这个的代价已经达到许多许多十亿美元，而我可能还会继续犯那个错误。","kind":4},{"y":1997,"at":"03:27:18","ask":"Buffett先生，我是俄亥俄州哥伦布的Pete Brown，B类股东。我有几个问题，如果可以的话。第一个是，我心里不太清楚我们典型的保险业务是怎么运作的，我是说，……","ans":"如果Charlie和我被迫——被告知我们只能选：在他们交易所上市的2500或3000只或不管多少只股票里买A、B、C或D，或者买10年期政府债券，而且股票得拿10年，债券也拿10年——大概至少80%的情况我们会选10年期政府债。你知道，很多情况是因为我们对那门生意了解得不够。其次，别的地方，我们可能懂了，但仍然更愿意要10%的政府债。所以，但我们会用那个标准衡量一切。我不知道，你算出来是多少，80还是多少，Charlie？荒岛上，10年，抱着股票凭证还是抱着政府债券，你选哪个？","kind":0},{"y":1997,"at":0,"ask":"我是纽约市的Mike Assael。你能不能再多解释一下你所说的消费者心智和产品的本质，并且解释一下你实际上怎么把这些概念用来找到那些……","ans":"我不知道你怎么把那类公司挤下去。我是说，如果你给我1000亿美元——我鼓励你们谁要是在想这事就站出来——但如果你给我，让我把Coca-Cola公司从世界软饮料领导者的位置上挤下去，你知道，我一点头绪都没有。但……这就是我们喜欢的那种生意。Charlie？","kind":0},{"y":1997,"at":"04:31:29","ask":"我叫Hugh Stevenson，来自佐治亚州亚特兰大的股东。我的问题跟GEICO有关。如果我没记错的话，去年GEICO大概占了保险市场2%的份额，浮存金大约40亿美元","ans":"对，对。有人……你会说有人肯定做对了什么。但问题是，我没听谁说过他们到底做对了什么。你知道，他们不想说，因为不符合那个套路。你看，像State Farm这样的事发生在这个世界上，你应该试着去，你应该试着去理解它。像GEICO这样的事发生在这个世界上，你应该试着去理解它。","kind":0},{"y":1997,"at":"04:33:28","ask":"我是来自佐治亚州亚特兰大的埃弗雷特·普里，我想问您能否评论一下内在价值的问题，当它适用于一些不可避免的公司时，鉴于现在多付的风险很高，而且股价","ans":"嗯，我们不会给它们定价。我们只是，我们告诉你它们是绝对出色的生意，由非凡的人经营，而且它们的售价高于大多数时候的售价。然后，但那，你知道，它们可能，它们很可能值这个价，甚至值更多，即使按现在的标准，或者可能提前几年透支了。我们不知道答案。我们知道我们非常高兴拥有它们。","kind":2},{"y":1997,"at":"04:42:53","ask":"","ans":"是的，我不知道按现在的价格我更愿意买哪一个。我是说，我觉得，你可以抛硬币决定。它并不会仅仅因为恰好是每股200美元而不是每股38,000美元，就比伯克希尔有戏剧性更好的增长潜力。我是说，我觉得两者的前景可能相对接近。而且，我，它们实际上基本上是由同一批人经营的。查理可能在Wesco上花的时间比我多一点。但它们的前景是一样的。","kind":2},{"y":1997,"at":"04:54:58","ask":"我是Joe Nobbe，来自西雅图的股东。Buffett先生和Munger先生，我想你们能不能再谈谈McDonald's，接着今天早上的话往下说，但更多是围绕Mc","ans":"对，在美国，普通人一年会买27个，27个Sensor或者Excel。你知道，大概每13天一个。我不知道零售价是多少，因为他们作为董事免费送给我们，但，你知道，如果是一美元一个，那就是27块钱。我是说，这差别很大。当然，全世界都在发生的就是，那些用便宜的双面刀片或者随便什么东西的人，他们不断在舒适度上往上走，在他们的舒适阶梯上往上爬，而Gillette是直接的受益者。刮得舒服和刮得马马虎虎、满脸划痕伤口之间的差别，一年10块钱，一年12块钱，我是说，那不会，那不会让多少人改变习惯。","kind":1},{"y":1997,"at":0,"ask":"你好。我叫John Zavanovich，来自加拿大渥太华，这个激励 incidentally 跟Brex没有任何关系。我的问题要回到关于智力资本的讨论，特别是也许","ans":"如果整体上企业能持续赚取很高的净资产收益率，而利率维持在当前水平，那我们就不处于估值过高的时期。但如果这些回报被证明不可持续，或者利率走高，那我们会回过头来说这是个高点，但至少在一段时间内。不过我们对此没有概念，我们基本上真的不去想它，因为我们不知道。你知道，我们的工作是专注于我们能知道并且能带来改变的事情。","kind":2},{"y":1997,"at":"05:05:33","ask":"你好。我叫John Zavanovich，来自加拿大渥太华，这个激励 incidentally 跟Brex毫无关系。我的问题要回到刚才关于智力资本的讨论，特别是也许","ans":"对，对。我是说，这完全不特别，我是说，如果未来10年股票年均回报4%，我们一点都不会意外。不是说一定会这样，我们也不知道具体数字，但那是，那不会是个令人意外的结果，也不会特别困扰我们。Charlene？","kind":2},{"y":1998,"at":"00:44:43","ask":"是的。早上好，Buffett先生，Munger先生。我叫Patrick Brown，来自北卡罗来纳州夏洛特，我一直在看美国银行业过去几年的净资产收益率涨了不少，而且那个","ans":"一个有趣的问题是想想看，如果你有500个Jack Welch，克隆出来，经营着堡垒，经营着所有Fortune 500公司，美国企业的净资产收益率会比现在更高还是更低？我是说，如果你有，我是说，如果你有500个了不起的竞争者，他们都可以很理性，但那不，而且他们会很理性，他们会很聪明，他们会一直努力做所有正确的事，但有一种自我抵消的效应。就像有500个国际象棋高手或者500个桥牌高手，如果他们聚在一起打比赛，你还是会有很多输家。所以完全不清楚，如果所有美国管理层都大幅提升，先不算对外国企业的竞争，净资产收益率会不会好很多。他们很可能把东西往下压。","kind":0},{"y":1998,"at":0,"ask":"我叫Pill Yoon，来自加州洛杉矶。Warren Buffett先生，Trudeau先生，我是非常敬佩你们两位的人之一。我有两个问题。第一个问题，您对世界金融商业环境的看法，在","ans":"所以我们说，什么是重要的，什么是可知的，在这两类之内的东西里，有哪些能转化成对Berkshire有用的行动？而真的，有些重要的话题，Charlie和我根本不懂，所以我们就不去想它们。所以对于未来10年商业或竞争格局会是什么样，我们有自己的看法，但我们就是不行。我们确实认为我们对Coca-Cola十年后会是什么样知道一点，或者Gillette十年后会是什么样，或者Disney十年后会是什么样，或者我们的一些运营子公司十年后会是什么样。","kind":0},{"y":1998,"at":"01:58:15","ask":"早上好，Munger先生和Buffett先生。我叫Prakash Puram，来自明尼阿波利斯。科技板块里似乎有很多很好的价值，符合你们的大部分标准、理念和投资原则，除了","ans":"嗯，答案是不，而且可能挺遗憾的，因为我一直是Andy Grove和Bill Gates的仰慕者，你知道，我希望我能把这份仰慕转化成投资。我不知道那个世界10年后会是什么样，我不想玩一个我认为别人比我更有优势的游戏。我就算把所有时间都花在思考科技上，在看那些生意的时候，我也排不上全国第100个、第1000个、第10000个最聪明的人。所以那是一个七八英尺高的栏杆，我跨不过去。有人能跨过去，但我跨不过去，不管我怎么训练，我都跨不过去。","kind":0},{"y":1998,"at":0,"ask":"早上好，Munger先生和Buffett先生。我叫Prakash Puram，来自明尼阿波利斯。技术领域似乎有很好的价值，符合你们的大部分标准、理念和投资，除了……","ans":"所以，有人会赚很多钱这件事，其实不困扰我。我是说，可能有人在可可豆上赚很多钱，但我对可可豆一无所知，而有一大堆领域我都一无所知。所以，你知道，祝他们顺利。而且我觉得，如果Charlie和我——如果你——如果有可能让Charlie和我花一年时间研究它，就能变得信息足够充分，让我们的判断比别人更好，那会是一个非常合理的批评。但那不会发生，那会是浪费时间。对我们来说，去打那些容易打的球要好得多。Charlie？","kind":0},{"y":1998,"at":"02:55:15","ask":"下午好。我叫Matt Lovejoy，来自肯塔基州列克星敦，很高兴我不是顾问。先生，Buffett先生，我有个问题，关于您的运营管理风格。在我看来，主要、主流媒体……","ans":"对，我们把钱集中管，其他一切基本都下放。但是，我不知道你在这儿有没有见到他，举个例子，Al Ueltschi就在这儿。他1951年创办了FlightSafety，他今年在模拟器上花多少钱我不知道，但很容易就是1亿美元左右。他就是……我就算跟他花上几个小时，我在怎么分配这笔钱上的知识，连他的百分之一的百分之一都加不上去。我是说，那就太荒唐了。那是浪费他的时间，也是我的一种傲慢。我完全不担心Al怎么分配钱，而且跟我们大多数业务比，那是一个资本密集度异常高的业务。","kind":0},{"y":1998,"at":0,"ask":"我叫Henry Allen，来自纽约Mamaroneck。我的问题有点微妙。跟我家人和继承人有关，而不是我自己，因为我比你们两位先生大几十岁。你们一直非常坦率地谈……","ans":"我是说，它，每年应该有合理数量的交易可以进行，而不会实质性影响股票价格，或者股票价格不是因为某种不自然的原因被撑着。所以我不真的担心那个。我们有过，我们有过一个股东大约一年、一年半前去世，持有公司0.75%的股份，举个例子。那在，我不知道，六周左右卖掉了，当时他们从出售中筹到了大约2.5亿美元。我不担心那个。我担心的是……我是说，我不担心，但关键因素是，这些生意的前景如何？如果这些生意值钱……股票交易所有各种各样的公司，都是完全体面的生意，一年有30%或40%的股票换手，如果Berkshire一年有10%换手而不是现在的3%，价格不应该差很多。Charlie？","kind":1},{"y":1998,"at":0,"ask":"第二个问题跟Ben Graham有关。随着几十年过去，当他没法再以低于净净值买股票时，他改变了自己的估值标准。他改变标准是因为环境变了。那么，这……","ans":"所以，说到十年后世界会怎么运转，或者股票和生意的回报会怎样，你知道，我不，我不知道会有哪些变量影响这些。显然现在人们非常看好，认为那些回报，或者类似那些回报，会继续下去。但我不，我不会在做出这种预测时，依赖冷战已经结束这个事实，或者世界上任何政治或经济发展。我不知道怎么预测美国企业未来的盈利。","kind":2},{"y":1998,"at":"03:53:52","ask":"下午好，Buffett先生和Munger先生。我叫Jack Sutton，来自纽约市。我有两个问题。日本股市被比作1974年的美国市场，日本股票以非常低的","ans":"现在说第一个问题，原因是，我不知道确切数字，日本股票以比美国股票更低的市净率出售，只是因为日本公司的账面回报率远低于美国公司，而盈利才是决定价值的，不是账面价值。账面价值不是我们考虑的因素。未来盈利才是我们考虑的因素。正如我们今天早上早些时候提到的，很多日本公司的盈利一直很差。现在如果你认为日本企业的净资产收益率会大幅上升，那你会赚很多钱，我是说，你是对的，你会在日本股票上赚很多钱。但净资产收益率，日本企业的净资产收益率一直相当低，这就使得低市净率非常合理，因为盈利是相对于账面价值来衡量的。","kind":0},{"y":1998,"at":0,"ask":"我是来自北卡罗来纳州Cedar Mountain的Yvonne Edmonds。我有个具体的问题，但不是无关紧要的。你们，你们经常把Berkshire Hathaway的表现跟S&P 500做比较，这很有帮助也很有意思……","ans":"所以我想你会发现，我不知道你会发现在Berkshire和S&P之间的具体相关性是什么。你会发现很多相关性，嗯，你可能不会发现那么多。你会发现它跟可口可乐和少数几只这样的股票之间的内在价值关系。但我真的不觉得那对将来是特别有用的信息。我们不反对，任何人想算就算，但这对我们来说不会有什么用处。如果我们觉得它对我们不该有用，我们就不想把它作为可能有用东西提供给股东。我们确实觉得S&P的年度计算有些意义，因为那是人们投资的替代选择。他们不需要我们来买S&P。所以除非长期来看我们比它有某种优势，你知道，我们在贡献什么，我们的管理层增加了什么价值？","kind":0},{"y":1998,"at":"04:11:30","ask":"我的问题跟你早些时候提到的有关，就是公司每年必须把一定数量的现金再投资到业务中，只是为了维持现状。如果可以说最好的企业是那","ans":"对。然后Charlie和我坐在USAir里，决策一个个来了，问题就是，你知道，你买不买Eastern Shuttle，或者不管是什么，你的钱快用完了，但为了玩这个游戏、保持客流，比如转机乘客什么的，你就得不断做这些决定，要不要在某个机场再多花1亿美元。这些决定很痛苦，因为 again，你没有真正的选择，但你也没有真正的信心，相信这些选择会转化，或者说没有选择，会在以后转化成真金白银。所以一种游戏就是逼着你往桌上推更多的钱，却不知道自己拿的是什么牌，另一种，你有机会推更多钱进去，同时知道自己一路拿的都是赢牌。Charlie，我们为什么买USAir？","kind":4},{"y":1998,"at":"04:18:24","ask":"我叫Hubert Voss，来自加州圣巴巴拉。今天早上早些时候你评论说，如果市场下跌，你会花更少时间上网，因为你会很忙。而这进一步印证了","ans":"嗯，你说得对，我们好几个月都没在股票里找到任何值得出手的东西。至于等多久的问题，我们无限期地等。我们不会为了买而买。只有当我们认为买到的东西有吸引力时，我们才会买。而且，顺便说一句，如果东西便宜5%，便宜10%，那也不会有什么实质改变。所以我们不知道那个时期什么时候结束，我们不知道是否至少……所以我们不知道那个时期什么时候结束，我们不知道免费 tonic 会不会停留在现在的位置，它们现在的位置，但它们即使……也一点都不让人流口水。所以如果回报率停留在原地，我们不会觉得自己错过了什么特别的东西，因为如果这些水平没问题，在我们看来，它们从这里也不会产生很好的回报。","kind":0},{"y":1998,"at":0,"ask":"您能否解释一下，在现金流估值过程中，既然您对所有公司使用相同的折现率，您如何区分不同类型的业务？比如，在估值Coke和GEICO时，您是怎么……","ans":"我们看风险，基本上把它当作一个——不，是一个通行/不行的阀门，用来审视未来的业务。换句话说，如果我们觉得我们根本不知道未来会发生什么，那并不意味着它一定有风险，只是意味着我们不知道。对我们来说它算是有风险的。对另一个懂这个业务的人来说，它可能没风险。那种情况下，我们就放弃。我们不试图去预测那些东西。我们不会说，好吧，我们不知道未来会怎样，所以我们就用9%而不是7%来折现，用某个我们自己都不知道的数字。那不是我们的做法。我们觉得，一旦它通过了一个门槛测试——也就是我们对它相当有把握——那么同样的折现因子就倾向于适用于所有东西。我们买业务的时候，尽量只做那些我们相当有把握的事。","kind":0},{"y":1998,"at":0,"ask":"是的。我叫Steve Check，来自南加州。我的问题跟质量与价格有关。我来过三次年会，每年都听到关于可口可乐的赞美，但就我……","ans":"我只能说，我们喜欢付一个舒服的价格，这在一定程度上取决于利率是多少。过去一年里，我们没找到我们喜欢的那类生意的舒服价格。我们也不觉得它们不舒服到想卖掉，但那不是我们会……我们加过一次可口可乐，大概，我不知道，五年前左右，可以想象我们还会再加。更可以想象我们会又加又减，但我们对大多数生意都是这种感觉。去年我们确实做了一个决定，认为债券相对有吸引力，我们削减了一些持仓，清掉了一些小的持仓，以便在债券上做一个更大、更大的承诺。Charlie？","kind":3},{"y":1998,"at":0,"ask":"下午好，芒格先生，Public先生。我叫Patrick Byrne。我是股东，从俄亥俄州辛辛那提来，今年又来问个问题，看能不能让你们俩在某件事上意见不一致。","ans":"所以，关于怎么改进这个系统，我不知道答案。你看，我读过一些做过的实验，但我确实相信，首先，你有一个好的公立学校系统，就像我们在Omaha这样，你竭尽全力去维持它，这样富有的祖父母或富有的父母就没有动力说，你知道，我喜欢平等的理念，但我更爱我的孙辈和我的孩子，所以我要把他从公立学校系统里拽出来。然后你就得到这种外流，留下的只有那些负担不起这种选择的人。","kind":0},{"y":1998,"at":"05:15:42","ask":"在你对McDonald's的描述中，你感觉McDonald's里面埋着一桩很棒的生意，还有两桩好生意混在里面，问题出在房地产和运营业务上","ans":"嗯，我的猜测是，我不了解细节，但我的猜测是，全球23000个门店，在这个节点上把房地产业务从特许经营业务中分离出来，我觉得会极其困难。我认为他们本可以走另一条路。我不是说那会是更好的路。事实上，我认为他们走对了路，拥有并控制了这么多房地产。但我觉得，我只是觉得问题会非常可怕。当然你不会想卖掉再租回来，因为在我看来，那样做最终不会得到更多价值，把它分拆成一个房地产信托什么的，在100多个国家运营，还有所有这些特许经营安排，我觉得会是一个巨大、巨大的问题。我自己可不想去碰它。","kind":2},{"y":1998,"at":0,"ask":"下午好。我叫Fred Strossheim，就是奥马哈本地人。我有个关于你们收购方法的问题，我读年报时对你们收购Star Furniture很感兴趣。……","ans":"其余的，人们做它可能是为了自我保护。我觉得太多次他们把它当拐杖，只是为了把那个他们反正就想做的交易做下去。当然所有专业人士都知道这一点，所以相信我，他们回来的时候带着尽职调查，不管该不该有。我们不太喜欢那个。我们这些年做了多少交易我不知道，但我想不出有哪一件跟传统的尽职调查有关系。","kind":0},{"y":1999,"at":0,"ask":"我叫Tim Speer，来自英国Hertfordshire。我在想Ben Graham的书《The Intelligent Investor》里，他花了前几章讨论市场水平以及它是否安","ans":"那绝不是任何形式、任何意义上的股市预测。我们完全不知道市场今天是涨、下周涨、下个月涨还是明年涨。我们确实知道的是，我们只会买那些我们认为就Berkshire得到的价值而言合理的东西。当我们找不到东西时，钱就堆起来，当我们找到，当我们确实找到东西时，我们就扑上去。但股市，我不知道有谁成功过，真正赚了很多钱，靠预测市场本身的走势。我知道很多人做得好，靠挑选企业并以合理的价格买入，那就是我们希望做的。Charlie？","kind":0},{"y":1999,"at":0,"ask":"早上好。我叫Matt Haverty，来自堪萨斯城。20年前中国在其境内放开了资本主义。从那以后，我相信它从这个经济体系中获得的好处比任何主要国家都多——在它的——","ans":"嗯，我对他们了解不多，但我，但当然，如果我能买到那些净资产收益率20%的公司，而且有承诺、有希望继续做到这一点，同时还能把大部分资本重新投入，而且它们以五倍市盈率出售，并且我对盈利质量感觉良好……我猜这样的不多，就那些符合你所说的伯克希尔要盈利性参与的标准的公司而言，以及你是否能从美国买到所有这些公司，我觉得会有很多，很可能会有很多问题。","kind":2},{"y":1999,"at":"02:11:01","ask":"早上好，Buffett 先生。我叫 Jean-Philippe Cramers，从英国伦敦来。我有个关于 Coca-Cola 的问题。第一部分是，您是否担心 Coca-Cola 的盈利可能继续……","ans":"嗯，关于美元的强势，也就是说利润和外币换不成那么多美元，我们，我，我们对此没什么强烈的看法。我是说，如果我们对美元兑日元、兑马克、兑欧元、兑英镑或者别的什么货币的走势有强烈看法，你知道，我们完全可以通过实际买卖大量外汇来表达这些观点。我们不知道美元会往哪个方向走。","kind":0},{"y":1999,"at":0,"ask":"我叫Esther Wilson。我住在内布拉斯加州南苏城。我丈夫和我在我们80出头的时候会有一些新的钱。我们有一个50岁的女儿，她会继承我们所有的一切。我的问题是","ans":"就像有人说的，纽约的律师比人还多。我是说，确实，你往前走会遇到某些冲突和术语问题，如果你说利润能比GDP增长得还快。所以如果你真的处在这种情况下，企业利润多年来最好的情况也就是增长4%或5%，那怎么可能会合理地认为股票——股票就是企业利润的资本化——能以每年15%增长呢？我是说，说白了，这就是胡说八道，人们在股票上不可能平均做到15%或者类似的水平。","kind":2},{"y":1999,"at":0,"ask":"我叫Merritt Belisle，来自德克萨斯州奥斯汀。公司对Washington Post Company有大量投资，该公司拥有许多服务非主要都市区的有线电视系统，以及最近一项投资——","ans":"TCA不是——Lou Simpson在GEICO管理一个独立的投资组合，股票组合。所以我从来没读过TCA Cable的年报。我对它一无所知。如果他还有的话，那是Lou在GEICO为GEICO做的投资，完全不属于我的管理范围。这一点我应该提一下，因为媒体时不时会捡起某个消息说伯克希尔，或者有时候说我在买X、Y或Z。有时候那是真的，但有时候不是真的，因为申报是以与我们相关的各种其他实体的名义做的，而我对它们一无所知。","kind":3},{"y":1999,"at":0,"ask":"","ans":"我是说，如果你遇到通缩，那意味着，你知道，资本在升值，所以在通缩下，你需要低得多的名义资本回报率才能处于和通胀条件下相同的位置。所以通缩，在其他条件不变的情况下——而实际上并不是不变的——对投资者是好事，因为，你知道，货币的价值在升值，货币的购买力在升值。但它也会有其他后果。我不认为这很可能。我不是——我在宏观预测方面完全没有什么好记录，而且我，如果它真的发生了，说实话我不知道影响会是什么。查理？","kind":0},{"y":1999,"at":0,"ask":"我知道您不喜欢预测股市，但也许您敢预测一下有效市场理论的拥护者和价值投资者之间这场辩论的演变。您觉得会不会有一天……","ans":"我会说，我会说过去一二十年里，它已经在相当程度上名誉扫地了。我是说，你现在听不到人们像 15 年、20 年前那样谈论它了。但市场总体上在大多数方面还是相当有效的。我是说，很难找到，很难找到定价无效的证券。有些时候相对容易，但比如现在，就很难。我，我不确切知道它在商学院里还有多少神圣教条的地位。我确实有个印象，我到处跟商学院的人聊，它被重视的程度远远不如以前了，不像 15 年、20 年前那样被当成某种不容置疑的教条。","kind":2},{"y":1999,"at":0,"ask":"我知道您不喜欢预测股市，但也许您敢预测一下有效市场理论的拥护者和价值投资者之间这场辩论的演变。您觉得会不会有一天……","ans":"但你要是找一个金融学博士，让他给一家企业估值，他就犯难了。他要是估不了值，我不知道他怎么投资。所以，干脆接受有效市场理论要容易得多，说这都无所谓，反正所有人对什么都了如指掌，琢磨给企业估值根本没意义，市场是有效的，市场把一切都定得完美无缺。那门课大概第二天，我是说，对，对，第一天，你走进去，你说，你知道，一切都定得完美，定得完美，下课。所以我，这，这让我困惑，但我鼓励你去找定价无效的。第三区。","kind":0},{"y":1999,"at":0,"ask":"巴菲特先生和芒格先生，非常感谢你们的热情款待。不好意思，我叫Yvonne Edmonds，来自佛罗里达州圣彼得堡。也谢谢你们这么好心花这么多时间回答问题","ans":"我从来没有，我想我在学校只上过一门保险课。我什么都不记得了。我连教科书是什么都不知道。那对我毫无价值。所以我从来没有真正有任何保险方面的背景。你知道，家里没人做保险生意，直到我和Davy聊过，我真的，这压根没在我脑子里出现过。我去那里的唯一原因是我，我的英雄Ben Graham被列在《Who's Who》里，说是Government Employees Insurance的董事长。就是说，如果他当时是，你知道，他同时也是旧金山Market Street Railway Company的董事长。幸运的是，我去了GEICO，说要去看看Market Street Railway Company，那个更近。但我自己关于保险的教育，就是来自读大量的、大量的报告。","kind":4},{"y":1999,"at":0,"ask":"我叫 Mike Thiele，来自新泽西州 Summit。您能不能再谈谈 Berkshire Hathaway 回购股票的问题？我们今天已经听到您说过 Berkshire 的价格……","ans":"1974 年 Berkshire 卖 50 美元的时候，我可能觉得它便宜，但我同时也在看整个 Washington Post Company 卖 8000 万美元，而我认为它 clearly 值 4 亿美元，我当时并不觉得 Berkshire 那时候被低估的程度能跟 Washington Post Company 比。这种情况在不同时候都成立，有些时候我觉得 Berkshire 被低估了，甚至显著低估了，但同时我又找到了别的东西，我觉得那些更有吸引力。而且，而且，而且就像我说的，很多次我都错了。","kind":4},{"y":1999,"at":0,"ask":"我还有一点，一，一个进一步的评论。你提到了30，30倍，那个B股是A股的价值。好吧，如果我把5月23日、4月23日每股2,474美元的价值乘以30，我得出74,220，但是那个——","ans":"而且，但你不能买，你不能买30股B股然后转换成一股A股。所以我不确定，在你实际买入的那天，如果你买的是B股——听起来你确实是——在你实际买入B股的那天，我不知道你买的时候是不是折价。去年大部分时间它没有折价出售。今年大部分时间它是折价出售的。有时候它会平价出售，有时候它会折价出售。查理？","kind":2},{"y":2000,"at":0,"ask":"我叫Thomas May。我10岁，在加利福尼亚州Canfield上基础学校。我已经做了两年股东。这是我第三次参加年会。我的问题是。我知道你们不会投资科技","ans":"我们不，我们没有，你知道，不买科技公司不是什么宗教信仰。我们就是不买。我们从来没找到过一家，按传统定义，我们从来没找到过一家让我们觉得对十年后这门生意会是什么样了解得足够多、能理性决定现在该付多少钱的公司。换句话说，我们一直没能找到一家公司，让我们觉得知道那片灌木丛十年后会是什么样、里面会有多少只鸟，从而知道我们今天能放弃多少只鸟去参与那个未来。没有一家，这，它……会有很棒的东西，就像Charlie那么生动地解释的，很多这类公司会演化出很棒的东西，但我们不知道怎么做出那个决定。","kind":0},{"y":2000,"at":0,"ask":"我叫格雷格·布莱文斯，来自肯塔基州巴兹敦。我有个关于内在价值的问题。这来自您今年年报里的一些话。在里面，您描述了阿吉特非凡的能力——","ans":"See's Candy的城堡周围有一条很棒的护城河。而查克·哈金斯从1972年接手以来，每年都在把这条护城河加宽。他往护城河里扔鳄鱼、鲨鱼和食人鱼，别人想游过去攻击城堡就越来越难，所以他们就不来了。你看，从1972年起，福雷斯特·马尔斯试过，用Ethel M，我不知道，大概20年前吧，我都不愿去想他花了多少钱去试，而他是个非常有经验的企业家。","kind":4},{"y":2000,"at":0,"ask":"我叫Greg Blevins，来自肯塔基州Bardstown。我有一个关于内在价值的问题。它来自你们今年年报里的一些评论。在里面，你们描述了Ajit的非凡技能","ans":"所以我们想它们的时候，我们想的是那个护城河、保持它宽度的能力以及它不可被跨越，作为伟大企业的主要标准。对我们的经理们，我们说我们希望护城河每年都加宽。你知道，那不一定意味着今年的利润比去年多，因为有时候不会。但如果护城河每年都在加宽，这门生意就会做得非常好。当我们没有，当我们看到护城河在任何方面都很脆弱的时候，回到你的问题，那就是风险太大了。我们不知道怎么去评估那个，所以我们就不碰。我们认为我们所有的生意，几乎所有的生意，都有相当不错的护城河，而且我们认为经理们在加宽它们。Charlie？","kind":0},{"y":2000,"at":0,"ask":"我叫休·史蒂文森，来自亚特兰大的股东。我的问题涉及公司在通用再保险收购之前和之后不久的活动。我记得你曾说过，在保险业，几乎所有的意外","ans":"我是说，我们有些业务条线，是故意——我是说，要是想把它压到零那才是疯了，因为以1%或2%的回报拿着两倍的钱，远比以0%的回报拿着一半的钱要好得多。但我们完全承认，我是说，Unicover是个意外，不过，我不知道在我们做保险这33年左右的时间里，我遇到过多少意外。顺便说一句，其中一个意外，你知道，反倒给我们带来了难以置信的好处。","kind":0},{"y":2000,"at":0,"ask":"我叫休·史蒂文森，来自亚特兰大的股东。我的问题跟公司在收购Gen Re之前和之后不久的一些活动有关。我记得你曾说过，在保险业，几乎所有的意外","ans":"所以这是一个招引欺诈的领域，而且经常是同一批人一次又一次地回来。这让我很惊讶。所以我要说，在任何十年里，我们在保险上都会遇到一两个意外。几乎没法避免。我们应该尽量把它降到最低。我们确实在尽量降低。但我可不敢拿命打赌说Unicover那种事我们不会再见到。它们总是有那么一点点不一样，所以没被看出来，或者链条上某个人没收到信号。但我不知道，查理，你不觉得我们还会再见到一个吗？","kind":2},{"y":2000,"at":0,"ask":"巴菲特先生，我想一开始就用一根湿面条抽您和查理十下。不是因为1999年，不是因为您的净值或我们的净值发生了什么，而是因为您把您的股东给宠坏了","ans":"你看，外面有一大堆人说自己能做这个，也许他们能，也许他们不能，也许你能看出哪些人能哪些人不能。我们唯一知道的赚钱方式就是试着去评估企业。如果我们评估不了一家碳钢公司，我们就不买它。这不代表它不是一笔好买卖。不代表它不是以远低于价值的价格在卖。只是说明我们不知道怎么评估它。你看，如果我们评估不了在巴西建个化工厂或者别的什么合不合理，我们就不做。","kind":0},{"y":2000,"at":0,"ask":"巴菲特先生，我想先给你和查理用一根湿面条抽十下。不是因为1999年你们的净资产或者我们的净资产发生了什么，而是因为你们把你们的股东给宠坏了","ans":"所以我们完全是从评估净资产的角度来看这个生意的。我们算出来1999年我们的净资产涨了非常非常少，就一点点。而且我们觉得不管股票卖什么价，都无所谓，因为我们看的是生意本身。我们真的就当这只股票没有任何报价来看它，因为我们不知道股票会怎么走。我们，如果我们做对了，如果生意的价值以合理的速度增长，股票早晚会跟上。但它不一定每周跟、每月跟、每年跟。","kind":0},{"y":2000,"at":0,"ask":"所以我很高兴看到现在事情回到了正轨。我的问题是，您投资的很多公司，比如Coca-Cola和Gillette，似乎在美元疲软、利率下降的时候表现更好。那——","ans":"我们其实不太想这个，因为，就拿汇率来说，你看看日元过去的走势，你知道，从二战以来，从多少来着，360，一路跌到多少，低的时候70几，然后，你知道，又回到140几，现在，我不知道，105还是多少。我是说，那些波动是巨大的。但说到底，我们更感兴趣的是日本会不会有更多的人喝Coca-Cola。长期来看，我们预测这个比预测日元走势更在行。","kind":0},{"y":2000,"at":0,"ask":"你们好，先生们。我叫丹·希恩，来自加拿大 Toronto。首先，我想感谢你们这个周末。它对我越来越重要，因为越来越难找到理性的","ans":"所以并不是说我们看到了——因为市场上某个特定领域也许有这种投机狂热，我们并不认为那会在其他地方造成难以置信的低估。那里发生的事可能会导致低估，你知道，几年之后，也可能不会。我不知道。但并不是说你能找到价值翻倍左右的东西，因为坦白说，到处流动的钱太多了，如果你找到这样的东西，很可能很快就会被某些收购类型的买家纠正掉。","kind":2},{"y":2000,"at":0,"ask":"下午好，巴菲特先生，芒格先生。我叫鲍勃·奥多姆，来自华盛顿州西雅图。首先我想说，来到奥马哈真是太好了，这里的人让我感到很自在。我希望你们能","ans":"我看到各种各样的人离开公司，他们赚了巨额的钱，而没人愿意以一半、四分之一甚至十分之一的价钱雇他们。你知道，我是说，这不是市场体系。CEO薪酬不是市场体系，它不受市场检验。我不知道你具体能对此做什么，但我，这似乎并不太困扰股东，那些有能力改变它的股东。","kind":0},{"y":2000,"at":"02:40:54","ask":"我是来自堪萨斯州普雷里村的黛安·瑞安。这是我第四年参加股东大会，我想说每年我都觉得自己多学了一点。今年我的问题是，你觉不觉得","ans":"嗯，黛安，我，我在宏观问题上不行，过去大概20年我对通胀过度担心，这已经证明了我有多不行。幸运的是，我在这件事上错了，也没造成多大差别。所以评估全球价格长期会怎么走，我真不觉得我的判断比你强多少。我的，我的看法是世界不会走向通缩。但是，你知道，我，我没，我过去的经济预测也没挣到任何星星。","kind":2},{"y":2000,"at":"02:51:08","ask":"巴菲特先生，芒格先生，我叫Norman Rentrop，来自德国波恩。非常感谢你们昨天和今天这么耐心地倾听、回答和分享。我从1992年起就是股东，而且……","ans":"这是个很好的问题。我不知道该怎么确切回答。也许查理在我磕磕绊绊说的时候会想到答案。但我真的，我觉得我自己能做得挺好，可我不知道有什么办法能给别人一套问题去问，或者，你知道，我不知道怎么告诉别人，不知道怎么告诉别人用那些标准去挑经理人。他们是爱这门生意还是爱钱？这非常非常重要。我是说，这很关键，因为它，你看，我们一直都能看到。我是说，你身边就有那种爱钱的人，你在上市公司里看到他们做些我们不想沾边的事。而另一方面，他们爱的是这门生意。","kind":0},{"y":2000,"at":"02:59:21","ask":"对。我不是，我不是想激你去做。我很高兴你没做，因为上次我可能就心脏骤停了。一旦我会等。所以，但所以你的预测是你并不……","ans":"这不全面。对，我看每一门生意，我都会想它的经济性。你知道，这已经刻在我骨子里了，也刻在查理骨子里了。所以不是说，如果，如果我跟Andy Grove在一起——其实1968、69年我在Grinnell的时候就认识Bob Noyce了，那时候他们刚创办Intel。我，当他跟我聊创办Intel的事，或者任何人跟我聊一门生意，我都会想它的经济性。我，我，我们聊个三四分钟，我就会想它的经济性。但我，所以不是说我们把阀门关了。只是我们，我们走不下去。我们不知道它，它将来会是什么样。而且，你知道，生活里有很多东西，我们很多人就是理解不了。","kind":0},{"y":2000,"at":0,"ask":"正如你们两位早些时候说的，我们正处在一个财务上特别不寻常的时期。你忍不住会听到那些灾难场景，关于全球金融市场即将崩溃，关于重大自然","ans":"这个世界上会有一些巨大的意外，这毫无疑问，但我不认为押注某一个具体的意外是个聪明的策略。事实上，我们，我们通常是跟这种人对着押，押超级灾难不会发生。我们知道未来50年加州会发生7.0级或以上的地震。我们不知道会在哪儿、什么时候，之类的。如果明天就发生，我们愿意赔很多钱，因为人们确实担心灾难，而在这个情况下，有保险价值，这完全合理。但在我们看来，这根本不是度过经济生活的方式。查理？","kind":0},{"y":2000,"at":0,"ask":"我是约翰·贝利，来自马萨诸塞州波士顿。你在年报里评论说，GEICO去年的营销费用中只有一部分是维持业务所必需的。这似乎触及了所有者收益的核心","ans":"我在报告里用GEICO的例子，是因为它足够大，对股东来说有意义。我是说，我们一直在做各种事情，短期内花钱，我们认为长期会产出远超相称的价值，但规模不像我们目前在GEICO做的这么大，我们可能还会加大那个规模。所以我觉得把这些数字摆出来很重要，尽管我没法精确。当我说，你知道，维持费用可能是5000万美元时，我并不确定那个数字。可能是7000万，也可能是3000万。你知道，也许我偏差得比那还多。但那是我最好的估计，我认为股东有权得到我最好的估计，他们也有权知道，除了维持成本之外，我们为了未来建设业务花了多少钱，而这些我们显然没有在资产负债表上资本化。","kind":1},{"y":2000,"at":0,"ask":"你好，我叫詹姆斯·阿姆斯特朗，来自宾夕法尼亚州匹兹堡。感谢你们接待我们。我想请您谈谈再保险业务，以及未来10年或20年它可能会是什么样子。在Berkshire，我们——","ans":"然后我们有一个巨大的态度上的优势，就是我们完全不需要——完全不需要——明年写出比今年更多的业务，或者同样的量，甚至接近今年的量。我们没有，Berkshire Hathaway根本没有业务量目标，而大多数保险公司不是这样的。我们按结果实际发生、按我们看到的样子来报告，我觉得这也给了我们一个优势，能对业务的各个方面保持现实。我们背后有巨额资本，所以我们可以接下大块有吸引力的业务，全部留在自己账上。所以我们在这个业务里有很多优势，这些会转化成比其他人更好的结果。我不知道好多少，我也不知道其他人会得到什么结果，但我们在业务里的优势不是微不足道的。","kind":0},{"y":2001,"at":0,"ask":"我叫Joseph Lapray，来自明尼苏达州明尼阿波利斯。近几年，烟草公司因为推销他们那些不健康但非必需的产品，被迫支付了大笔赔偿。我的问题有两部分……","ans":"但产品责任总体上对原告律师来说是一块肥沃的田地，而且它……我们在收购企业时是有意识的，我们放弃过一些企业，就是因为担心产品责任的潜在风险。除非有某种立法上的解决办法，我觉得你会看到越来越多的GDP流向赔偿判决。至于会不会有……会不会有立法上的改变，我不知道。但它，你知道，这是个大领域，那种彩票式的吸引力太大了，因为如果一个律师能赌上不多的时间，甚至是相当合理的时间，潜在回报能有一千万、两千万，有时候甚至几亿美元，你知道，那可是一张不错的彩票。","kind":2},{"y":2001,"at":0,"ask":"早上好。我是内布拉斯加州滑铁卢的Most Spins。你经常说价值和成长是同一枚硬币的两面。能不能详细说说？还有，你更偏好一家卖得便宜的成长型公司……","ans":"所以如果你告诉我你拥有一门要长到天上去的生意，那是不是很棒，我不知道它棒不棒，直到我知道那种成长的经济性是什么，你今天得投进去多少，以及你今天投进去以后将来能收回来多少。经典的例子，还是航空业。航空业从——你知道，从Orville起飞那会儿起——就一直是成长型行业。但它的……成长是它身上发生过的最糟的事。对美国公众来说是好事，但成长对航空业来说是诅咒，因为越来越多的资本以不够的回报投进了这个行业。","kind":0},{"y":2001,"at":"01:08:49","ask":"谢谢您回答我的问题。我叫Frank Jurvich，来自安大略省伦敦市。很高兴看到这么多年轻人提问。我今年甚至把我自己11岁的孩子Matthew也带来了。我首先想","ans":"嗯，谢谢。我觉得你也该给你妻子再买一枚戒指。不过……嗯，谢谢。我们其实，早在……我不记得是1980年年报还是哪里，但至少20年前，我们就说过，我们认为保险长期来看会是我们最重要的业务。我们当时没想到它会变得像现在这么重要。但我们一直觉得那是……我们会做很多业务，但保险很可能会是我们最大的业务。现在按员工人数算它不是我们最大的业务。按收入算它是我们最大的业务，我们希望它随着时间变得大得多。","kind":2},{"y":2001,"at":0,"ask":"谢谢回答我的问题。我叫Frank Jurvich，来自安大略省伦敦市。很高兴看到这么多年轻人提问。今年我甚至把我自己11岁的孩子Matthew也带来了。我首先想……","ans":"我们……我们试着看有什么送上门来。我们试着把整个金融领域扫一遍。我们试着看有什么送上门来，找那些我们看得懂的东西，那些我们觉得有持久竞争优势的，管理层我们喜欢的，价格也合理的。而且，你知道，两三年前我们根本不知道，你知道，我们会成为世界上最大的地毯公司、宽幅地毯公司的87%的股东。但它……你知道，我们就是不……我们不计划这些事。","kind":0},{"y":2001,"at":0,"ask":"我叫Charlie Sink，来自北卡罗来纳州。Buffett先生，您去年在Fortune杂志上的文章非常精彩。我在想，嗯，我想知道您对美国企业利润率、回报","ans":"我觉得特别有意思的是，当年股票的前景要好得多的时候，我甚至在70年代末还写过这方面的东西，养老基金用的投资回报假设往往在6%左右。而现在前景差多了，大多数养老基金在计算里用的投资回报是9%或者更高。我不知道它们怎么能拿到9%或更高的投资回报，但我也知道，如果他们把投资假设调低，计入收益的费用就会大幅变化，他们不想那么做。所以他们继续用我认为相当不现实的投资假设。","kind":2},{"y":2001,"at":0,"ask":"我叫Charlie Sink，来自北卡罗来纳州。巴菲特先生，您去年在《财富》杂志上的那篇文章非常精彩。我在想，我想知道您对美国企业利润率、回报……的看法","ans":"而且那还是在长期国债收益率低于6%的情况下，你知道，也许高等级公司债是7%。他们不知道在债券市场怎么拿到收益，不知道在抵押贷款市场怎么拿到。我觉得他们也不知道在股票市场怎么拿到。但如果他们改变投资假设，那就会导致他们的盈利下降。就像我说的，我不知道有哪家大公司在考虑这件事。我不知道有哪家大型精算顾问公司在向管理层建议这么做。就是，他们宁愿不去想它。","kind":2},{"y":2001,"at":0,"ask":"嗨，我叫Steve Rosenberg，来自密歇根州安娜堡。首先，我只想感谢你们两位是两位了不起的榜样。我长期以来一直很敬仰你们两位。我的第一个问题是关于……","ans":"我是说，就拿密苏里州那个角落里的New Madrid地段来说。就是那个，那是三次最大地震的区域。它们在时间上有点关联，而且在有记录的历史上，它们肯定是美国最大的三次地震。你知道，在那个巨大的地带上，有人持有多少房主保险业务、多少商业地产保险业务，据说当时发生的时候，让波士顿的教堂钟都响了，不管是什么时候，1807年还是09年之类的。所以有各种各样的风险能以巨大的方式聚合起来，而公司根本没在想这些。我是说，我不知道Freddie Mac或者Fannie Mae，比如说，是否要求他们在New Madrid方圆300英里内承保的所有房屋都必须有地震保险。但是，你知道，那种事情从来不会被人想到，直到不可想象的事情发生。但在保险业，不可想象的事情总会发生。","kind":0},{"y":2001,"at":0,"ask":"我是Chip Mann，来自明尼苏达州明尼阿波利斯。再次感谢这种开放的形式和您对我们问题的直接回答。您谈过一些你们承保的超级巨灾级别的风险。您能不能分享一下您的想","ans":"但就写一份具体合同而言，我们比世界上任何人都更大、也更快，我觉得。实际上，我们有一些能力，过去人们会把它跟去伦敦Lloyd's联系在一起。我是说，我们可以，我们现在，我不知道这些年来那些说法有多少是真的，因为我那时候不在那儿，但我们真的能在一个小时内对某件事给出答复，而别的公司一个月都不知道该怎么办。这应该是我们在世界上的一个优势。Charlie？","kind":3},{"y":2001,"at":0,"ask":"我叫Ethan Berg，来自马萨诸塞州剑桥，我想感谢你们提供的教育，尤其是年度报告。我有三个简短的问题。多年前，你写信给你的……","ans":"我是说，你真正想要的投资课程，应该是怎么给一门生意估值。这才是这个游戏的核心。我是说，如果你不知道怎么给一门生意估值，你就不知道怎么给一只股票估值。你看看现在教的东西，我觉得你几乎看不到怎么给生意估值，剩下的都是拿数字玩玩，或者，你知道，希腊字母之类的，但对你没什么用。我是说，到最后你得决定，你知道，你是要，你是要把一门生意估成4亿、6亿还是8亿，然后你拿这个跟价格比，这就是投资。我不知道还有别的什么投资，基本上，可做的。","kind":0},{"y":2001,"at":"03:17:36","ask":"Bill Graham，来自洛杉矶。Warren，你让外部股东能够理解伯克希尔的金融业务，但有一块在我看来，反正，很难理解，就是金融……","ans":"嗯，我觉得你说到点子上了，Bill。这是一门很难理解的生意，而且如果你拥有它，它都很难理解，更别说在别人的年报里读到了。我猜大多数拥有复杂或庞大衍生品业务的人，我得说大多数CEO可能都不懂。至于有多少人、多少人为此夜里睡不着觉，我不知道。","kind":0},{"y":2001,"at":"03:26:20","ask":"我叫Scott Tilson，来自马里兰州Owings Mills。先生们，你们多次说过，Lou Simpson是独立自主地管理GEICO的投资组合。是什么独特或卓越的资……","ans":"对，我觉得他能，但我希望别太快就轮到他。（笑声）Lou很聪明，很K，很谨慎，做高质量的东西，而且经验丰富。所以他确实自主管理着几十亿美元。他会买一些我根本不知道的东西，直到我看月度报表，或者有时候在报纸上读到，那没关系。你知道，他不知道我在干什么，我不知道他在干什么，偶尔我们会碰在同一只证券上，那种情况下我们买卖的时候会试着协调一下。","kind":4},{"y":2001,"at":"03:35:55","ask":"下午好。我是Claudia Fenner，来自纽约长岛，我有两个问题。第一个是，作为Gap的忠实粉丝，我想知道为什么您现在觉得Gap被低估了。第二个问题……","ans":"第二个问题我让Charlie来回答。他是我们Berkshire的消费专家。Gap很好地说明了我之前讲的事情，因为我觉得外界以为是我在Berkshire做出了买Gap的决定，实际上那百分之百是Lou Simpson的投资组合操作。我不认为我读过Gap的年报，而且我知道我从没读过Gap的年报，我对它一无所知。我是说，你可能比我了解得多得多，我希望Lou比我了解得多得多。它不是我曾经看过的一家公司。","kind":4},{"y":2001,"at":0,"ask":"下午好，Buffett先生，Munger先生。我叫Kevin Truitt，来自芝加哥。我有三个问题。Munger先生，在去年的股东大会上您说过，您不觉得成本的概念……","ans":"一旦我们跨过那个门槛，那我们要不要回购股票？嗯，显然，如果你能以远低于保守计算的内在价值的折扣价买入你的股票，而且能买到合理的数量，那就是资本的用途。再往后，问题就变成，如果你有资本，你认为你能创造超过一美元的价值，你怎么用最小的风险创造最多？这就涉及到商业风险。这不涉及到任何对波动性的计算。我不知道，See's Candy的风险是用它的股价波动来衡量的吗？因为这只股票从1972年以来就不在外流通了，这是否意味着我没法判断See's这门生意有多大风险，因为我们没有它的每日报价？不，我可以通过看这门生意、看它经营的竞争环境等等来判断。","kind":0},{"y":2001,"at":0,"ask":"下午好，巴菲特先生，芒格先生。我叫Kevin Truitt，来自芝加哥。我有三个问题。芒格先生，在去年的股东大会上您说过，您觉得成本的概念不……","ans":"现在，说回那些大点子。你看，当你有一个大点子的时候，我没法告诉你，你知道，那时候你神经系统里或者脑子里到底发生了什么。但这些年我们有过的大点子、好点子，相对来说不多。我不知道你觉得我们整个职业生涯里有过多少个，大概25个吧。每年你把Berkshire Hathaway最好的15个拿掉，你们大多数人就不会在这儿了。所以差不多每两年一个，对，每一两年一个，伙计们。有时候会一下子来一堆，像1973年和74年那样。但问题是，对我们来说，现在大真的就是大。我是说，得是几十亿美元才能在Berkshire看出点动静来。","kind":1},{"y":2001,"at":0,"ask":"是啊，你好。我是来自得克萨斯州达拉斯的James Halperin，从1995年起就是股东，我感觉很好，谢谢。这个问题跟伯克希尔的所谓永久持股有关，以及是否，当……","ans":"我不希望因为我经营一家上市公司，就让我做出那种如果你们是私营公司我会不舒服的行为。但我也觉得，你们作为股东有权知道这是我的一个个人特点，所以我把它摆出来，而且摆了20年，作为你们作为投资者、或者在成为投资者之前应该了解的东西。我确信这长期来看对我们在收购上有帮助，但这是否能在任何程度上补偿Charlie所说的、偶尔做出有利处置的机会成本，我不知道，这是我永远不会去算的东西。Charlie？","kind":0},{"y":2001,"at":0,"ask":"嗨，我叫Richard Marvel，来自华盛顿特区，我的问题跟Berkshire Hathaway的内在价值有关。您说过好几次，您希望这只股票既不被高估也不被低","ans":"我们显然不知道Berkshire的确切内在价值。如果你看那些数字，如果我们从1965年以来一直秘密记下一些数字，其中有些放到现在看会显得很傻，跟实际发生的情况比起来。但我们尽量给你们，我不觉得，我觉得Berkshire其实比大多数企业更容易估值，因为我们把至少对我们估值重要的信息全都给你们了。","kind":0},{"y":2002,"at":0,"ask":"我是John Bailey，来自马萨诸塞州波士顿，我希望我不是在让您重复保险业务的演示，但我有一个关于我们浮存金增长的问题。有一种越来越流行的分析……","ans":"而且……我们不希望人们盯着我们保险业务的增长。我是说，我们希望他们关注有智慧的增长，当我们能在GEICO或者其他什么地方做到的时候。但从商业角度来说，告诉一帮保险经理出去大幅增长，我觉得那是自杀。所以你可能会说，好吧，总部不推动，那你知道，这375亿美元怎么增长？我会说，就像我过去30多年一直会对你说的那样，我不知道。","kind":0},{"y":2002,"at":0,"ask":"早上好。我叫Tedd Friedman，来自俄亥俄州辛辛那提。您在1996年年报中说，大多数投资者会发现，持有普通股的最佳方式是收费最低的指数基金。两个……","ans":"所以我会选一个宽基指数，但我不会一次性投入一大笔。我会在一段时间内分批投，因为指数基金的本质就是你在说：“我认为美国的企业在长期内会表现不错，或者相当不错，但我不够了解，选不出赢家，也不够了解，选不出赢的时机。”这没什么问题。我也不够了解，选不出赢的时机。偶尔我觉得自己够了解，能挑出一个赢家，但不常有，而且我当然没法通过把整个名单过一遍，说这个是赢家那个不是之类的来挑赢家。所以重要的是，如果你总体感觉企业是长期放钱的好地方，那就长期投资，不要通过在某个特定时间投入一大笔来隐含地押注时机。","kind":0},{"y":2002,"at":0,"ask":"对了，顺便说一句，这不是你两年前写信的那家巧克力公司。他们大约一周前以非常低的价格被卖掉了，但这只股票还是可以买的。（笑声）","ans":"所以，你看，我还没去过他们的总部。我打算去他们总部看看。Steve，抱歉。那个……但我明白这生意是怎么回事。你不能……大多数好生意，你几分钟就能明白它是怎么回事，除非那种生意你永远都搞不懂它是怎么回事。我是说，还有些别的生意，你花上几年时间，你还是搞不明白到底怎么回事。我不知道哪家美国汽车公司10年后会做得最好。就算我花一整年时间跟Ford、Chrysler和General Motors的经销商谈，跟供应商谈，跟开他们车的人谈，我仍然不知道五年或十年后会是什么样。","kind":0},{"y":2002,"at":0,"ask":"早上好。我叫Pamela Harrington，我住在内布拉斯加州的奥马哈。我的问题是关于你对Fruit of the Loom的投资。你能不能谈谈那笔投资怎么符合你关于……的理念","ans":"Fruit of the Loom在男士和男童市场里，我不知道，大概有40%到45%的份额。这个产品配得上它的质量形象。那些很重要的零售商非常接受它，他们之前对破产前和破产初期发生的事情感到不安，但他们很喜欢店里有Fruit of the Loom这样的产品。而且它是一个非常基础的产品，生产成本非常低。所以它非常适合我们。现在管理层就只管把品牌建好、把工厂尽可能高效地运营好。工厂方面有一些调整，整个纺织行业相关的很多东西都发生过这种情况。但这是一家，绝对是一流的生意。而且，你知道，我们想在女士市场多拿一点份额。我也想在男士、男童市场多拿一点。","kind":3},{"y":2002,"at":"01:50:28","ask":"你好，巴菲特先生和芒格先生。我叫贾斯汀·方，12岁，来自加利福尼亚。这是我连续第二年来参加。我父母带我来向你们学习。我的问题不是关于……","ans":"但1959年查理和我认识的时候，是戴维斯家介绍的，他们预言，30分钟内我们要么受不了对方，要么会相处得极好。这其实是戴维斯家相当有洞察力的分析，因为这是两个在某些情况下都有支配倾向的性格。但我们就是一见如故。我们有过分歧，但43年里我完全不记得我们吵过架。而我们俩都有强烈的意见，有时这些强烈的意见还不一样。但事实是，我们在一起非常快乐。我们继续非常快乐，基本上没有什么会改变这一点。它，它也许效果更好，因为他在加州，我在奥马哈。我不知道。我让查理来评论吧。","kind":4},{"y":2002,"at":"01:55:39","ask":"你好，Buffett先生和Munger先生。我叫Kevin Truett，是来自伊利诺伊州芝加哥的股东。这个问题是问你们二位的，Buffett先生和Munger先生。Buffett先生，我从第一次读到关于","ans":"是的，我大体上同意你说的。我想说他们……我不知道一个人脱离人群的能力，比如说，我不知道这在多大程度上是天生的，多大程度上是学来的。但这是你需要的一种品质。我完全同意你，不需要高智商。我是说，你根本不需要特别聪明就能做好投资。我想说你百分之百说得对，我首先从Graham那里学到了东西，学到的方式非常非常重要，我还从Phil Fisher那里学到了一些东西，从Charlie那里学到了很多。","kind":0},{"y":2002,"at":"02:22:12","ask":"巴菲特先生，我叫Pete Danner，来自科罗拉多州博尔德市，我也想感谢你们两位为这个行业带来的一切。我听到了你对Koch……对关于可口可乐那个问题的回答。在年报里","ans":"嗯，GEICO就是个很好的例子。GEICO是家了不起的企业，绝对了不起，一天比一天更了不起，有全世界最好的经理Tony Nicely在管它。GEICO在过去20年里，至少进了三家我能想到的其他保险业务。他们搞了个Resolute Insurance，是80年代中期起步的再保险业务。那是个灾难。他们还搞了另外两个，Southern什么的，还有一个以M开头的。他们，你知道，他们……我真是搞不懂他们到底为什么要进那些。我是说，他们本来有个非常非常好的保险业务，而真正好的保险企业并不多，那两家都没搞出什么名堂。我觉得，你知道，他们后来某个时候把它们卖掉了。","kind":4},{"y":2002,"at":0,"ask":"是的。下午好，Buffett先生和Munger先生。我叫Ho Nam，来自加利福尼亚州旧金山。我有个问题跟你们刚才提到的一个话题有关，就是关于股票","ans":"这是另一个我觉得挺逗的论点，前几天刚读到，他们说，“嗯，期权太难估值了。”嗯，我用各种方式回答过这个问题，但我注意到，那个，Dell Computer，它总是有大量卖出的看跌期权，那些卖出的看跌期权会让他们花很多钱。一家公司说，“我们算不出期权的价值，所以没法把它计入费用”，同时又做着几十亿美元规模的期权交易，他们是在说，“我们在买卖几十亿美元的期权，但我们不知道怎么给这些东西估值。”这在我看来有点似是而非，有点脱节，认知失调，就像他们说的，失调。Charlie？","kind":1},{"y":2002,"at":0,"ask":"嗨，我叫Steve Rosenberg。我22岁，来自密歇根州安娜堡。能来这里是我的荣幸。首先，我只想感谢你们二位，对我以及很多人来说，你们是英雄，是正面的榜样。远不止你们的成功","ans":"而且，你知道，我只能说，我，我这辈子做过空，做空过股票，1954年有过一次特别难受的经历。而且我，我几乎想不出有什么情况，从10年后看是我错了的，但我能想出一些情况，从10周后看肯定是错的，而那恰好就是相关的时期，在那期间我的净资产在蒸发，我的流动资产变得越来越不流动，等等。所以我只能告诉你，这非常难。","kind":4},{"y":2002,"at":0,"ask":"不，我讲慢一点，免得我的口音让你们听不明白。噢，天哪。我的问题接着今天上午关于人口控制的那项决议。首先，我能不能说，我投了反对票，我想那只是……","ans":"而地球的承载能力，结果比人们过去以为的要大得多。但确实有一个跟承载能力相关的量。它也许是可以扩大的，但不是无限可扩大的。我想说的是，在人口相对于估计承载能力偏低这方面的错误，其危险远远小于人口相对于承载能力超出的危险。既然我们不知道承载能力是什么，或者一百年后会是什么，我认为总的来说，人类有理由确保人口不要超出。而且，在我看来，人口偏低根本没有什么大的代价。","kind":0},{"y":2002,"at":0,"ask":"不，我说慢一点，免得我的口音让你听不明白。哦天哪。我的问题跟今天早上提出的那个关于人口控制的决议有关。首先，我可以说我投了反对票，我想那只是……","ans":"我们在一辆叫地球的车上。我们不知道它的承载能力。我们了解到它比马尔萨斯或者几百年前某个人可能以为的要大得多，但那不代表它是无限的。而且我不……我能向你保证的一件事是，《纽约时报》几周前登的那些预测，不会是30年或50年后登的那些。而且这不是那种事后能补救的事情。我是说，你不会到处去试图故意减少人口。预防人口增长比事后试图纠正要好得多。Garrett Hardin在这方面有一些有意思的东西。Charlie？","kind":2},{"y":2002,"at":"03:45:27","ask":"我叫Bert Flossbach，来自德国科隆。首先，我想感谢两位先生所做的一切监督，还有那纯粹的投资哲学，在德国越来越多的人追随它……","ans":"嗯，我希望我知道。我唯一能告诉你的是，它会比过去20年低。但我觉得它会，我觉得跟大多数替代选择相比它会令人满意。但我不知道那些替代选择一年会产出4%还是8%。我不觉得它们一年会产出15%。而且我想我们会拿到成本很低的浮存金，我觉得我们应该能，我觉得我们也会，而且我们不断有机会以合理的条件买下企业，不是惊人的条件。我们偶尔也会遇到市场机会，过去几年我们在债券市场做的那些事甚至也有过几次机会。我们赚了巨额的钱，但我们赚了相当不错的钱。股票方面我们也会看到一些可做的事。","kind":2},{"y":2002,"at":0,"ask":"我是来自堪萨斯城的约翰·戈洛布。我基本退休了，但也在堪萨斯城密苏里大学教一门金融市场的课。我总是告诉我的学生，我在Berkshire学到的投资知识多得多……","ans":"而且说真的，像国家这样的人，你知道，用这个世界给我的方式来补偿我，根本说不通，如果我生在孟加拉国，就不会这样，如果我生在200年前，也不会这样。你知道，又是那种精灵的故事：想象一下，你知道，在我出生前24小时，旁边有个跟我DNA一模一样的人，也将在24小时后出生，精灵来到我们俩面前说：“我们现在来一场竞价，谁出让自己未来收入的百分比最高，谁就生在美国，输的那个生在孟加拉国。”你愿意拿出未来收入的百分之几来换生在美国？","kind":4},{"y":2002,"at":"04:44:57","ask":"好。第三点是，3月1日，《华尔街日报》分析或比较了审计费用，按与审计服务和其他审计服务相关的费用，对道琼斯工业指数30只股票……","ans":"这个我不知道答案，我也没看到你指的东西，但这并不完全让我意外，因为我们喜欢在乎开支的地方。而且，你知道，我从来没——我想杰克·韦尔奇在他的书里说过，没有哪家公司会因为削减开支太快而破产。当你看到管理层在花钱上大手大脚，你知道，我觉得总体而言，那一类公司为股东做得不如另一类。但我没有统计学的方法来证明这一点。我也不知道我有什么办法，我不知道你怎么建立一个真正有效的样本，去比较这一类对那一类。但你说的并不让我吃惊。","kind":0},{"y":2002,"at":0,"ask":"好。第三点是，3月1日，《华尔街日报》分析或者说比较了道琼斯工业指数30只股票的审计费用，按审计服务相关费用和其他审计服务来分……","ans":"我们尽量盯着Berkshire周围的所有开支，我觉得在我们的子公司，总的来说我们的经理在这方面都非常非常好。我觉得我们的审计成本，相对于企业规模什么的，我觉得相当低，虽然不如几年前那么低。但这是我们关心的事情，我可以向你保证。我不，我不知道怎么，不过我不想基于那种统计指标来买股票或者卖股票，哪怕它在他们所谓的回溯测试里看起来不错。Charlie？","kind":3},{"y":2002,"at":"05:13:51","ask":"就在今天早上，我还得训斥Kirby楼下楼梯上的一些伙计。几周前，Berkshire Hathaway的名字上出现了一个污点或瑕疵，魅力上也出现了一点裂缝","ans":"对，我看了那个节目，挺有意思的，因为它聚焦在一些人的销售做法，或者说被指控的销售做法上，那些人不是我们的员工，而是经销商的员工，就像推销员为Ford经销商工作之类的。特别是，它在讲他们向老年人销售。有意思的是，十多年前我们定了一个政策，据我所知全国独一份，就是任何人，任何65岁以上买了Kirby吸尘器的人，不管什么原因不满意，在一年零十一个月零二十九天之内，都可以告诉我们，然后无条件拿回钱。我不知道全国还有没有另一个这样的耐用消费品政策。","kind":3},{"y":2003,"at":0,"ask":"谢谢，巴菲特先生。早上好，各位股东。我叫Chris Fried，我来这里是为了提出一个股东提案。这个提案旨在把股东指定捐赠计划扩展到","ans":"而且当时我们向一群新合伙人，B类合伙人，发行那些股份的时候，我相信我们解释得很清楚，到底有哪些不同。投票权上有不同。还有，A类可以转成B类，但反过来不行。还有股东指定捐赠计划上也有不同。自从我们发行那些股份以来，我不知道，大概六七年前吧，我们实际上跟A类和B类股东都有一个约定，就是我们会按照发行当时所解释的方式来对待这两个类别。","kind":3},{"y":2003,"at":0,"ask":"谢谢，巴菲特先生。早上好，各位股东。我叫Chris Fried，我来这里是为了提出一项股东提案。这项提案旨在将股东指定捐赠计划扩展到","ans":"而人们，这意味着人们一直在让我们使用那笔钱。而且就像我说的，第一季度的结果不仅是使用这笔钱没花我们一分钱，实际上人们还付钱让我们用这笔钱，我们希望他们继续这样做。而且我看我们的浮存金从现在起不会增长太多了。查理上次说它不可能增长了，但很可能还是会增长。我不知道他会不会改变那个看法。","kind":2},{"y":2003,"at":0,"ask":"这个能用吗？好，行。……纽约市，问题如下。保险公司：您能否谈谈保险公司通过出售信用衍生品承担信用风险的问题，账户的充足性，一","ans":"我在年报里提到过，GEICO在80年代初收了多少，七万出头，7万美元的保费，就几份保单，当时他们以为是在挑樱桃，还把大部分再保出去了。到现在我们亏了9300万美元。你看，我们最多能赚七万出头，我不知道我们最多能亏多少，但我知道9300万美元已经引起我注意了。","kind":4},{"y":2003,"at":"01:38:13","ask":"我们大概得找个警察来估一下，但我说得有两千吧。总之，继续往下。希望我能一问两得。一个是，在我们经营的小公司Branders，我们看到，我们在花很多","ans":"是啊，嗯，我们不会，我们不会预测得那么远，除非我们觉得自己能被成功冷冻起来才需要那样。但我们，我们真的，这些企业我们打算永远持有，所以我们想要一个，我们想要一个我们认为如果经营得好，能在几十年里保持某种竞争优势的企业。我是说，我们不打算转手卖掉它们，所以我们最好拥有的东西不仅现在好，将来也得好。所以我们不买呼啦圈公司，也不买宠物石头公司，我们也不买那些我们认为需求会大爆发的行业里的公司，但前提是，我们不知道谁会赢。所以我们看得远，我们努力，我们喜欢认为自己是在往未来看很远。","kind":0},{"y":2003,"at":0,"ask":"你好，巴菲特先生和芒格先生。我叫Justin Fung，13岁，来自加州。这是我连续第三年参加。首先，我祝你们身体健康，这样我们能继续，","ans":"我是说，那个，我不知道是Oscar Hammerstein还是谁说的，你知道，“钟不敲不响，歌不唱不成歌，爱如果只放在心里不拿出来，爱就不是爱，直到你把它给出去。”基本上你付出的总会比你给出的多，如果你什么都不给，你就什么都得不到。就这么简单。","kind":0},{"y":2003,"at":0,"ask":"你好，巴菲特先生和芒格先生。我叫Justin Fung，13岁，来自加州。这是我连续第三年参加。首先，我祝你们身体健康，这样我们就能继续，c","ans":"我不认识任何像我这个年纪的人，能被很多人爱着。前几天我们有个晚餐会，Don Keough在场，所有人都爱Don Keough，你知道，而且是有理由的。我认识的人里，没有谁——能赢得身边人的爱，同事、家人、邻居的爱——不是成功的，或者不觉得自己成功的。我不知道那些知道没人爱自己的人是什么感受，但我没法相信他们感觉会好。所以很简单。你没法摆脱爱。如果你试着给出去，你收回来的比你给出去的还多，这是，这是最好的事。Charlie，你想说什么？","kind":0},{"y":2003,"at":0,"ask":"是的。我叫Oliver Graussa，来自奥地利维也纳。我，我的问题有两部分。第一部分是，你是怎么靠少数几个出色的投资主意取得这么大成功的？你会读什么特别的报纸或者","ans":"所以这不是那种，你知道，我当年对赌马特别感兴趣的时候，有句老话说——我希望Bob Dwyer还在场——就是说，你能赢一场比赛，但你赢不了所有比赛。你可以在单独一家公司上做出一个非常赚钱的判断。但要是我被要求对S&P里全部500只股票都做出预测，判断它们未来几年相对市场的表现，我可不愿意被这么衡量。我不知道我会做成什么样。但也许我能在里面找到一只，我觉得自己有九成、90%的把握是对的，这在股票上就是巨大的优势。就是，你一辈子只需要在极少极少极少的事情上判断正确，只要你别犯任何大错。","kind":0},{"y":2003,"at":0,"ask":"是的，你好。Paul Tomasik，伊利诺伊州Thornton。Ben Graham和价值投资的模型。我想把讨论拉回到那上面。关于你、Charlie和Ben Graham，有趣而特别的地方在于那个选","ans":"我要告诉你，你知道，财富500强里20%的公司，但我不知道是哪20%，五年后赚的钱很可能会比今天少得多。这就是这个游戏的全部意义，搞清楚那些未来的现金流大概会是什么样。当你做不到的时候，当你觉得在这方面没法做出合理估计的时候，你就换下一个。Charlie？","kind":2},{"y":2003,"at":"02:57:52","ask":"是的，你好。我是Paul Tomasik，来自伊利诺伊州桑顿。Ben Graham和价值投资的模型。我想把讨论拉回到那上面。关于你、Charlie和Ben Graham，有趣而特别的地方在于那种自","ans":"对，我们不会，我们不会那么做。事实上我们从来没这么做过。而且，你知道，最初，1956年5月5日我们成立合伙公司的时候，我发给七个有限合伙人一份叫基本规则的东西，我，你知道，我说，这是我能做的，这是我不能做的，还有些事我不知道自己能不能做。可能挺短的。但那种明知道自己做不到还去做的事，那不行，你知道，那肯定会出问题。我是说，有人跟我说我必须跳七英尺高，现在甚至可以降到四英尺了，你知道，在今天日落之前，不然就开枪打我，你知道，我会出去买件防弹背心。","kind":4},{"y":2003,"at":"03:00:07","ask":"嗨，我是来自堪萨斯城的John Golob。我有一个关于衍生品的后续问题。媒体盯上你年度信里的评论之后，Fannie Mae的头儿站出来说，嗯，巴菲特先生的批评不","ans":"是的，我很尊重Frank Raines。我觉得他在Fannie Mae干得不错。我不太了解具体情况。问题，就像你说的，是像Fannie Mae或Freddie Mac这样的机构，或者过去的储蓄贷款机构，都有这个问题，这在抵押贷款工具里是固有的，就是在匹配或者接近匹配资产和负债的时候。他们之所以有那个糟糕的问题——很多机构都因此完蛋——原因就是抵押贷款工具里的期权性。","kind":0},{"y":2003,"at":"03:25:02","ask":"先生们，我叫Jim Maxwell，来自内布拉斯加州奥马哈。可以说，你们通过Level 3试了试水，当时你们给了笔交易，或者说，你们参与了跟他们的那笔交易。我想知道是不是有","ans":"他有麻烦了。不，我们完全不知道。你知道，你要是随便拎出个名字，BellSouth，对吧？我完全不知道五年或十年后那一切会怎么整合。我是说，我知道人们五年、十年、十五年或二十年后还会嚼Wrigley口香糖，还会吃Hershey巧克力棒或者Snickers棒。他们还会用Gillette刀片，还会喝可口可乐，你知道。我对这些东西各自随时间推移的盈利能力多少有点概念。但电信行业怎么洗牌，我完全不知道，而且，这行里谁要是告诉我他知道，我也不会信，因为，你知道，五年前他们又会跟我说什么呢？","kind":2},{"y":2003,"at":0,"ask":"先生们，我叫Jim Maxwell，来自内布拉斯加州的奥马哈。可以说，你们在Level 3上试探了一下，给了笔交易，或者说，参与了跟他们那笔交易。我想知道是不是有","ans":"所以这就是个我不懂的游戏。那个，就是说，有太多东西我不懂了。我不知道明年可可豆会怎么样，你知道的。我是说，我要是知道的话就轻松多了。我光靠可可豆就能赚所有的钱，比在Berkshire管一大堆生意简单多了。但是，我不担心我不知道的东西。我担心的是确保我懂我确实懂的东西，而电信不在那个范围里。","kind":0},{"y":2003,"at":"03:43:02","ask":"Phil McCaw，来自康涅狄格州Warren。您能不能谈谈Gen Re以及自您收购以来商誉减值的问题，还有它在您想法中是如何演变的，甚至它是否成为您……谢谢","ans":"是啊，一般来说人们认为报告、透明度和所有这些这些年来是改进了的。你看，我觉得看1960年的财务报表比看2000年的财务报表舒服多了。说实话，在很多方面，我觉得它们让我更了解公司真正是什么样，比现在的报表还强，尽管细节少得多。我们真正痛恨的是用会计手法来解决经营问题。你看，Gen Re在80年代中期有些问题，那时候大家都有，他们就开始对工伤补偿准备金做贴现，你看，那是个快速解决办法，但就像海洛因一样，一旦沾上就不容易戒掉。","kind":0},{"y":2003,"at":0,"ask":"下午好，先生们。Andy Marino，来自Chapel Hill，原籍波士顿。你们反对使用替代性的盈利指标，比如息税折旧摊销前利润，作为","ans":"“就是要当那个永远见风使舵的Bray牧师。”嗯，我觉得我们在审计行业里已经看到一点这种情况了。但我，我觉得他们现在其实已经找到真正的信仰了，所以我不，我不想坐在这里批评他们。但是，你知道，现在有四家事务所在1993年游说反对把期权计为费用，现在却写信给FASB说期权应该算费用。我真不知道一件事怎么能在1993年不算费用，到2003年就算费用了。","kind":4},{"y":2003,"at":"04:06:57","ask":"我已故的叔叔，Robert W. Baird的Bill Shield，在我们家第一次买Berkshire的时候股价是337美元。我非常感谢你们两位，因为我得以在圣路易斯创办了一个基金会，把钱捐出去，而我","ans":"咱们就别试了。咱们就别试了，Charlie。不，哦，得了吧。我是说，这是有记录的，而且大概25年没变过了，我估计。但基本上我所有的一切，在我或我妻子中较晚去世的那天，都归，都归慈善。我是说，那99%还多。既然我的孩子们在这儿，我就不算到小数点后八位了。但是，你知道，为什么不呢？这么想吧。这儿，这儿，咱们就假设，我不是像我这样单胎出生的，而是在娘胎里，旁边有个同卵双胞胎。同样的DNA，什么都一样，性格、工作的劲头、想说什么就说什么的劲头。同卵双胞胎，不是Charlie。可能长得像他，但是。","kind":0},{"y":2003,"at":"04:42:27","ask":"这就是被提议的东西。","ans":"我们一直在……我们一直在努力做你说的那种事。而且……但即便是努力去做，我是说，我们已经给了你我们会给自己的那些数据。我们不知道答案，但我们确实知道这是你必须考虑的东西。我们做的时候……当我们买McLane的时候，当我们买Clayton Homes的时候，当我们买任何东西的时候。我们试图看向经济上的未来，说这个生意随着时间能产生什么样的现金，我们对此有多确定，以及购买价格跟这个相比如何。","kind":0},{"y":2004,"at":0,"ask":"Warren和Charlie，我叫Peter Brochi，来自马萨诸塞州Beverly，我想感谢你们两位帮助我成为更好的商人和更好的投资者。也许更重要的是，你们创造了，通过","ans":"那时候我在投资界已经很久了，那两位是我认识的。但他们差不多是我的同代人，这些年我逐渐了解他，我观察他很久了，所以我不光知道他们的业绩，还知道他们是怎么取得业绩的，这非常重要。现在那一代经理人我不认识了。但事实上，以我认识的人数之多，我在非常活跃的时候也只能找出两个来，这说明找到经理人有多难。","kind":4},{"y":2004,"at":0,"ask":"一个海滩。说到MidAmerican Energy，它下面的一个子公司HomeServices，我觉得是个大机会。我很想听听你对它未来增长潜力的看法，尤其是面对……","ans":"我不知道它能变得多大。它会比现在更大。相对于伯克希尔的整体市值，它可能不会是一个巨大的因素，但可以想象，随着我们买下更多业务，我们也会找到其他事情跟它们一起做。我是说，买房子对人们来说是件大事。你知道，他们常常同时买家具，也许我们可以提一两个建议。查理？","kind":2},{"y":2004,"at":"02:44:12","ask":"嗨，我叫Nate Anthony，来自伊利诺伊州Hinsdale。首先，我想对之前一个关于Berkshire未来的问题做个回应。我相信作为股东，我们有责任自己思考","ans":"是啊，问题会是冲突太多了。你看，我们在Berkshire管理着那么多自己的钱，要是再承担起管理另一群人的责任、对他们负有全力付出的义务，还要在道德上戴两顶帽子处理那种局面，我不知道怎么做。我当然不想开一家基金管理公司，然后在Berkshire和那家基金管理公司之间按比例分配所有购买，个人来说不想开一家基金管理公司然后在Berkshire和那家基金管理公司之间按比例分配所有购买，或者在那家基金管理公司或它管理的基金里……我，我们想过很多了。我是说，各种提议都有人给我们提过，显然我们可以大卖特卖，但等我们卖完了，接下来就有公平管理它的问题，我不知道我们该怎么做。Charlie，你说？","kind":0},{"y":2004,"at":0,"ask":"下午好，巴菲特先生和芒格先生。我叫Van Argyrakis，来自奥马哈。很多美国跨国公司依赖进口外国劳工。你对美国移民的现状怎么看……","ans":"所以这是一个非常了不起的故事，而要归因于或量化其中各个组成部分是非常非常困难的。但我们确实一直是一个以大量移民为特征的国家，这是否以任何方式促成了这个国家不可思议的纪录，我不知道，但我怀疑是这样的。","kind":0},{"y":2004,"at":0,"ask":"Sam Kidston，来自马萨诸塞州Cambridge。我想请您谈谈你们的再保险业务和Gen Re在其证券部门所做的有什么异同，因为看起来","ans":"嗯，1991年那个星期天我们在Salomon就遇到这种情况。如果Salomon第二天破产了，你会有在1.2万亿名义金额左右衍生品另一侧的人，他们跟一个将要面对破产法庭的对手方有合约。你会有各种证券结算不一定能结算。你会有各种混乱，相信我，那时候会非常巨大，日本那边的情况、英国那边的情况、美国这边的情况，因为账目全都混在一起。事实上，Salomon是一家，是一家银行，在德国经营一家银行，那家银行吸收了大量个人存款然后全贷给Salomon。所以它会有一笔对破产公司的应收款，同时欠着不知道多少德国储户的钱。","kind":4},{"y":2005,"at":0,"ask":"我叫Ole Larsen，来自盐湖城，原籍瑞典。我读了你们的年报，你在里面提到经常账户赤字或贸易赤字最终必须结束。而他们报告，你们，我们","ans":"但大多数经济学家、大多数观察者仍然会说某种软着陆是可能的，或者说他们会说这很可能。在我看来，他们从来没真正解释过，你知道，软着陆到底是什么。他们只是说，你知道，很可能是软着陆，但也可能是别的，不过我们仍然认为会是软着陆。可我不知道软着陆到底是什么，从数字怎么大幅降下来这个意义上说。","kind":2},{"y":2005,"at":0,"ask":"我叫Ole Larsen，来自盐湖城，原籍瑞典。我读了你的年度报告，你在里面提到经常账户赤字或贸易赤字最终必须结束。而且他们报告，你我们","ans":"Volcker在这东西里说，他在第二段说，“然而在平静的表面下，有令人不安的趋势：巨大的失衡、不均衡、风险，随你怎么叫。总而言之，这些情况在我看来是危险且难以处理的，”我不是强调难以处理，“就像我能记得的任何情况一样，而我能记得很多。”嗯，Paul Volcker能记得很多，我同意这一点。我不，我完全不知道，我完全不知道时机。而且在经济学里，告诉你会发生什么比告诉你们时会发生要容易得多。","kind":2},{"y":2005,"at":0,"ask":"你好，我叫Johann Freudenberg，来自德国。您认为房地产市场大幅下滑会对地毯零售商和制造商的销售产生什么后果？谢谢。","ans":"这个，你知道，我不会……我不知道我们现在处在住宅住房周期的哪个位置。它有不一样的行为特征，很简单，因为人们住在房子里，很多很多情况下是这样，所以不一定表现得和其他市场一样。但当价格以远远高于建筑成本或通胀因素的速度上涨时，有时候会有相当严重的后果。Charlie？","kind":2},{"y":2005,"at":0,"ask":"来自英国的Andrew Noble。除了你之前谈到的那些灾难性保险事件或世界末日场景，就Berkshire Hathaway的运营而言，你最大的恐惧是什么？","ans":"我们的经理没有一个人向Omaha提交预算。我完全不知道我们下一季度会赚多少。我也没有向我们的经理们发出任何隐含的肢体语言或类似的东西，说我希望这个季度每股赚X美元。因为特别是在保险业务里，你可以基本上报告任何你想要的数字，如果你写长尾业务的话，在短时间内。而且，你知道，我们有450亿美元的损失准备金。嗯，谁知道正确的数字是450亿还是460亿还是440亿？如果目的是在某个给定季度报告某个给定数字，那你就不是说4500亿，而是说4475亿或类似的东西。","kind":0},{"y":2005,"at":"02:37:29","ask":"谢谢。我是圣路易斯的一名医生，我想感谢您和在座的各位，因为我就是那种对钱和金融完全不懂的医生之一。钱是进来了，但我不知道……","ans":"嗯，如果市场变得更便宜，我们会有多得多机会用钱做聪明的事。至于我们在这期间会不会把钱乱花掉或者别的什么，那是另一个问题。但是，你知道，我们会买东西，这样那样的东西，运营企业、股票、高收益债券，什么都行。只要我活着，我就会一直买东西，就像……就像我会一直买杂货一样。比那个还长。是啊，Charlie就等着我……之后接手呢。（笑声）我这辈子都会一直买杂货。那我是希望杂货价格涨还是跌？如果我明天、下周、下个月、明年都要买杂货，答案很明显，如果我是净买家，我……我会……价格更低我做得更好。","kind":2},{"y":2005,"at":0,"ask":"谢谢。我是圣路易斯的一名医生，我想感谢你和在座的每一个人，因为我就是那种对金钱或金融一窍不通的医生之一。钱是进来了，但我不知道……","ans":"我们没有……我们不擅长预测市场。我是说，我们知道70年代中期我们拿到了巨大的便宜货。我们知道90年代末市场在某种程度上疯了。但我们没有太多……我们不花任何时间……查理和我都不花时间思考或谈论股市会怎么走，因为我们不知道。我们有时确实知道，当我们买入一些股票或债券时，我们得到了非常好的价值。但我们不是基于任何对股票的宏观预测来操作的。","kind":0},{"y":2005,"at":0,"ask":"谢谢。来自纽约州的Bill Ackman。对于少数几家AAA评级的公司，AIG、Fannie Mae、Freddie Mac和MBIA正在因会计花招接受正式调查，并正在重述","ans":"现在，很明显，一个GEICO，你基本上承保同样的东西，汽车驾驶员，你得到的……你的统计数据在这类东西上比如果你承保……像石棉责任这样的东西要有效得多。你在估计上会犯更大的错误。这不意味着人们不是善意经营。但是，你知道，我会拿……就拿20家最大保险公司的石棉估计来说。我敢打赌它们差得远，但我不知道是哪个方向。这就是金融公司的某种本质。","kind":0},{"y":2005,"at":0,"ask":"谢谢。我是来自纽约州的Bill Ackman。那几家AAA评级的公司，AIG、Fannie Mae、Freddie Mac和MBIA，都在因会计猫腻接受正式调查，正在重述","ans":"我不会怪评级机构没能深挖财务报表、找出那些东西，你知道……你提到的所有这些公司都请了大牌审计师。而我们Berkshire的审计师，去年花了多少小时？你知道，我不知道……会是多少，大概6万、7万小时吧。我确信还有……你知道，你要是看大银行，他们花的比这还多。但是，你知道，他们能确定那些数字吗？我怀疑。Charlie？","kind":0},{"y":2005,"at":"03:48:41","ask":"下午好，先生们。我是来自德国科隆的Thorsten Kramer。你们批评过美国金融部门目前相对于GDP所占的异常大的比重，这个比重是","ans":"就像我之前说的，我看不出这个局面怎么能靠美元走强来解决。大多数人似乎还挺淡定，觉得不会有什么特别颠簸的事，会是所谓的软着陆。我不知道会不会真是那样。但我要说，我们面临的风险是，如果某些事件凑到一起，叠加在你刚才、刚才列举的那些因素之上，市场可能会变得混乱。但我不……在经济上我根本不是那种末日论者。","kind":2},{"y":2005,"at":0,"ask":"下午好，董事长先生，副董事长先生。我叫Andy Peake，来自康涅狄格州韦斯顿。最近我们看到一些公司董事会采取了强有力的行动，比如惠普和波音。我们……","ans":"但我们董事会上有真正的所有者，他们当董事的报酬跟他们的投资相比真的微不足道，我偶尔会被提醒这一点。而且他们是我的朋友。他们很聪明，非常聪明。我是说，他们是在商业头脑和人的品质方面精挑细选出来的。我真的认为，你知道，我们拥有全国最好的董事会。但那些想用清单来评估的人，你知道，不管是按多样性还是按所谓的独立性，虽然我不知道一个从董事会拿一半收入的人怎么能算独立，你知道，我们可能不太符合他们的标准。","kind":0},{"y":2005,"at":"04:16:01","ask":"下午好。我是来自北卡罗来纳州Davidson的Scott Jeffords。大型制药公司近年来面临了无数根本性和法律上的挑战。考虑到这一点，并且鉴于目前明显的持续","ans":"嗯，我的回答是我不知道，但也许Charlie知道。这是个，你知道，这是个很好的问题。只是这个行业现在处于动荡之中。它为人类做着非常重要的事情。它历史上赚过不错的回报，投入资本回报率非常好。但它要……很可能未来这些公司面对的世界会和过去不一样。也许……也许不是这样。我不觉得自己真有资格给你一个好答案，因为很大一部分在政治层面，而我对政客会怎么做，判断力大概不比你好。Charlie？","kind":2},{"y":2005,"at":"04:21:51","ask":"我是来自亚特兰大的Steve Casbell。有通胀的迹象，你知道，在商品和石油方面，为什么你觉得10年期还是，你知道，收益率是4.2%，而且，你知道，是不是市场看到了通缩的迹象","ans":"嗯，第二部分的答案是是的。我是说，如果有人向我保证10年期利率在未来50年永远不会超过4.2%，我们就得重新调整、重新校准我们在Berkshire周围做的每一个决定。我觉得是Alan Greenspan，我不知道他是在说10年期还是现在最接近30年期的什么东西，或者我们不再发行30年期了，但他把它称为一个谜。我查了一下之后，我决定同意他。我不理解它。但没关系。金融市场里有很多东西我不理解，但这不意味着我必须做一个决定。我不必要么做多要么做空10年期。","kind":2},{"y":2006,"at":"00:46:00","ask":"早上好。我叫Phil Raft，来自加州Orinda的股东。我的问题是：在一个从繁荣到萧条来回摆的强周期行业里，你会怎么设计薪酬体系？你想把……","ans":"是啊。有件事你可能会觉得有意思：我们……我们有，我不知道，68家运营公司。我大概负……我大概负责大约40个经理的薪酬体系，差不多这个数，因为有些人的业务是归在别人下面的。我想不起……还是那句话，我想不起40年里有谁因为薪酬……薪酬观点不同而离开我们的。我也……我们从来没有薪酬顾问进过Berkshire。子公司可能请过，但他们够聪明不告诉我。他们……哦，从来没发生过。我是说，我们不……我们也不开很多会。我们不在那上面花很多时间。这不是火箭科学。","kind":4},{"y":2006,"at":"00:56:10","ask":"我的问题是，现在大家对新兴市场热情很高，很多持有新兴市场股票的封闭式基金，交易价格比净资产价值高出很多，即使是开放式……","ans":"是啊，我觉得往往会这样。你说的新兴市场基金那些具体情况我完全不了解。我没看过溢价有多大。但历史肯定表明，大多数封闭式基金，几乎所有的封闭式基金，最终都会变成折价。我 actually 工作过……算了，我跳过那个类比吧。但……绝大多数情况下，封闭式基金都变成了折价。你知道，一开始，如果它们按 6% 佣金卖出，那最初买的人当然是花一美元拿到 94 美分的净资产价值。","kind":0},{"y":2006,"at":0,"ask":"我的问题是，眼下新兴市场这么热，很多持有新兴市场股票的封闭式基金，交易价格比净资产值高出不少，即便是开放式","ans":"但我不……我……如果我看到两个……如果我有兴趣通过别人的管理投新兴市场，我可以按X或资产价值买一只开放式基金，却要付120%的X买某只封闭式基金，那你得非常有说服力地让我相信那只封闭式基金的管理更好。所以我觉得你，你说得对。我不……再说一遍，我不知道那个溢……溢价。几个百分点，其实没多大差别。但偶尔Charlie和我在过去见过封闭式基金甚至卖到资产价值30%或40%的溢价。","kind":0},{"y":2006,"at":0,"ask":"换个严肃点的话题，美国公司治理上有个小但越来越明显的趋势，就是从董事选举的纯多数投票制转向绝对多数投票制，这在大不列颠一直是个门槛。您觉得好处是什么，还有","ans":"但我们也在别的董事会待过，我还真没见过因为把他们选进董事会的投票性质不同，行为上有什么差别。但差别巨大……你要是这些年观察过董事会，我觉得你会大……大……吃一惊。屋里人的商业头脑，他们做事时像不像所有者那样思考，差别就是巨大。我没见过……我不知道双重投票制或者没有双重投票制，跟这个到底有多大关系。","kind":0},{"y":2006,"at":"01:14:50","ask":"早上好。我是来自堪萨斯城的Diane Ryan。我的问题是，您对乙醇的经济性怎么看，就是作为燃料添加剂，而且作为潜在投资者，我应该关注这个行业吗？","ans":"嗯，后面那部分我了解得不够，没法回答。我知道我们不了解。Charlie和我都不够了解，没法评估乙醇项目。有人找过我们谈这些，当然现在它们很热门。但要算出一个乙醇厂五年或十年后的资本回报，对我们来说，算人们会不会喝Coca-Cola，甚至会不会吃See's Candy——这个我强烈推荐——要容易得多。所以这个，你知道，它取决于政府政策，取决于很多变量，而我们不太擅长预测这些。现在为它融资很容易。我是说，它是个热门项目，你知道，很火。而我们的总体经验是，我们不太看任何特定时候很火的东西。我知道，我对那个，你知道，生物化学之类的，一无所知。","kind":0},{"y":2006,"at":0,"ask":"我叫Louisa Loro。我是堪萨斯大学的学生，我来自巴西的巴西利亚。我的问题问巴菲特先生和芒格先生两位。南美洲的股市最近涨得很快，在","ans":"你看，PetroChina就是一个，大概是，嗯，它是世界五大石油公司之一，可即便在那儿，我们也只投进去四亿多美元，幸运的是现在值个二十来亿。但这是一个中国那么大的国家，那个国家最大的公司，即便在那儿我们也只投进去四亿多，虽然我们本想多投些。但我们不怕去，只是希望去中国要更高的回报，我们确实也拿到了，因为那儿我们不太懂这个游戏。","kind":1},{"y":2006,"at":"01:32:06","ask":"我叫Jeff Bangham。我来自伊利诺伊州芝加哥。我有一个关于预制房屋行业的问题。您对该行业的需求前景怎么看，相应地，在您看来，贷款会增加吗","ans":"嗯，愚，愚蠢的放贷总是有后果的，而且通常规模很大，因为你好一阵子都看不到。所以它就像一种病，你知道，好几周都不显现，然后你可以有那种病的流行病，等你知道有流行病的时候，你已经陷得很深了。嗯，愚蠢的融资就是这样。","kind":0},{"y":2006,"at":"01:38:54","ask":"我是来自加州旧金山的Lorie G。我的问题是，你怎么看美国的住宅房地产市场，它往哪儿走，加州如果不一样的话，怎么不一样？","ans":"你看，这很好，气候很好，这房产什么都好。只不过时不时地，哪怕在很好的地段，纽约过去30年里你也见过好几次了，房产价值的波动就是巨大。而我们在住宅经纪业务里看到的——我们在多少个州我都不知道——我们现在看到每个地方都在放缓。最明显的是在一些曾经最热的市场。在我看来，你最可能看到最大回落、泡沫最大的那些市场，往往是高端市场，往往是人们为了投资或投机而不是自住而买的那种。","kind":2},{"y":2006,"at":0,"ask":"我叫John Gos，来自Key West。保险费率有没有像您预期的那样走硬？过去几年您有没有看到明显的向优质资产转移？","ans":"有些价格涨了很多，但我们不知道的是，风险敞口是不是涨得更多。我们不知道过去两年的经历，比如说，这个半球的飓风经历，是不是比过去100年的经历更可靠。你可以拿100年的经历来看，它告诉你一件事，你可以拿过去几年的来看，它告诉你另一件事，哪个更有意义，我们不知道答案。","kind":2},{"y":2006,"at":0,"ask":"你好，我是来自澳大利亚墨尔本的Marc Rabinov。我有一个关于2005年年报的两部分问题。首先，NetJets是我们运营中很大的一块。不幸的是，它的价值被近期的亏损掩盖了","ans":"Rich Santulli，管那块业务的，你找不到比他更好的经营者了。他爱NetJets。他一天干16个小时。他，他本可以，这世上除了Rich，我不会让任何人去管那块。我觉得这是一项重要的服务。飞机这生意很难赚钱。资本密集。燃料又成了那样，虽然能转嫁给客户，但还是影响生意。我本来，我本来预期去年能盈利，结果就像我在年报里写的，我大错特错。我觉得要不了多久我们会盈利，但在我这个预测真发生之前，你大概该带着点怀疑看它，因为，就像我说的，我错过了。","kind":2},{"y":2006,"at":0,"ask":"嗨，沃伦。嗨，查理。我叫Jeremy Cleaver，来自堪萨斯州的Lawrence。我是Jayhawk。你们认为美国最好的金融项目是哪个？另外，我，我一年后就要毕业了。你们能不能","ans":"这个，这个，投入到资金管理里的脑力数量有点让人不安，尤其是对，对查理来说。但我会，你知道，现在22、23或者25岁、刚从学校出来，是个很好的时机。所以你，你可以展望一个非常，我觉得，一个，一个非常有趣的未来，在这个国家，尽管你可能会发现，运用你在投资方面的才能的方式，会以某种不同于，不同于它们目前被使用的方式被使用。我是说，现，现在来奥马哈参观的很多学生都说私募股权或者对冲基金。很难想象一个人人都在经营一个，经营一个对冲基金的世界。我不太确定我们到时候靠什么来吃饭穿衣之类的。","kind":2},{"y":2006,"at":0,"ask":"好。首先，我叫Egil Dahl。我是来自挪威的零售商。我想先感谢你们几位给我这个机会来这里向世界上最好的两位商人提问。我的问题是关于","ans":"我是说，Procter & Gamble和Ford Motor之间，通往几亿人眼球的电子高速公路只有三条。只有三条高速公路的时候，这三条能赚很多钱。但你不断修更多的路，让P&G或者Gillette或者不管是谁，或者Ford Motor、General Motors能到达那些眼球，你就降低了那些高速公路的价值。这不复杂。所以我，我觉得你们会看到，很难想象那些生意总体上会有很好的前景。我们拥有过World Book。我们现在还拥有World Book。80年代中期我们一年卖30万套左右。那是非常有价值的产品。卖600美元左右，值那个价。","kind":2},{"y":2006,"at":0,"ask":"下午好。我叫Yugi Simoto，来自纽约市。我想问巴菲特先生关于您对货币的看法：人民币、日元，特别是欧元。在胡锦涛访问期间","ans":"但基本面，在我看来几乎，你永远不能说一定，但发生的概率很高，就是美元会随着时间走弱。未来六个月或一年怎么样，完全不知道，但长期来看，对其它货币会走弱，因为我们执行的政策看起来没多少，看起来没留多少别的选择。这儿有句话，说的是，说的是巨额经常账户赤字，是2002年2月28日说的。原话是：“走上这条路的国家无一例外都遇到了麻烦，我们也会一样。最终，经常账户赤字必须受到约束。”说这话的是个非常聪明的人，叫Alan Greenspan。当时经常账户赤字是3850亿，现在会翻一倍还多。","kind":2},{"y":2006,"at":"03:37:44","ask":"嗨，我叫Jeremy，来自San Diego，首先，我想感谢你们各位对我作为职业投资人职业生涯的巨大影响。我的问题也是关于报业，那个","ans":"对，我们不谈具体细节。新闻，它，它……我觉得没人比Charlie和我更仔细地观察报业了，真的看了50年。我们以前，我们总是谈论全国的每一份报纸，收购潜力之类的。那是个，很容易理解的。我是说，那差不多是你能想象的最简单的经济、商业经济学问题。我们慢慢醒悟到它的变化。其实，我在1991年年报里写过，报纸，那个，全世界的预印广告插页，你知道，开始把报纸变成一个包装纸。它，包含了一堆本来可以装在别的包装里的东西。","kind":4},{"y":2006,"at":0,"ask":"David Winters，新泽西州Mountain Lakes。您能否谈谈您的承保标准发生了怎样的变化，因为天气模式似乎变得更恶劣，全球恐怖主义的挑战似乎在升级，一个","ans":"但这没什么神奇的。我大概会觉得，过去100年或200年的地震经验，比过去100年或200年的风暴或飓风经验更有参考价值。我不确定，但我愿意拿真金白银这么赌。而且我们——10年后飓风经验会是什么样，就袭击美国的数量，以及袭击时的猛烈程度？你知道，我不知道，但我每天都会琢磨这事。Charlie？","kind":2},{"y":2006,"at":0,"ask":"","ans":"所以我觉得品牌制造商和零售商之间的较量会一直一直持续下去，而且越来越激烈。所以我觉得，如果我站在那两边中的任何一边，我都会想强化自己的筹码。而且我觉得，Gillette和P&G合在一起，未来会比各自单干更好。我觉得尤其如此，因为Walmart、Costco，还有世界各地你叫得上名字的那些，都很强。我不知道，Charlie，你怎么看？","kind":2},{"y":2007,"at":0,"ask":"嗨，F. Natani。我大半辈子住在印度，现在住在新泽西州霍博肯。沃伦，首先，谢谢你回我的信。我把你的名字拼错了，在我来的地方，如果我犯了同样的错，回信会","ans":"但它确实会产生，它确实会在薪酬上产生这种棘轮效应。薪酬委员会坐下来，人力资源的人进来。人力资源的人知道，CEO对他们的看法会决定他们的未来。然后人力资源，那个部门推荐某个薪酬顾问。薪酬顾问知道，他给其他公司的建议取决于这些人怎么评价他。所以在这种情况下，你想，你能想象那像是一场公平的较量吗？就是个笑话。你知道吧。查理？","kind":0},{"y":2007,"at":0,"ask":"我叫Takashi Ito，来自日本。除了全球流动性过剩之外，企业利润相对于劳动份额来说非常高。这是不是让你更难找到投资机会？","ans":"我，企业利润占GDP的比例在持续上升，那意味着别人占GDP的份额在下降，你说得很对，GDP里劳动那块实际上下降得相当明显。这会不会变成一个政治问题，也许下一场竞选里，会不会变成国会要采取行动的事，国会有权力很快改变这个比例。不久以前企业税率还是52%，现在是35%，还有很多公司交20%甚至更少就过去了。所以我会说，眼下美国企业界算是活在最好的世界里，而历史表明这种状况不会无限期持续下去。是什么让它结束、什么时候结束，我不知道，但我不认为未来企业利润平均还能占到GDP的百分之八点几。Charlie？","kind":2},{"y":2007,"at":"00:55:18","ask":"你好。我叫Brian Vok，来自内布拉斯加州Fremont。随着我们股票市场里交割失败的交易越来越多，包括投资者的现金账户、Roth IRA和其他退休账户，看起来像……","ans":"对，就是所谓的交割失败和裸卖空，我想这是问题所在。我不太清楚具体情况，我从来没有遇到过这种情况——我向经纪人买股票，要求他给我证书，结果被拒绝了一段时间。我觉得你或许可以对他们采取一些行动。但我从来没有、我完全不觉得人们做空股票有什么问题。我是说，我欢迎人们做空Berkshire Hathaway。我是说，如果你持有股票，而他们需要向你借，你可以从你的股票上获得一些额外收入，而且最终你股票的一个确定买家就是做空它的人。我是说，那家伙总有一天要买它。","kind":0},{"y":2007,"at":"01:00:31","ask":"","ans":"博彩公司。博彩公司如果合法的话，前景会非常好。那个，你知道，哪些公司或者什么的，我对此一无所知，但人们赌博的欲望，顺便说一句，他们在股票上也赌。日内交易，我会说，很多时候非常接近定义上的赌博。但人们，人们喜欢赌博。你知道，我是说，这是个，如果超级碗在播，或者甚至，更好的是，如果一场极其无聊的橄榄球赛在播，但你没事可干，你坐在那儿跟别人一起，你要是押几块钱赌哪边赢，你大概会更享受这场比赛。你知道，我是说，我们承保飓风，所以我看天气频道。但那是个，可以很刺激。","kind":2},{"y":2007,"at":0,"ask":"早上好。早上好。早上好。我叫Mike Klein，是加州萨利纳斯的一名普通外科医生。鉴于你们在保险承保方面的资源和经验，你们有没有想过涉足，或者帮","ans":"你知道，如果我们要有，如果我们想通过私营部门找一个解决方案，我们会找那种分销成本非常非常低的东西。我是说，你不会想让大量收入被消耗在赔付和保费之间的摩擦成本里。我不知道怎么做，我也没看到别人很擅长做这个。你可以说，如果你把接近GDP的15%花在医疗成本上，总该有人能想出点办法来。但我没有，我没听到过。","kind":0},{"y":2007,"at":0,"ask":"是的。嗨，巴菲特先生，芒格先生。我是惠特尼·蒂尔森，来自纽约的股东。多年来，你们两位一直在警告衍生品的危险，有一次称它们为金融大规模杀伤性","ans":"嗯，衍生品和指数期货之类的引入，已经完全让任何保证金要求的监管成了笑话。它们还在，你知道，就是个过时的东西。所以我相信，我觉得查理大概也同意我，我们可能不知道危险到底从哪里开始，在哪个点、什么时候变成超级危险等等。我们当然不知道什么会精确地终结它。我们不知道它什么时候会精确地结束。但我们大概，至少我相信它会继续下去并加剧，直到某个时候市场上会因为它发生一些非常令人愉快的事情。","kind":2},{"y":2007,"at":0,"ask":"是的。嗨，巴菲特先生，芒格先生。我是Whitney Tilson，来自纽约的股东。多年来，你们两位一直在警告衍生品的危险，一度称它们为大规模杀伤性金融武器","ans":"嗯，那跟……比起来不算什么。那……那是一个正式安排，搞这些，这种动态对冲或者投资组合保险，卖出东西。但你有的同样的事情，当你有基金经理操作着数十亿、总计数万亿美元，带杠杆，会对同样的刺激做出反应。他们有那种……他们有我们会称之为拥挤交易的东西，但他们自己不知道。这不是正式的拥挤交易。只是他们都准备好了，如果某个给定信号或者某个给定事件发生就卖出。当你把那个和衍生品所允许的极端杠杆结合在一起，总有一天你会遇到一个非常、非常混乱的局面。我不知道什么时候。我不知道外生因素是什么……我不知道刺杀某个大公，你知道，会引发第一次世界大战。我也不知道什么会导致这种事。但它会发生。查理？","kind":2},{"y":2007,"at":0,"ask":"嗨。我是来自香港的Stanley Ku。我的问题是关于投资中短期心态的蔓延，因为越来越多的资金被置于绝对收益的委托之下。这些管理人，正如你刚才所说，会对……做出反应","ans":"这让纽……纽约证券交易所的换手率增加了，我不知道确切数字，但我记得40年前大概在15%到20%左右，现在我认为已经增加到100%以上了。所以，当然在债券市场，债券的换手率也大幅上升了。过去人们买债券是为了持有，现在他们买债券是为了交易。这本身没什么邪恶的，但这只是意味着参与者们在玩一种不同的游戏，而这种不同的游戏在买入并持有的环境里可能会产生不同的后果。","kind":1},{"y":2007,"at":"01:58:20","ask":"早上好。我是来自俄亥俄州坎顿的格伦·斯特朗。请告诉我们你在全球变暖辩论中的立场，或者特别是你在General Re的经理们的立场。也许你可以给我们讲讲你对科学方面的看法","ans":"我们终于把他放出来了，各位。嗯，我们会……我们会继续让负责保险的人来管，我向你保证，他们非常担心全球变暖。但它……我们不知道。我们确实知道2004年和2005年，飓风的频率，尤其是强度，是看上个世纪完全预料不到的。而我们幸免了，尽管有卡特里娜，我们幸免了本来可能更糟的情况，因为几个五级飓风没有登陆大陆。","kind":2},{"y":2007,"at":"02:00:53","ask":"嗨，我是来自堪萨斯城的John Golob。我有一个关于中国经济的问题。一些观察人士提出，中国的银行体系看起来有点像90年代的日本。您是否担心中国可能","ans":"我得说我不知道这个问题的答案。我是说，这是一个……这是一个……这是一个非常有趣的问题。这是一个非常重要的问题。但是，你知道，我在日本发生的事情发生之前，也不一定理解会发生什么，而我对中国银行的洞察力基本为零。有人向我们提供过买入各种中国银行股权的机会，还是那句话，因为我对它们一无所知，我放弃了。这不是判断说有什么不好的东西。只是说，坐在内布拉斯加州的奥马哈，不知道贷款和垫款的某些项目里，它由什么构成，或者那个地方的实际运营情况，我就能判断它值X、X的一半、2X、X的四分之一。我就是不知道。我真的不知道。它们……我对你问题的答案就是毫无概念。但也许查理有。","kind":2},{"y":2007,"at":0,"ask":"嗨，我是来自洛杉矶的Bob Klein。从另一个角度追问您之前关于sigma的评论。投资界的传统智慧是，一项投资的风险可以用p的波动性来衡量","ans":"风险来自某些类型企业的本质。仅仅因为你所处行业的简单经济学，身处某些行业就可能是有风险的。风险也来自你不知道自己在做什么。而且，你知道，就是，如果你理解你所从事企业的经济学，你了解和你做生意的人，你知道你付的价格是合理的，你就没有承担任何真正的风险。我不认为查理和我，当然伯克希尔，我不认为我们在可流通证券上曾经有过永久性损失，大概是，1%，也许净资产的一半个百分点。我在买Dexter Shoe时犯了一个可怕的错误，那次我们损失了远超净资产1%的钱，当时我买下了整个企业。但我看错了那个企业。跟鞋价或者皮革或者别的什么的波动毫无关系，就是看错了。","kind":0},{"y":2007,"at":"03:58:43","ask":"是的。谢谢沃伦和查理，谢谢你们在这场精彩的会议上给我们带来的非凡教育和慷慨分享。我从 1994 年起每场会议都参加。沃伦和查理，假设未来现金流需要必要的安全边际……","ans":"是啊，我们觉得就我们面对的世界而言，我们旗下是一批相当不错的企业。你知道，我们不知道哪些最终会最好。有几家我们认为是真正的超级赢家，我们觉得相当一部分会表现还行。我们买企业时不太会想着世界大趋势。我们当然会考虑国际竞争、外国竞争。我是说，我们不想买那种劳动含量很高、产品又很容易从国外运进来的企业，因为那迟早会出问题。就像查理和我真的，我买了一家航空公司，他后来过来想救我，那是几年前的事了，那家公司每座英里成本很高，但有受保护的航线，就是 US Airways。所以它能在每座英里 12 美分成本下运营，因为 Southwest 还没带着他们 8 美分的成本到那儿，但他们总会到的。","kind":0},{"y":2007,"at":0,"ask":"我是来自爱荷华州Des Moines的John Norwood。快速说一句、快速评论一下再问个问题。评论是接着Charlie关于乙醇的说法：我至少想请他从燃料乙醇的环境效益角度看一看……","ans":"他们就是，你知道，这不是那种你做个决定、然后有人赞成有人反对的事。根本不是那样运作的。我不知道怎么在这方面大幅改进。我觉得我们在Berkshire有一个非常出色的团队。这个团队里，几乎每位董事都有相当比例的净资产在里面。Bill的太大了，我们没法让他占到显著比例，但他在里面有数亿美元。我们有一个和股东处于完全相同立场的董事会。","kind":0},{"y":2007,"at":0,"ask":"下午好。我叫Andy Peake，来自康涅狄格州韦斯顿。最近报纸一直上新闻：Murdoch竞购Dow Jones，Morgan Stanley的Hassan Elmasry推动取消New York Times的双重","ans":"后来呢，你知道，另一件事先来了，人们的习惯不会立刻改变，你知道，世界不会一下子翻过来。但实际上，你知道，今天报纸的处境仍然反映了这样一个事实：它们有来自过去的惯性和势头在撑着。我不管你有多聪明。你知道，几年前有个人来到LA Times，他打算把发行量提到150万，我记得是这样，没错。而现在LA Times的发行量是80多万，而且还会往下走。每个星期都在往下走。我不知道，你知道，我不知道Joseph Pulitzer或者William Randolph Hearst或者E.W. Scripps，或者任何在他们那个年代也许是扩大发行量天才的人，能对此有多大作为。事实是，世界已经发生了重大的变化。","kind":2},{"y":2007,"at":"04:28:18","ask":"下午好。我叫Andy Peake，来自康涅狄格州Weston。最近报纸行业一直是新闻焦点：Murdoch竞购Dow Jones，Morgan Stanley的Hassan Elmasry推动取消New York Times的双重股权结构……","ans":"我还想补充一点，Sulzberger家族从一开始就是这样，你看，任何买入New York Times的人都知道，他们不会试图最大化某个季度的盈利，也不会通过削减成本之类的办法来尽量减小 downturn。他们不是靠那样把New York Times建起来的。它能有今天的声誉、或许能在互联网上有个不错的未来，也不是靠那种做法。它不是靠那种、你知道、商学院教的管理学入门那一套走到今天的。然而，走那条不同的路，你知道，我不知道纽约有多少家报纸消失了，不管是Herald Tribune还是Sun还是World-Telegram，或者你随便说，World、the obser，它们用的是不同的管理方式，结果全都半路倒下了，而Times还在。","kind":0},{"y":2007,"at":"05:13:35","ask":"是的，我叫Bill Rosenfeld，来自马萨诸塞州列克星敦。在你们的网页上，你们声称子公司不能控制其母公司的行为，所以针对PetroChina的行动不会对CNPC产生影响。假设","ans":"是的，Charlie和我在比如生育自由这些问题上有我们自己的看法，但我们在Berkshire Hathaway没有关于生育自由的方针，我们也不会用Berkshire Hathaway的资金、我们股东的资金去资助。我们不会资助任何跟我们个人信念相关的活动，虽然我们显然可以自己出钱或者自己发声。但我们不会因为我们认为女性应该有选择权或者类似的问题，就以Berkshire Hathaway的名义去资助。我觉得在这些问题上，理性的人可以有不同意见。在Berkshire，有些生意我们不会去买、不会去单独控制，但我们愿意持有同样这些生意的股票。这是不是正确的道德界线？我不知道。我们尽力而为，我们做决定，我们拍板。","kind":0},{"y":2008,"at":"00:14:38","ask":"早上好，巴菲特先生，芒格先生。我叫Sam Rainer，来自新泽西州Fort Lee，我的问题是关于您这周对经济衰退以及四月股市大幅上涨的评论。您能不能","ans":"嗯，我可以展开说，但我也答不上来。他们……查理和我对下周、下个月或者明年股市会怎么走，一点概念都没有。我们从来不谈这个。你看，这根本不会出现在我们的话题里。我们的董事可以告诉你，他们从来没参加过一次董事会，会上讨论股市走向的……我们不做那个生意。我们不知道怎么去做那个生意。很明显，如果我们能高概率地猜中股市会往哪走，那我们别的什么都不干，就去玩S&P期货市场了，那就根本没有理由去看企业和股票了。所以这根本不是我们的游戏。","kind":0},{"y":2008,"at":"00:52:08","ask":"早上好。我是来自加州Walnut Creek的Dinish Takariya。嗯，我们从一部喜剧电影里学到了一些东西，但您能不能展开讲讲，您是怎么保持身心健康的？","ans":"他经常跟我指出这一点。嗯，你想想看，CEO薪酬代表了一个市场体系，你得付给某个人一千万美元的留任奖金什么的，让他留在一个——你知道，他一直在拼命保住的工作上，还在董事会里安插人什么的，好让他们把他留下来。我是说，这……我不知道美国有哪个CEO，我肯定有几个吧，但我……那儿……我不知道有哪个会不愿意拿一半甚至四分之一的价钱高高兴兴干这份活。我见过一些人离开了给他们八位数薪水的工作，一年后、两年后，没人给他们开任何价。我就纳闷那个美妙的市场体系在哪儿， supposedly有一堆人争着要他们的服务。我觉得这真有点荒唐。（掌声）我们继续，12号。","kind":0},{"y":2008,"at":0,"ask":"嗨，Warren。我是Doug Hicks，来自俄亥俄州阿克伦。最近新闻上很多人说石油会在本世纪内耗尽。考虑到美国的政策是不到最后一秒什么都不做，那你怎么","ans":"所以我们没办法在短时间内把日产量从8600万或者7000万桶提到1亿桶。但不管那个峰值是多少，不管我们是五年后还是五十年后到达那个峰值，之后它就会慢慢递减，世界会去适应它。希望我们能在那发生之前就想到这件事，你看，世界上会做出各种调整，使得需求随着可用供应一起慢慢降下来。但本世纪之后我们还会继续产油。问题只是我们日产5000万桶，还是7500万桶，还是2500万桶。这个答案我不知道。","kind":2},{"y":2008,"at":"02:38:29","ask":"我叫Ola Larson，住在盐湖城。我想是1981年左右在Lou Rukeyser的《华尔街一周》上看到你的，Warren，那你肯定给我留下了深刻印象。我想问你的是，看看这","ans":"Charlie和我刚到Salomon的时候，我们注意到他们在和Marc Rich做交易，那个人已经逃出国了。我们建议，嗯，我们告诉他们我们想停止和Marc做交易，他们说，嗯，他们这么做在赚钱，不管怎么说吧，他们说，“我们对原油交易懂个什么？”他们想继续和他们交易。只有靠完全强制命令我们才能阻止自己的员工和Marc Rich交易。你看，如果你连自己的交易员和Marc Rich交易都阻止不了，当你专门盯着这件事的时候都这样，那你就想象一下，别处那些交易室里都在发生什么。","kind":4},{"y":2008,"at":0,"ask":"我叫Ola Larson，住在盐湖城。我想是1981年左右在Lou Rukeyser的《华尔街一周》上看到你的，Warren，那你肯定给我留下了深刻印象。我想问你的是，看看这","ans":"你就想象一下，全世界有成千上万的交易对手，你知道，都在试图解除合约，而且所有人都知道他们必须在非常非常短的时间内解除合约。我们试图去联系但那4亿没找到，我们有奢侈的条件花大约四五年时间去慢慢解除那些合约。这些人只有四五个小时来做同样的事，而且所有人同时在做。那会是一场我觉得规模空前的奇观。当然，在我看来，那会导致另外一两家投资银行在几天之内倒下，你知道，因为没人非得留下来，没人非得借钱给你。","kind":2},{"y":2008,"at":0,"ask":"Harry Bagai，旧金山。Buffett先生，我最近在《Fortune》杂志上读到，你2001年还是2002年往PetroChina投了5亿美元的时候，你做的就是读了年报。然后我就想，","ans":"所以我们真正喜欢的是那种你不需要算到小数点后三位的东西。你看，如果你得算到小数点后三位，那就不是什么好主意。你看，就像PetroChina，就好比有人走进这扇门，体重大概在300到350磅之间，我可能不知道他具体多重，但我知道他胖，你看。这就是我要找的——财务上胖的东西。至于PetroChina是950亿还是1050亿，如果我们是花350亿买的，那没多大区别。如果它卖到900亿，那就有区别了。","kind":0},{"y":2008,"at":0,"ask":"Harry Bagai，旧金山。Buffett先生，我最近在《财富》杂志上读到，你2001年还是2002年投资5亿美元买PetroChina的时候，你做的就是读了年报。现在，我在想","ans":"所以如果你光看数字都没法对PetroChina这样的东西做出判断，那就别往下想了。基本上我们就是这么做的。那是一份很直白的报告，就像读另一份，就像读Chevron或者ConocoPhillips之类的，信息量一样。我们还会了解更多，你知道，通过出去调研，判断你觉得他们在中国是不是有一个巨大的油田，它的寿命是13年还是14年之类的？这些应该一眼就能看明白。Charlie？","kind":0},{"y":2008,"at":"02:45:38","ask":"Harry Bagai，旧金山。Buffett先生，我最近在《财富》杂志上读到，您2001年或2002年投资5亿美元买PetroChina的时候，您做的就是读了年报。现在我在想","ans":"当我们接到像Mars-Wrigley这种情况的电话时，如果到那时候我们对Mars和Wrigley了解得还不够，还得出去调研，我还是喜欢出去，当然，把所有巧克力棒都尝一遍，所以我们有，15。我是说，我觉得这是我欠Berkshire股东的。但我不会去看他们的劳动合同或者租约什么的。如果Wrigley的价值取决于某个地方的某个具体租约，或者对这个那个的具体承诺，你知道，或者某个环境问题，那就算了，你知道。","kind":0},{"y":2008,"at":0,"ask":"你好，我叫Harold Yulin，来自伊利诺伊州芝加哥。我想请您描述一下Kraft Corporation的经济特征，以及您为什么觉得这是一门好生意。","ans":"那个我一直没太搞明白，当初的承诺到底是什么，但不管是什么，都没成，而且，你知道，它们一直有，我不知道有多少，Don Keough会知道，但这些年有几百种可乐。但到最后，谁会，你知道，为了便宜一美分、或者每罐比Coca-Cola便宜两美分，去买某种替代可乐呢？See's Candy也是一样，Kool-Aid也是一样，不管是什么。所以当品牌产品在它们领域里是遥遥领先的老大时，我们感觉相当不错。","kind":0},{"y":2008,"at":0,"ask":"巴菲特先生，你好，芒格先生。我叫Brooke Advertic，来自德国慕尼黑。我想回到您说的那一点，就是作为一个专业投资者，应该能够快速而果断地行动。那意味着","ans":"但然后如果它通过了这几个筛选，进入到这样一个区域，就是说这个东西我们了解得够多、可以做出决定了，那我们就准备马上行动。所以我们做决定，我们可以在五分钟内很轻松地做出一个决定。我是说，它就没那么复杂。现在，我们了解一些企业和行业，也有很多企业和行业我们一无所知。我们对某些类型的债券了解很多，我们知道一些，有各种各样我们知道的东西。如果能扩大那个知识圈当然好，但最重要的是，任何通过筛选的东西得是在知识范围之内的。","kind":0},{"y":2008,"at":0,"ask":"是的，但谢谢你。好。我还应该做什么来引导他们做出合理的财务决策，拥有一个快乐、健康的财务生活？","ans":"我，有一个例子你可以在班上试试，我跟高中生讲话的时候就跟他们讲这个。你就想象你16岁，我今天要送你一辆车，你随便挑，想要什么车都行。但是，有一个条件。这是你这辈子唯一的一辆车，所以你得让它用得久。你可以挑最花哨的那辆，大多数人都这样，随便什么。你会怎么对待它？当然了，你会在拧钥匙点火之前把车主手册读个五遍。你会把它停在车库里。有一点小锈迹，你马上就去处理。你会按规定的两倍频率换机油，因为你知道，它得用一辈子。","kind":4},{"y":2008,"at":0,"ask":"是的，但是谢谢你。好。我还应该做什么来引导他们做出合理的财务决策，拥有一个快乐、健康的财务生活？","ans":"所以你的学生做的任何投资于他们头脑和身体的事情，尤其是头脑，我们这儿对身体没怎么下功夫，但是，你看，那是有回报的。回报的方式非常惊人。你最好的资产就是你自己，你可以在极大程度上成为你想成为的那个人。我去大学上课的时候，我就让他们想象，他们要买一个同学，拥有那个人余生10%的股份。他们会选谁？他们不会选智商最高的那个，也不一定是成绩最好的那个。他们选的是那个会有效的人。而人之所以有效，是因为别人愿意跟他共事，愿意待在他身边。而有些人，别人不愿意待在他们身边。","kind":0},{"y":2008,"at":0,"ask":"主席先生，副主席先生，我叫Andy Peake，来自康涅狄格西部。美国人在个人、市、州和联邦层面上历来都不储蓄。另一方面，亚洲人储蓄大约","ans":"那个，我不，我不知道那个，你知道，储蓄率是基于消费和进口等等的计算，我们进口的商品和服务比出口多7000亿美元，这意味着基本上是别人在替我们储蓄，因为我们在出口美国的所有权和债权。我觉得随着时间推移这会有后果，但我们太富了，可能不会那么明显。","kind":2},{"y":2008,"at":0,"ask":"我是洛杉矶的Bob Kline。接着上一个问题，您能谈谈全球主要金融机构财务报表的准确性吗？应该怎么做才能正确估值它们的资产","ans":"而且我觉得，这个约束——虽然可能比较温和——告诉管理层你们得按市值给这些东西估值，可能就会阻止他们做一些本来会做的蠢事，如果他们以为自己能蒙混过关、用某种虚构的估值，或者用成本价，而那在市场意义上就是虚构的。所以我倾向于，我倾向于市值法。我不知道，当你碰到真正复杂的工具时，我就是不知道怎么给它们估值。","kind":0},{"y":2008,"at":0,"ask":"先生们，我叫Mark Slaby，来自芝加哥。我大概是今天最后几个发言或者提问的人了，所以，我代表三万一千人，向你们表示感谢。谢谢你们的尊重。","ans":"我不知道你们个人能对此做些什么，我也不知道你们怎么去给那些大机构创造激励机制让它们去做这件事。我是说，这对它们个人来说其实没什么太大好处。我不觉得——我觉得，机构用来判断是否认可公司做法的很多清单，都是愚蠢的。我是说，它们，你看，它们把问题交到你手上，然后有人来建议它们怎么投票代理权，这挺傻的。我不懂为什么它们不能自己拿主意，判断什么是合适的什么是不合适的。Ben Graham很多年前就感叹过，投资者就是一群羊，而在大机构身上，我也没看出多大区别。","kind":0},{"y":2008,"at":"04:24:24","ask":"你好，我是Clement Lowe，来自加拿大多伦多。我想感谢你们办了这么棒的会，我觉得在这里几个小时学到的东西，比大学里很多很多个小时学到的还多。我的问题是，你","ans":"嗯，这是个好问题，而我们跟很多企业不一样，如果我们，当我们投资像制药这样的东西时，我们不知道管线上的答案，而且五年之后管线反正也会不一样了。所以我们，我们不知道是Pfizer还是Merck，你知道，或者你随便说，Johnson & Johnson，我们不知道它们当中哪一个会在三四年后搞出一个重磅商业药物，我们也不去试着评估那个。","kind":0},{"y":2009,"at":0,"ask":"抱歉。嗨，我叫Sarah，来自内布拉斯加州的奥马哈。我想知道您能不能解释一下您的策略，也就是价值投资，在培养下一代投资者方面。您会怎么教这","ans":"那个，但如果你知道怎么给一家企业估值，你不需要知道怎么给所有企业估值。在New York Stock Exchange上，我不知道，大概有4000或5000家企业，NASDAQ上还有更多得多。你不需要在4000或5000家里都做对。你不需要在400家里都做对。你不需要在40家里都写对。你只需要待在你的能力圈里，你能理解的东西，然后在你能估值的那些里找那些卖得比价值便宜的。你可以从一个相当小的能力圈开始，随着时间推移多了解一些企业。但你会学到，有一大堆企业根本不适合估值，那些你就忘掉它们。","kind":0},{"y":2009,"at":0,"ask":"抱歉。嗨，我叫Sarah，来自内布拉斯加州的奥马哈。我想知道您能不能解释一下您的策略，也就是价值投资，在培养下一代投资者方面。您会怎么教这","ans":"而且在很大程度上，这不是智商的问题。如果你，如果你在投资这行，你有150的智商，卖掉30点给别人，因为你不需要。我是说，那个，对，你需要相当聪明，但你完全不需要是个天才。事实上，那可能有害。所以，但你确实得有情绪上的稳定，你得对自己的决定有一种内心的平静，因为这是个你每分钟都受到刺激的游戏，人们一直在给你意见。你得能自己思考。我不知道，我不知道这有多少是天生的，有多少是可以教的。但如果你有那个品质，你在投资上会做得很好，只要你花些时间在上面，学点给企业估值的东西。","kind":0},{"y":2009,"at":0,"ask":"早上好。我是来自肯塔基州路易斯维尔的Steve Fulton。我今天下午放弃了Kentucky Derby的包厢票，跑来问你这个问题。谢谢给我这个机会。我的问题跟你怎么看……有关。","ans":"我们看，我觉得你应该看一门生意，就像看你买的那栋公寓楼，或者你想买的那个农场一样。人们让每天都有报价这件事变成了负债，而不是资产。我只想说，你最好回去读《The Intelligent Investor》第8章，那里面讲了该怎么看待市场，那比学什么现代投资组合理论对你有用得多。好，第7个。","kind":0},{"y":2009,"at":"01:46:40","ask":"有了这个更小的资产规模，你会怎么做不同，无论在持仓数量还是换手频率上？比如说，如果你持有10只股票的组合，其中5只在短时间内翻倍了","ans":"我们会持有我们最喜欢的那么六七只股票，完全不管我们的成本是多少。只跟我们对其价格对价值的评估有关。那成本是多少就无所谓了。而且立刻，如果它们跌了50%，我们还是会说同样的话。我，你知道，用你的例子，我不知道那个基金实际上有没有什么东西涨了或跌了。","kind":0},{"y":2009,"at":0,"ask":"亲爱的，我叫Sam Alter。我11岁，来自新泽西州的West Wings。我的问题是，通货膨胀会怎样影响我这一代人，Berkshire又是如何投资来为此做准备的？","ans":"所以它们曾经是一种有定价权的产品，对客户来说不可或缺，本质上是对广告主不可或缺。而它们已经失去了那种不可或缺的性质。它们曾经是，30年或40年前，如果你想了解跑车或者股价，甚至国际事务的新闻，它们是首选。然后那种性质，Walter Annenberg过去称之为“不可或缺性”，我不知道这个词在不在字典里，但它开始被侵蚀，然后侵蚀急剧加速。而它们只有在对读者不可或缺的时候，才对广告主不可或缺。而且，你知道，没人喜欢在报纸上买广告。只是广告确实有效。而这正在改变。每天都在变。我在 horizon 上看不到任何能让这种侵蚀停止的东西。","kind":2},{"y":2009,"at":0,"ask":"亲爱的，我叫Sam Alter。我11岁，来自新泽西州West Wings。我的问题是，通货膨胀会怎样影响我这一代人，Berkshire是怎么投资来为此做准备的？","ans":"《Post》有一块很好的有线电视业务。有一块很好的教育业务。但在报纸业务上没有答案，就像Don Graham在年报里写的那样，别人也没有。我们都在四处找，看谁能找到一个模式，但我觉得美国现在大概有1400份日报，还没有人找到那个模式。信不信由你，我觉得我们在Buffalo的处境，跟任何人一样好，可以把这个局打下去。但到底是我们能在亏损变得不可逆转之前找到办法，还是情况会变得更糟、不可逆转地亏损，我不知道。但我们会尽可能长久地打下去。这不是商学院教你的东西，但这就是我们经营Berkshire的方式。Charlie？","kind":2},{"y":2009,"at":"02:12:41","ask":"早上好，巴菲特先生和芒格先生。我是来自澳大利亚墨尔本的马克·拉比诺夫。我想问一下，我们的零售、制造和服务业务都受到了衰退的严重冲击。Gi","ans":"三年后的事我不知道。当然，你提到的那些领域，不同程度地受到了很大打击。有些制造业跟住宅建设相关。如果我们把房屋开工量维持在每年50万套，你知道，我猜几年之内，大部分，我们会在住房方面接近均衡，也许还会快不少。我，没人能精确知道数字，但如果你每年组建130万左右的新家庭，而只建50万套新房子，再加上一些老房子烧掉了什么的，你会在一个不算太遥远的未来达到均衡。那会对我们的地毯业务、砖块业务、绝缘材料业务和油漆业务等等产生很大影响。","kind":2},{"y":2009,"at":"02:26:34","ask":"我是来自新泽西州霍沃思的杰克·本本。首先我想感谢你们。这是，我来过大概十几次会了，这可能是最好的一次，所以非常感谢你们的新形式，也非常感谢jo","ans":"嗯，这个问题从广告诞生那天起人们就在问自己了。而且，你知道，我不确定是Marshall Field还是Campbell Soup的John Dorrance还是什么，那些家伙里有一个说过，你知道，当我问他是不是在广告上浪费了很多钱，他说：“是啊，我们浪费了一半，我们不知道是哪一半。”这就是广告的本质，不过我们通过GEICO能比大多数公司更好地衡量它。","kind":4},{"y":2009,"at":0,"ask":"好。你好，Warren、Charlie。我是Felton Jenkins，来自佐治亚州萨凡纳，长期股东和合伙人。我只想简单评论一下过去几年关于PacifiCorp的一件大事。T","ans":"但我在爱尔兰银行上犯了大错，错得很离谱。我就是没搞懂，我本应该搞懂的，我本来是有条件搞懂的，它们对土地开发类贷款的敞口大得惊人，不是那种已建成物业的房地产贷款，而是各种土地开发贷款。那真是非同寻常……对一个只有四百多万人口的国家来说，你知道，他们把钱借出去开发房产，那些房子要一直延伸到遥远的未来。这是我的一个糟糕的错误。没人骗我，没人给我任何错误信息。我就是纯粹没留意。","kind":4},{"y":2009,"at":0,"ask":"好。嗨，沃伦、查理。我是来自佐治亚州萨凡纳的费尔顿·詹金斯，长期股东和合伙人。我只想简单评论一下过去几年关于PacifiCorp的一件大事。T","ans":"银行业确实有实实在在的差异，但人们不，他们似乎不看这些。数字都在那儿，但是，但他们似乎不怎么仔细看。Wells前几天报业绩的时候，他们有一项费用，一个季度超过6亿美元，是核心存款的摊销。那不是真实的费用。我是说，核心存款的数字会随着时间上升，而且根据税法他们有权计提，我不知道，大概150亿美元左右，然后他们可以摊销，这是个优势。但我没看到一篇报纸文章或任何评论员提到那6亿美元的费用在里面，这跟看任何其他银行是完全不同的。但就是，没人注意到。所以数字在那儿，信息也在那儿。","kind":1},{"y":2009,"at":"02:49:08","ask":"好。你好，Warren，Charlie。我是Felton Jenkins，来自佐治亚州萨凡纳，长期股东和合伙人。我只想简单评论一下过去几年关于PacifiCorp的一件大事。T","ans":"我马上把这个交给Charlie。但Charlie和我觉得，除了价值投资之外没有别的投资。换句话说，我们不知道怎么会有人去做非价值投资。所以我们一直对“价值”这个词感到困惑，还说什么跟成长或别的什么对比。价值关系到你今天付出什么，换回未来可预期的现金回报能有多少。所以我们一直，每次有人把我们说成价值投资者，我们总是问他们还能有别的什么类型。但Charlie是我们这里负责BYD的队长，他会很激动，我可能得控制他一下。来吧，Charlie。","kind":0},{"y":2009,"at":"02:56:17","ask":"你好，Buffett先生和Munger先生。我叫Dan Lewis，来自芝加哥。我的问题关于美元兑其他主要货币。你已经谈了一点政府政策及其影响……","ans":"是啊，这相当难以预测。但是，我向你保证，美元在5年、10年、20年后能买到的东西会更少，你知道，而且可能，可能会少非常非常多。但显然我不知道。但我们在做的事情会损害美元的购买力。另一方面，全世界各个国家也在发生同样的事。所以很难说美元兑英镑或者美元兑欧元等等会怎么走，因为，你知道，英国人今年会跑出一个占GDP 12%多一点的赤字，就连德国人，带着他们，你知道，那种长期的通胀恐惧，大概也会跑出占GDP 6%多一点的赤字。","kind":2},{"y":2009,"at":"03:30:50","ask":"下午好。我是来自新泽西州蒙特克莱尔的迈克·诺兰。直到最近，美国的学生贷款业务一直是非常有吸引力且成功的。然而，华盛顿提出的改革方案将会","ans":"查理和我考虑申请学生贷款那都是很久以前的事了，所以我们没太仔细查过那方面的规定。但是，你知道，我们对此了解不多。实际上有人来找过我，我猜大概是一年还是一年半以前，关于Sallie Mae那笔没谈成的交易。我当时跟打电话给我的那个人说，我不太懂这个，结果我不懂倒是件好事。安德鲁？","kind":4},{"y":2009,"at":"03:31:50","ask":"下午好。我是来自新泽西州Montclair的Mike Nolan。直到最近，美国的学生贷款生意一直是非常有吸引力、非常成功的。但是华盛顿那边提出的改革方案……","ans":"嗯，我可以说，我可以争辩说，过去15年里，美国产业中有相当大比例的公司，在某个时候都做过盈余管理，我亲眼见过，也反对过，但没什么用。所以我不认为这是什么罕见的毛病。我什么都不知道，我不会去谈那些公司的具体细节。我对那些公司感觉不错，从它们生意的质量和管理的质量来看。但主要是条款让我们做了那些交易。我是说，那些交易是在市场一片混乱的时候做的，那时候你投入资金就应该拿到非常好的条款。很少有人愿意，或者在大多数情况下有能力，在短时间内投入大笔资金，所以我们需要好条款才做。","kind":0},{"y":2009,"at":0,"ask":"我是来自菲律宾的Vishali。我的问题是关于资本密集型子公司的薪酬。现在，我冒昧地假设，大量银行倒闭在很大程度上是由……引起的","ans":"Charlie和我对本地一家公司相当熟悉，Peter Kiewit Organization，还有Pete Kiewit，我不知道，50多年前或者更早，你知道，他想出了一个非常非常合乎逻辑的办法来给公司里的人付报酬。那不是什么火箭科学，我保证他没有就这个问题咨询过任何薪酬顾问。他就是自己想出来的。你也能想出一个来，我也能想出一个来。但你必须明白，不是每个CEO都想要一个理性的薪酬体系。你知道，当非理性回报更高的时候，谁还要理性呢？所以要让人们在边界上……这确实是个问题。","kind":4},{"y":2009,"at":0,"ask":"好。现在，我想增加我在Berkshire Hathaway的投资，我觉得我们已经确认了这是一家很棒的公司。所以我还剩几个其他问题，对外国人来说可能有点不一样……","ans":"我们从来没有预先设定，也根本没有目标，说要在这里或那里发展出X%的利润。我们就是每天去上班，你懂的，我们不知道电话会从以色列打来还是从印第安纳打来，给我们一个投资的机会。我们希望所有子公司都在各个地方寻找机会，有些会在海外找到，有些不会。","kind":0},{"y":2010,"at":"00:41:05","ask":"早上好，Buffett先生和Munger先生。我叫Guy Pope，来自俄勒冈州波特兰。我很好奇你们对国会目前正在推进的金融改革的看法。具体来说，哪些是好主意","ans":"是的，就我现在对法案的理解，几天前提出的那个，我可能理解错了，但我觉得我理解对了，我读了那些条款，要求会是零。那个，如果我们被发现，Berkshire被发现是一个，我不知道法案里的确切术语，但基本上是财政部长或者我相信某个委员会认定对系统有危险，那么我们可能会被要求对追溯性合同、对过去签的合同提供抵押品。","kind":2},{"y":2010,"at":0,"ask":"是关于希腊、欧元的未来，以及全世界的财政纪律，还有我们作为投资者必须做好的准备。过去，您一直在警告我们美元的结构性弱点。","ans":"我不知道这部电影怎么结尾。这不意味着我在预测灾难什么的。我真的就是不知道这部电影会怎么收场，我尽量不去看那种电影，如果能不去的话，但我会盯着看的。我真的，这会是，在我看来，这里发生的事会是高度戏剧性的。","kind":2},{"y":2010,"at":0,"ask":"你好，我叫David Clayman，来自伊利诺伊州芝加哥。这个问题是给Buffett先生和Gates先生的，主要是作为Berkshire股东，但也是作为Bill and Melinda Gates Foundation的受托人。那个引导","ans":"我不知道，你知道，我不知道那个项目会有多重要，但每个人都有兴趣降低死亡率，GEICO有一个非常积极的安全项目，测试汽车，做各种事情，通常和其他保险公司合作。我不认为，我是说，Gates Foundation在我看来有相当具体和明智的指导方针来决定他们把活动投向哪里，他们相信专注。所以他们不会试图解决世界上的每一个问题。但我可以向你保证，保险业以及汽车公司总体上都在持续努力让汽车更安全。Charlie？","kind":3},{"y":2010,"at":"01:24:54","ask":"嗨，我是来自肯塔基州路易斯维尔的Steve Fulton。再说一次，我放弃了肯塔基德比的包厢座位来问你一个问题，我很感激这个机会。我的问题集中在转变上，如果你愿意的话，","ans":"嗯，我想说，如果我现在写那个问题，我可能会写同样的问题，但我不确定他二月份会不会写同样的问题。现在，投资中的风险特征显然不同，事实是我不知道Harley-Davidson的股票是值33还是20还是45。我对此没有看法。","kind":2},{"y":2010,"at":0,"ask":"嗨，我是来自肯塔基州路易斯维尔的Steve Fulton。再说一次，我放弃了肯塔基德比的包厢座位来问你一个问题，我很感激这个机会。我的问题集中在转变上，如果你愿意的话，","ans":"我不，你知道，我挺喜欢那种客户把你的名字纹在胸口之类的生意，但要算出那东西的经济价值，而且，你知道，我不确定，就算继续追问那些人，我从他们身上学到了很多。但我确实知道，或者我以为我知道，而且我觉得我是对的，我是对的，那就是，第一，Harley-Davidson不会倒闭，第二，15%会看起来相当有吸引力。事实是，我们大概能卖掉那些债券，我不知道，差不多在，大概135左右吧。","kind":2},{"y":2010,"at":"01:49:17","ask":"我叫Lucas Rimswell，来自Whangarei，万一您不知道Whangarei在哪，它在新西兰。现在新西兰是凌晨四点一刻，所以我可以说我妻子","ans":"嗯，一个办法是可以征收财富税。我是说，你可以征税，我不知道现在有多少国家这么做，Charlie。实际上，某种程度上房产税就有这个效果，但你可以搞财富税。我要说的是，他完全正确。如果你想把所有的钱都捐出去，那是个绝妙的避税手段。而且，不过我也要说，在我刚提交的税表上，慈善捐赠那一栏，我有超过70亿美元的未使用结转额度，我还没拿到抵扣。所以，但我欢迎这个问题，也欢迎任何其他人效仿我的避税例子，把自己的钱捐出去。他们那样能省很多税，而且那些钱大概会做很多好事。","kind":0},{"y":2010,"at":0,"ask":"你好。嗨，巴菲特先生。我叫Jeff Chen，来自旧金山。我想问您更多关于通胀问题的细节。我想知道您评估时看哪些关键指标，那个指标","ans":"我们不，我们有能力做事，国会有权力，这就是为什么我一年前写了那篇专栏文章，算是闪个黄灯。我们有能力控制我们的未来，我们通过民选代表来做。我就回到那个结论，基于我看到正在发生的事情，美国人民、政府、全世界，我认为货币比一段时间以来是更差的赌注。但我不知道这在通胀率方面意味着什么，我希望我在这上面是错的。","kind":2},{"y":2010,"at":0,"ask":"亲爱的巴菲特先生，亲爱的芒格先生，我叫Steven Roman。我是奥地利维也纳大学工程机械专业的学生。如果有一天我想申请伯克希尔旗下公司经理职位，","ans":"所以如果你看2009年年报的后面，我想是第11条，或者我不确定，但读一下经济原则，你会看到我不得不承认我的错误以及我最初是怎么措辞的。但我，我认为，我认为这在智力上仍然是诚实的，关于达到我，我打算说的。你知道，我在投票支持它之前投票反对它，或者类似约翰·克里在2004年说的那样。我，我认为，我，我认为它确实符合一美元留存收益产生超过一美元市场价值的检验，而且，而且我们将继续基于是否达到这个检验来衡量自己。如果我们没有，如果保留一美元不能产生超过一美元的现值，我不是说每天或每周，而是随着时间，我们，我们应该想办法做点别的。查理？","kind":0},{"y":2010,"at":0,"ask":"第五号。我叫Robert McArthur，来自马萨诸塞州波士顿。我刚开始投资生涯，很多——如果不是大多数——我这个年纪的投资者都认为自己是价值投资者。另外，这里来的人数创了纪录，","ans":"如果你是债券保险公司，你担心的大事是传染。很明显，债券保险公司，除了Berkshire以外，在我看来，债券保险公司的负债相对于资本来说高得离谱，几乎每一家要么倒闭了要么实际上倒闭了，不得不搞个坏银行对好银行之类的拆分，就因为它们在涉足结构化证券时遇到的麻烦。而且我觉得它们对那个领域可能发生的事一直抱着非常乐观的态度。但我不知道未来几年违约率会是多少，这个答案我不知道。我知道一年半前我觉得承担那个风险拿到的报酬是合理的，而现在我不觉得人家给我们的溢价是合理的，所以我们就让别人去做吧。Charlie？","kind":2},{"y":2010,"at":0,"ask":"下午好，巴菲特先生和芒格先生。我是来自佛罗里达州劳德代尔堡的Srinivas Canadial。首先，我想感谢你们如此慷慨地与我们分享智慧。早在2008年10月，您高度推荐","ans":"但我不喜欢，我不知道股市下周、下个月或明年会怎么走。我完全没概念。人们总以为我知道。我，我知道我根本没概念。我不去想它。这没什么区别。查理和我，我不，我基本想不起来我们有过关于这个的讨论，你知道。但我确实认为未来10年或20年，我更愿意持有股票，包括美国股票。我更愿意持有它们而不是现金，或者我更愿意持有它们而不是10年或20年期债券。但这部分是因为我对替代选择非常不热衷。我认为，我认为股票可能会随着时间给你一些正的、温和的正实际回报，但除此之外我真的什么都不知道。查理？","kind":2},{"y":2010,"at":"03:26:48","ask":"Mike McCoy，来自旧金山。巴菲特董事长，您经常乐观地谈论后代的繁荣，说我们的孩子和孩子的孩子会比我们过得更好。我们当前的","ans":"石油行业，很明显，石油的发现，大概是在1850几年，在宾夕法尼亚州泰特斯维尔的某个Drake上校，什么的。那件事以非常重大的方式改变了世界，而那不过是150年前的事。从那以后，我们一直以惊人的速度往地里插吸管。美国有超过50万口生产井，你信吗？我是说，平均每天11桶、10桶左右的样子。我是说，我们真的已经开采了可能需要——我不知道，几十万年还是几百万年才形成的东西。它对世界的繁荣做出了巨大的贡献。","kind":1},{"y":2010,"at":0,"ask":"来自旧金山的Mike McCoy。巴菲特董事长，你经常乐观地谈论后代的繁荣，我们的孩子和孩子的孩子会比我们过得更好。我们目前的多少","ans":"现在，你知道，Irene是一个完全有能力的经理，她可能知道很多我不知道的关于那个业务的事情，而且，就像我说的，我们自己犯了很多错误。但是，如果是我，我会投票保留披萨而不买Cadbury。我表达了我的意见，我不，我不经常这样做，但我们拥有很多Kraft。Kraft的售价仍然远低于其组成部分的价值，特别是如果你像你估值那样估值它们，不能，他们估值Cadbury。","kind":4},{"y":2010,"at":"03:43:44","ask":"亲爱的巴菲特先生，亲爱的芒格先生，我叫Richard Rentrop。我是来自德国的股东。芒格先生，您刚才又提到了诚信的重要性。我的问题是关于管理层诚信的变化。关于","ans":"这不是最大的那个。我们见过几个对我们大声尖叫的，我们也见过几个估值过高的时期对我们大声尖叫，而90%的时间我们处于中间某处，我们不知道确切在中间哪里。害怕这件事，你知道，我，我不知道你对此怎么办。如果，如果你是那种，如果你有那种气质，当别人恐惧时你自己也会害怕，你知道，你不太可能随着时间在证券上赚很多钱，很可能。那，你知道，人们真的，如果他们不看报价……但当然全世界都在敦促他们看报价，而且不止如此，根据报价的小变化做点什么。","kind":0},{"y":2010,"at":0,"ask":"嗨，我叫Kip Johann-Berkel，来自马萨诸塞州波士顿。首先，感谢你们两位的著作、年度股东大会，甚至Charlie Rose的采访，因为它们帮助我成长为一名投资者，也","ans":"我非常同情他们，就是，你知道，基本上他们，很多人是在2008年底世界看起来要崩溃的时候变得恐惧的，他们付出的代价真的，我认识一些这样的人，但就回报而言太糟糕了，他们的购买力会被侵蚀掉。但这总会在某个时候结束。我不知道它会怎么结束，但我不想当美联储主席或者财政部的人。从来没人问过我，但也许这就是为什么我说我不想干那活。","kind":2},{"y":2010,"at":0,"ask":"没关系。让我分享一点。我在获取年度报表信息时遇到了一些麻烦，所以我终于上网了，一周前的周五，昨天寄了明信片请求，我在会议前拿到了票","ans":"最严重的保险损失，我不知道Katrina最终是不是达到了700亿美元左右。我认为就最坏情况而言，我猜如果那种情况发生，而我们有一个正常年份和其他一切，Berkshire仍然会有相当数量的正收益。所以我们准备好了。Charlie？","kind":2},{"y":2011,"at":0,"ask":"Jeremy Pose，来自马萨诸塞州牛顿市。巴菲特先生和芒格先生，Berkshire Hathaway在Wells Fargo和U.S. Bank有大量投资。这两家银行的收入前景和业务前景如何","ans":"我们仍然认为Wells Fargo和U.S. Bank是非常好的机构。我们认为它们是很不错的企业。但它们不如杠杆率可以更高时那么有吸引力了。说到银行业的麻烦，我……我觉得最糟糕的时候已经过去了，贷款损失已经连续几个季度呈下降趋势，我想预期是会继续下降。我认为银行业是一个非常基础的业务。但就像John Stumpf几年前在Wells Fargo说的，他说：'我不明白为什么我们老想着找新法子亏钱，明明老法子还挺好使的。'你知道，银行隔一阵子就发疯。总是在资产端。","kind":2},{"y":2011,"at":0,"ask":"我是马萨诸塞州牛顿市的Jeremy Pose。巴菲特先生和芒格先生，Berkshire Hathaway在Wells Fargo和U.S. Bank都有大笔投资。这两家银行的收入前景和业务前景如何？","ans":"所以，我喜欢我们在那里的仓位。你去看那些总数，你会看到我们增持了Wells Fargo，而且……我觉得这两家……这些公司都是经营得非常好的机构，但它们没法再赚……我不知道具体数字是多少，但我觉得有形股本回报率到了25或30，这个未来不会重演，也不该重演。Charlie？","kind":2},{"y":2011,"at":"01:57:01","ask":"是的。德州达拉斯的Little Miller。Buffett先生，Munger先生，你们当初募集第一笔投资基金时，是怎么吸引投资人的？一旦你有了第一笔基金和第一批投资人，你们又是怎么","ans":"听起来像是个准备开对冲基金的人。他们……就我来说，1956年3月左右我从纽约搬回这里，有几个家庭成员说：“我们想让你帮我们管理投资，”就像我去纽约之前在这里卖证券时做的那样。我不喜欢做证券销售这一行，部分原因是，如果我卖给别人一只20美元的股票，它跌到10美元，我想买更多，但我没法面对那些在20美元买入的人——他们买只是因为相信我，而不是因为他们理解它——现在他们感到沮丧，那……那真的不……不太令人满意。如果人们盯着每一个决定，我管钱就做不了像我一个人在房间里做时那么好。","kind":4},{"y":2011,"at":0,"ask":"嗨，Warren和Charlie。我叫Catherine Borud，来自加州洛杉矶。我主要投资大宗商品和大宗商品股票。我2007年开始买石油。2008年夏天，我们到了——","ans":"我不知道全世界是不是到了每天8800万桶，还是……不是8500万桶左右，但总得有些回升。所以我不会惊讶……目前数字已经挺接近每天8800万桶了。每天从地下抽出来那么多油。当然，也发现了新的前沿地区，但你……你往地球里插了很多吸管，而它是有限的。所以有一件事我可以向你保证，作为……几乎可以保证，就是石油有一天会卖得贵得多。","kind":2},{"y":2011,"at":"02:42:16","ask":"嗨，Warren和Charlie。我叫Catherine Borud，来自加州洛杉矶。我主要投资大宗商品和大宗商品股票。我2007年开始买石油。2008年夏天，我们到了","ans":"但我不知道。你知道，我们传统上……BNSF对冲了一定量的石油，因为他们显然用大量柴油。我向他们建议过，虽然BNSF怎么运营是他们的事，但我只是……我真的不认为我们能猜准油价，我觉得如果我们能猜准油价，就不需要经营铁路了。我是说，那……经营那条铁路要花很多精力、时间，如果我们知道只要坐在房间里交易石油就能赚钱，为什么不干脆那么做呢？所以我真的……我们不对冲。就Berkshire母公司的政策而言，我们不对任何大宗商品做对冲。我们有些子公司会做，那没问题。它们为自己的业务负责。但很少有哪类大宗商品，我会觉得自己能知道它未来六个月或一年的走向。","kind":0},{"y":2011,"at":"02:44:27","ask":"嗨，Warren和Charlie。我叫Catherine Borud。我来自加利福尼亚州洛杉矶。我主要投资大宗商品和大宗商品股票。我早在2007年开始买石油。2008年夏天，我们达到了","ans":"是的，我们不是试图让它变得比必须的更困难。我真的不知道在那类活动中有什么方法能获得优势。我是说，如果你要试图弄清楚什么时候做多或做空石油、天然气、铜、棉花或其他什么，我不知道……我不知道有谁我觉得在未来10年试图这样做会有优势。但我确实知道有些人，我认为他们在投资普通股方面会有非常显著的优势，也许还有困境债券，就此而言，也是。","kind":0},{"y":2011,"at":"02:57:33","ask":"下午好，巴菲特先生和芒格先生。我是Marc Rabinov，来自澳大利亚墨尔本。作为亚洲地区的投资者，我担心美元走弱会侵蚀我持有的Berkshire股票价值。不过，Berks","ans":"答案是不行。要是澳元跌下去那就容易多了。澳元是我们去年做的两种货币之一，贡献了那1亿美元的利润。但不行，我没法告诉你美国会采取什么政策、澳大利亚会采取什么政策，那些政策会是什么样，以及它们会如何影响这两种货币比如10年后的相对价值。我认为汇率变动可能相当剧烈，而且我认为两个方向都可能很剧烈。所以我不知道该怎么做。","kind":2},{"y":2011,"at":"03:04:31","ask":"嗨，我是Whitney Tilson，来自纽约的股东。感谢您在最新年度信中对Berkshire给出了如此完整清晰的估值信息。您说保险业务的运营收益","ans":"是的，Whitney，我同意这一点。但是，很难估计未来20年左右的正常承保利润会是多少。所以我同意你。我不知道该不该叫它过度保守。我会说，假设承保盈亏平衡是保守的，但你也知道，我是说，如果我们再来一次Katrina之类的，别提欧洲的冬季风暴那些了，我是说，今年承保就可能亏大钱。而且我们预期承保会亏大钱，你知道，也许每50年或每10年一次，谁知道呢。但我认为你说得对，在年报里我做的计算之外，再加上一些正常化的承保利润，并不算不合适。","kind":2},{"y":2011,"at":0,"ask":"我的朋友Walt想知道，Berkshire有没有考虑过像拆分B类股那样拆分A类股，如果有，你觉得利弊是什么，短期和长期","ans":"我们在再保险领域一个接一个地进入新领域，当人们进来模仿我们在某个业务领域的做法时，能源那边又冒出别的东西。最近我们在寿险再保险方面活跃得多，但谁知道明天会怎样。我是说，如果今年第三季度碰巧来一场大灾难之类的，当产能吃紧时，那可能会打开各种承保机会。但谁知道会发生什么。我只知道Ajit的脑子像机器一样运转，日复一日，而且他确实热爱自己做的事，这在任何活动中都是做好事情的重要部分。我真的，我不知道他最好的交易是哪一笔。我知道我最好的交易是什么，就是雇用了他。Charlie？","kind":2},{"y":2011,"at":0,"ask":"Keith McGowan，马萨诸塞州诺福克。谢谢巴菲特先生和芒格先生。谢谢你们作为榜样：你们的道德、节俭、幽默感、诚实、分享投资理念、分享商业理念","ans":"你可以去找你的同伴们帮忙，但放弃用自己货币发债的权利是巨大的一步，而美国还没有这么做。我不知道我们有没有用其他货币发行过美国债券，但我们肯定没有养成这个习惯。顺便说一句，日本，债务占GDP的比例非常高，也一直用自己货币借债。","kind":0},{"y":2011,"at":"04:03:19","ask":"好的。下午好，巴菲特先生和芒格先生。我是来自爱荷华州爱荷华城的John Gory，我是MidAmerican Energy的满意客户。大概在2004年，巴菲特先生，您跟我们讲过您非常关注限制","ans":"是的，我不认为它构成，我不知道细节，Greg Abel能比我讲得更好，但我不认为存在你提到的那种风险敞口。我认为核电是世界解决问题的重要一环。这是非常长期的，因为你不可能很快改变已建成的装机容量。如你所知，法国核电比例非常高，实际上美国20%的电力来自核电。","kind":0},{"y":2011,"at":"04:23:57","ask":"小姐，巴菲特先生，芒格先生，很荣幸也很高兴。我叫Ben Anderson，来自洛杉矶。当您考虑在中国投资时，那里的商业文化很不一样，很多方面都不同","ans":"我们遵循同样的原则，但我们承认，一旦走出美国，我们对税法、习俗、对股东的态度了解得都比在美国少。当然，程度不同，我们会把这种不确定性考虑进去。我买PetroChina股票的时候，大概是2003年吧，跟任何储量、炼油能力、现金流之类的计算相比，它都便宜得离谱。同时，俄罗斯的Yukos也同样非常非常便宜，而且两家都是巨头。你知道，我不是地缘政治专家之类的，但我决定买PetroChina比买Yukos让我更踏实。","kind":4},{"y":2011,"at":0,"ask":"先生，巴菲特先生，芒格先生，很荣幸也很高兴。我叫Ben Anderson，来自洛杉矶。当你看中国的投资时，那里的商业文化很不一样，很多方面都不一样——","ans":"那么，我买PetroChina的时候，是不是像买一家类似规模的美国本土公司那样放心？不，因为我知道的没那么多。我当时不知道，现在也没那么了解中国税法的所有复杂之处、政策可能会怎样。但我读了PetroChina的报告后，印象相当深，非常深。一方面，他们说会把——我记得是——把盈利的45%拿出来分红。这比任何一家美国石油公司会告诉我的都多。所以我把这看作一个加分项，也是我认为会兑现的意图信号，而它确实兑现了。","kind":4},{"y":2011,"at":0,"ask":"先生，巴菲特先生，芒格先生，很荣幸也很高兴。我叫Ben Anderson，来自洛杉矶。当你看中国的投资时，那里的商业文化很不一样，很多方面都不一样——","ans":"而我们能在人们需要钱的时候、在全世界不知为什么吓呆了的时候拿出钱来，这让好几笔交易做成了。我们不知道明天还能不能这样。我是说，你知道，如果Ben Bernanke跟Paris Hilton跑到南美去了什么的，我是说，谁知道呢，谁知道会发生什么。我们希望在那一刻我们的支票能兑现。所以我们想，永远不知道明天会带来什么，虽然不会带来那个。我想把那段从报告转录里去掉。但是，当有人来找我们说“我们现在就要做一笔交易，现在就要”，我们能做，他们知道我们能做，而且可以很大。只要够有吸引力就行。好，第10区。","kind":3},{"y":2011,"at":0,"ask":"下午好。我叫Christopher David，是弗吉尼亚州阿灵顿的一名创业者。我的问题关于年轻人。我和很多高中生、大学生以及刚毕业的年轻人一起工作，他们正面临就业","ans":"而且，你看，这就像手里有一对骰子，然后你接受别人在牌面上的下注之类的。你知道，它每36次才会出现一次，所以你可以通过给出错误的赔率赢很多赌注。但如果你一直这么做下去，时间够长，你就会亏很多钱。所以这些不常发生的事件，你最好已经把它们考虑进你的定价里了，别因为某一年或者两年、甚至三四年赚了钱就骗自己。大多数人在这上面都有点问题，我们大概有15年也在这上面有点问题。","kind":0},{"y":2011,"at":0,"ask":"嗨，我是来自纽约的Glenn Tongue。首先，感谢你们带来精彩的一天。我的问题关于收购。在Lubrizol之前，我们估计Berkshire 2011年底的现金余额可能接近600亿美元。我相信你","ans":"我是说，如果你看未来20年，你知道，住宅房地产会有三四个糟糕的年份，也会有很多相当不错的年份，还会有几个特别好的年份。我不知道它们出现的顺序，但我知道，如果我能以足够便宜的价格买入资产，参与到这20年里，那我们在那段时间里就会做得不错。所以这就是我们做砖头生意的原因。现在，让我看看。对，现在是3点半，所以我们休会大约五分钟，然后我们将进行Berkshire Hathaway的正式会议，我们可以把灯调亮，几分钟后我们就回来。（掌声）","kind":2},{"y":2012,"at":0,"ask":"早上好，巴菲特先生，芒格先生。我叫弗恩·库欣伯里，我代表一群从堪萨斯州欧弗兰帕克赶来的投资者问这个问题。MidAmerican在风能方面有大量投资……","ans":"我，我不一定知道肯·切诺特或者穆赫塔尔·肯特或者约翰·斯顿夫的政治立场。有一段时间我对科瓦切维奇比较了解。但是，他们经营这些企业，我们有十，吉尼·罗梅蒂，我是说，我们在她那里有110或120亿美元。我不知道她的政治立场，而且，你知道，我也不知道她的宗教信仰。她肯定有各种各样的个人观点，可能比我的还好，但那无所谓。我只想知道她怎么经营企业。","kind":0},{"y":2012,"at":"01:35:06","ask":"早上好，沃伦和查理。很高兴你们身体都好。我叫Ryan Boyle，在芝加哥一家私募股权公司工作。如果您是我，有机会重新开始，您会关注哪些领域去投——","ans":"是啊，我们，我们知道我们不知道什么。而且我们都，我们知道我们不想破产。我是说，我们就从这出发。我们知道只要你手头有相当数量的流动储备、没有短期债务之类的，你就不会破产。所以我们的第一条规则永远是明天还能接着玩，不管发生什么。但如果我们把这一点覆盖住了，又能找到有吸引力的东西，我们就买。你看，查理有家小公司叫Daily Journal Company，他坐在那儿手里一大把现金，2008年来的时候他就出去买了几只股票。他不肯告诉我名字。但是，他，你知道，那时候就该用钱，而不是坐着不动。是那只股票的名字吗，查理？你从他们那儿什么都问不出来。第七站。","kind":0},{"y":2012,"at":0,"ask":"Buffett先生，Munger先生，感谢你们的启发和洞见。看看Berkshire旗下这一批企业，过去五年里哪家企业大大、大大改善了它的竞争地位","ans":"Charlie和我大概比你能找到的任何两位经理人都更常想最坏的情况，而我们永远不会把自己暴露在最坏情况之下。而且，要求为东西提供抵押品意味着你把自己置于一个可能明天早上就得拿出一些现金的位置，而我们永远不会在任何有意义的规模上这么做，因为我们不知道明天早上会带来什么。Charlie？","kind":0},{"y":2012,"at":"01:59:27","ask":"是的。我是John Horton，佛罗里达州杰克逊维尔的Water Street Capital。既然伯克希尔在像 Burlington Northern 这样非常大的收购中很可能需要提供股票成分，那伯克希尔不就会降低现金支出——","ans":"是啊，我们，我们，我们当然更希望我们的股票正好按内在商业价值卖，尽管我们不知道那个精确数字。但查理和我心里有个区间，不过不会太宽。如果它，如果它按内在商业价值卖，我们又能把它作为按内在商业价值买别的东西的对价的一部分，剩下的用现金，你知道，我们会喜欢那种情况。而且那，那在未来很可能会发生。过去也发生过。伯克希尔在不付股息的情况下，过去35年左右的时间里，按内在价值或以上卖出的时间，大概和低于内在价值的时间一样多。我是说，它会上下晃。","kind":0},{"y":2012,"at":0,"ask":"是的。我是约翰·霍顿，来自佛罗里达州杰克逊维尔的Water Street Capital。既然伯克希尔在像Burlington Northern这样的大收购中很可能需要提供股票成分，那伯克希尔难道不会通过……来降低现金支出吗？","ans":"现在，他们，他们的问题在于，正如提问者提到的，发行成本很高。然后第二个问题是，整个国家，我们有1700家报纸，日报，现在大概1400家了。那个，那个，在很多很多情况下，他们上网，免费提供他们原本收费配送的同样的内容。现在，我不知道有哪个商业模式能长期维持下去，也许你能想到一个，也许查理能想到一个，但一边收着高价，一边免费提供同样的东西，那种商业模式长期来看是行不通的。最近，去年，很多报纸已经尝试过，某种程度上实验成功了，在网上免费给的东西开始收费了，而以前他们是想通过配送来收费的。","kind":0},{"y":2012,"at":"02:24:03","ask":"嗨，我是赫克托，来自中国的气枪行业基金管理公司。我的问题是，你提到以零成本甚至负成本获取保险浮存金是伯克希尔哈撒韦的关键竞争优势之一……","ans":"是的，我们当时想，要么内部扩张，那会很难，要么在商业领域收购一家好公司，那更可能是我们的做法。后来我们有机会，我不记得了，六七年前，GE想退出医疗责任险领域，我们就买下了。然后去年我们又收购了Princeton Insurance作为补充。所以六七年前我们确实有机会进入一家一流的公司，有蒂姆·肯尼迪这样一流的经理人，我们马上就抓住了。","kind":3},{"y":2012,"at":0,"ask":"嗨，我是芝加哥的Dan Lewis。我想听听你们对后巴菲特时代伯克希尔的两个担忧的看法。你们会不会担心你们的一些关键运营和投资经理可能为了更赚钱的机会而离开——","ans":"没错，如果你回到一个我们认为能在权益上赚20%之类的世界，那就很少有消耗资本的生意能让大量增量资本以20%的回报率赚钱。那就会不利。但我们不知道拿着我们现在这种规模的资金，未来怎么在权益上赚20%，如果我们能在权益上赚12%之类的，我们就会非常高兴，尤其是当其中一些被消耗的资本是由浮存金产生的，而那不花我们一分钱。我们在那儿有一点小优势。查理？","kind":2},{"y":2012,"at":"03:06:59","ask":"哦，你觉得中国要多久才能出现一家像可口可乐这样伟大的公司，会在哪个行业？","ans":"嗯，这个嘛，BNSF完全是自己在运营的。几年前我们买下它之后，我去过沃斯堡一次，之后就再没去过了。我大概跟Matt通过电话，我也不知道，大概每三个月一次或者差不多这样。但毫无疑问，铁路、公用事业、保险公司都深受政治进程的影响。幸运的是，我觉得在铁路行业，你知道，经济学是站在我们这边的，而经济学通常会……","kind":4},{"y":2012,"at":"04:21:44","ask":"我们还有一个问题。约翰，约翰·博克斯托斯，来自马萨诸塞州达特茅斯，你知道的，就在新贝德福德旁边，伯克希尔以前的老家。我的问题是，你怎么建立进入壁垒，尤其是在行业……","ans":"但是，你知道，没多少年前，你记得理查德·布兰森，他来到这个国家，他，他搞了个叫Virgin Cola的东西。你知道，他们说品牌就是一个承诺。嗯，我不确定他那个品牌想传达什么承诺（笑声）。但是，你知道，从那以后你就再没听说过那玩意儿了。我是说，我不知道历史上有过多少种可乐饮料。唐·基奥可能知道，但肯定有几百种。那些才是真正的壁垒。但是，这，这，这很难做到。我是说，就像辉瑞发现立普妥那样，你知道，他们，时间到了，曾经是绝对的金矿，现在还是个不错的矿，但远不是以前那样了。","kind":4},{"y":2012,"at":"04:43:50","ask":"刚才我，我有点心动。沃伦，今天很多问题都提到风险。在我看来，我们面临的最大风险之一就是纯粹的主权债务水平，不管是在美国还是在欧洲很多国家。","ans":"嗯，主权债务的好处是，他们最后可以不还你，你也抓不到他们任何东西，不像其他种类的债务。而且，你知道，事实是，这个世界见过很多很多次主权债务违约。我记得沃尔特·里斯顿，80年代初那会儿，你知道，说主权国家不会违约。嗯，事实是它们违约过，你知道，历史上很多很多次。然后，然后发生的就是财富的大规模重新分配。现在，财富不会消失。我是说，你不会失去农场，你不会，你失去工厂，你不会失去有技能的人以及所有那一类东西。我是说，可能会有一些边缘的损失，但，但我不知道在欧洲会怎么演。","kind":0},{"y":2013,"at":"00:48:52","ask":"谢谢。我是乔纳森·希夫，从中国澳门来访。您刚才简单提到了这个，但在我们那边，有很多关于美元作为世界储备货币地位的讨论。抱歉，那里","ans":"嗯，这个我不知道答案，但幸好我不，我觉得，它会是相关的。我觉得美元在未来几十年里还会是世界储备货币。我觉得中国和美国会是两个超级经济大国，但我看不到任何，我觉得任何货币在未来几十年里取代美元成为世界储备货币是极不可能的，如果说有可能的话。查理？","kind":2},{"y":2013,"at":0,"ask":"谢谢。我是堪萨斯州欧弗兰帕克的斯科特·摩尔。美联储每月购买850亿美元的抵押证券和国债，您认为这个过程的长期风险是什么，美联储怎么停下来","ans":"我对伯南克很有信心。我是说，他，如果他在冒风险，那是他知道也理解的风险。我不知道他会不会受这个影响——他的任期很快就到了，所以他就把接力棒交给下一个人说，“喏，这张漂亮的资产负债表，你只要把它降下来几万亿就行了，”你知道。我去年在乔治·华盛顿大学做了几场讲座，你要是愿意可以去读读，也许对你有帮助。这个，这是我们没见过的东西，它确实有引发严重通胀的潜力。到目前为止还没有。事实上，我猜美联储还希望它通胀得再多一点。","kind":2},{"y":2013,"at":0,"ask":"谢谢。我是 Scott Moore，来自堪萨斯州 Overland Park。美联储每月购买 850 亿美元的抵押贷款证券和国债，你认为这个过程长期来看有什么风险，美联储又怎么停下来呢？","ans":"我是说，如果你是美联储，每月买 850 亿美元很容易，我不知道他们要是开始试着卖 850 亿美元会怎么样。现在，当你手里有这些准备金的时候，那肯定比这些准备金已经投放到实体经济里要容易得多。那时候你就真的是在收紧政策了。但我，你知道，对我来说，这就像看一部好电影，因为我不知道结局，而这才让电影好看。","kind":2},{"y":2013,"at":"01:58:20","ask":"嗨，我叫 Kelly Morrell，来自纽约，我有个问题。您在公司税和个人税率以及贸易逆差上都直言不讳，我想知道您能不能详细说说，最高的","ans":"嗯，我会说医疗成本会是个大项。我们的支出，我们是个支出——数字说法不一，但就算 17.5% 左右的 GDP 吧，而世界上大多数竞争对手大概在 9.5 到 11.5 左右。所以，你知道，一美元只有 100 美分，如果你在这一美元里让掉六七个、八个点，我是说，这就像你有一种原材料成本比别人高，或者类似的情况。所以那会是美国竞争力上的一个大问题。","kind":1},{"y":2013,"at":"02:18:21","ask":"嗨，嗨，我叫 Dex During，来自弗吉尼亚州 Stafford。我 30 岁，我想知道几年后我的生活会是什么样，更别说 50 年后了。我想问 Buffett 先生和 Munger 先生的问题是，","ans":"嗯，这就像 1990 年代末不买互联网股票一样。我是说，你周围全是这些人，智商很高，他们在做这件事，而且做得很成功。所以，你知道，从你的配偶到你的雇主到媒体，每个人都说，你知道，怎么其他这些人——你怎么就觉得自己那么聪明，避开这个，而别人都在做？他们赚了很多钱。当然这就制造出了一种社会证明，它确实管用了一阵子。","kind":0},{"y":2013,"at":"02:50:49","ask":"嗨，沃伦和查理。我叫黄文森，来自西雅图。人们分析一只股票的时候，很多人会看量化指标，比如市盈率、净资产收益率、资产比率等等。所以，巴菲特先生，您","ans":"不，我不知道怎么。不，比尔还在试着跟我解释。我，我们，你可以，这个很难说得精确，因为我们其实不用筛选器。另一方面，我们又在筛选一切。但不是像我们坐在那儿说，你知道，我们想看那些低市净率的或者低市盈率之类的。","kind":0},{"y":2013,"at":0,"ask":"嗨，Warren和Charlie。我叫Vincent Wong，来自西雅图。人们分析一只股票的时候，很多人会看量化指标，比如市盈率、净资产收益率、资产比率等等。所以，Buffett先生，请问……","ans":"我们认为Burlington Northern在15年后会拥有一种计算机……一种竞争优势，而且我们有很高的信心。我们对Apple永远不会有那种程度的信心，不管他们的财务报表显示什么。不行，就是，太难了。是啊，我们不知道，我们对一家石油公司10年后会怎样也不知道，你知道，不知道产品会卖什么价，什么都不知道。但我想说，我们对Burlington Northern或者GEICO或者一些我不点名的公司，几乎是100%有信心的。","kind":2},{"y":2013,"at":"02:54:06","ask":"嗨，Warren和Charlie。我叫Vincent Wong，来自西雅图。人们分析一只股票的时候，很多人会看量化指标，比如市盈率、净资产收益率、资产比率等等。所以，Buffett先生，请问……","ans":"是啊，Charlie和我根本不看宏观预测。你知道，我们合作到现在54年了，我想不起来有哪次我们做决定——买股票也好，买公司也好——是讨论过宏观的。你知道，我们不知道事情会以什么精确的方式发展，而且我们自然而然就觉得，如果我们不知道，那别人也不知道。这是我们的一点小自负。所以我们就，你知道，为什么要谈，为什么要花时间谈你根本不知道、完全不懂的东西？你知道，我是说，人们整天都在这么干，但没什么成效。所以我们谈的是生意本身。","kind":0},{"y":2013,"at":0,"ask":"……格雷厄姆和费雪写的。我还想告诉您，我觉得如果您能把巴菲特合伙公司那些年的投资组合报表公布出来，那会非常好。我觉得有很多小投资者","ans":"我是说，就像我说过的，如果当年有一个资本主义的基蒂霍克，他应该把奥维尔打下来，那是帮了我们大家一个忙。但是，但是既然没这么做，投资者们往航空公司飞机制造公司里砸钱已经一百多年了，结果糟透了。如果真有那么一天，只剩一家航空公司，而且没有监管，那会是一门好生意。然后问题就是，现在经过一大堆破产之后，剩下相对少数几家在做高比例的客运里程，这到底是不是一门好生意，我不知道答案，但我持怀疑态度。查理？","kind":2},{"y":2013,"at":0,"ask":"……是 Graham 和 Fisher 写的。我还想告诉你，我觉得如果你能公布 Buffett Partnership 那些年的投资组合报表会很好。我觉得有很多小投资者……","ans":"你知道，你首先用钱照顾好你的生意，如果你能买额外的生意，那是能给每股价值加分的事，你就去做。如果你能以明显低于内在价值的价格回购自己的股票，那就像用 90 美分或 80 美分买一美元的钞票，不管具体是多少，这是提高每股价值非常可靠的办法。我们一直很难做到，因为每次我们一宣布，人们就说，如果，如果他认为它值 120% 的账面价值以上……","kind":0},{"y":2013,"at":"03:45:57","ask":"Derek Foster，来自加拿大渥太华。首先，谢谢你，Warren，谢谢你分享所有信息。你改变了我的人生。我在大学学了金融，那些希腊字母公式我根本看不懂，但现在我能比较合理地投资了……","ans":"嗯，有一点，我不知道你说的是 20 家最大的公司，还是 20 家最好的。不同人对哪些是最好的可能有不同看法。但我觉得你大概会，你挑出来的这 20 家，结果几乎会和指数基金一样。谁知道到底哪几家会是最好的呢？","kind":0},{"y":2013,"at":0,"ask":"然后，最后一个附加问题，如果最后可以的话，你能不能解释一下，美联储主席 Ben Bernanke 认为他工具箱里有一个叫定期信贷工具的东西，他到底把它当成什么工具？","ans":"我是说，当时股票很便宜，而且你几乎肯定会先被杀得很惨，你知道，至少在相当一段时间里，我们当时已经承诺，美联储会把利率维持在很低的水平。所以那是一个拥有股票的好时机。我只是，我为那些在这种时期还紧抓着固定美元投资的人感到难过，尤其是短期投资，如果我在那个位置，我不知道我会怎么做。","kind":2},{"y":2013,"at":0,"ask":"然后，最后再问一个小问题，如果最后可以的话，您能不能解释一下，美联储主席 Ben Bernanke 认为他工具箱里有个叫定期信贷便利的工具，他到底觉得那是个什么东西？","ans":"我也没想到我们会看到利率在这么长时间里保持在这么低的水平，我也不知道它还会往下走多久、持续多久。但这对很多人来说真是个两难。我收到信，收到很多人的信，他们说，你知道，“我有 30 万，是我攒下来的，我该怎么办？”所以，低利率带来的后果，是以一种非常残酷的方式冲击了成千上万的人，而你很少读到这方面的报道。他们没什么发声的渠道。","kind":2},{"y":2013,"at":0,"ask":"你好，Buffett先生和Munger先生。我叫Brant Hooker，来自洛杉矶。首先我想感谢你们两位，感谢你们多年来的建议和你们的财务慈善，以及你们的教育和/或知识……","ans":"这就是Charlie和我的优势所在。我们在很多其他方面并没有什么优势，但我们能够——我想，也许比大多数人更强——真正不被别人在做什么所影响。而且，你知道，我不知道，我们是慢慢学到的还是怎样，但当我们看到价格下跌时，你知道，我们觉得那是买入的机会，而且它不困扰我们。当然，我们不借钱买股票，或者说，你知道，我们不会让自己陷入别人能把地毯从我们脚下抽走的境地，这在人生中极其重要。","kind":0},{"y":2014,"at":0,"ask":"是的，你好。我叫Doug Merrill，来自科罗拉多州丹佛，Peyton Manning的老家。太棒了。总统的支持率是40%。Steve Wynn说奥巴马是经济最大的扫兴鬼。其他一些……","ans":"所以我们谈过这个。我们说过我们愿意买——不只是愿意，是渴望买——以账面价值的120%买股票。账面价值现在接近2300亿美元，那显然意味着我们认为在大约450亿美元超出那个数字之上，相对于内在价值我们是在捡便宜。但我们永远不会试图给出一个精确数字，因为我们不知道精确数字，而且它……它每天都在变，虽然每天变得不多，但肯定在变，你知道，按季度、按年份在变。第二个原因是，如果你让Charlie和我坐在这儿写下Berkshire的内在价值，我们俩的数字大概会在5%以内，但很可能……我们大概不会在1%以内。","kind":1},{"y":2014,"at":0,"ask":"早上好，沃伦和查理。我叫杰森，来自多伦多，我的问题跟整体金融市场有关。我们已经处在几乎零利率的环境里很多年了。最近","ans":"但就像我去年说的，这真是一部有趣的电影，因为我们以前没看过，而它有趣的地方也在于我们不知道结局。但我觉得本·伯南克是个英雄，无论是在崩盘、恐慌那会儿，还是之后。他是个非常聪明的人。我觉得他处理得很好。让我觉得有意思的是，当美联储2007、2008年那段的会议纪要公布出来时，我很有意思地发现，美联储好些成员当时根本没搞明白发生了什么。那真是，那真是很有意思。","kind":4},{"y":2014,"at":0,"ask":"早上好，沃伦和查理。我叫Jason，来自多伦多，我的问题跟整体金融市场有关。我们已经处在几乎零利率的环境里很多年了。最近","ans":"Pete把公司经营得非常出色。他来的时候我们达成了一个协议，激励薪酬和基本薪酬。他从来没提过要改，我也从来没提过要改。他把公司做到了今年会超过，我觉得他今年会做超过40亿美元的生意。整个这段时间我大概跟他通过三四次电话。那是他的公司，他做得非常棒。我不知道Thor、Forest River的情况，不知道去跟他们竞争有多难，但我觉得在任何情况下跟Pete竞争都会很难。他，一个40亿美元生意的IT部门只有六个人。他就是知道那地方在发生什么。","kind":3},{"y":2014,"at":0,"ask":"嗨，巴菲特先生和芒格先生。我叫Dev Kantesaria，是来自费城的一位基金经理。你们今天已经谈到了其中一些，但我想问一下，你们能不能展开讲讲你们怎么看待比较","ans":"那么，说到自动驾驶汽车，那对汽车保险行业是个真正的威胁。我是说，如果那真的成功了，大幅减少事故，对社会非常好，但对汽车保险公司非常糟糕。所以，你知道，那是可能发生的。我不知道怎么去评估那需要多长时间，或者多大比例的汽车会受影响，但它确实可能发生。而我们，那不会让我们有一秒钟去想卖掉GEICO。查理？","kind":2},{"y":2014,"at":0,"ask":"您好，Buffett 先生，您好，Munger 先生。感谢您非常慷慨地分享什么是信心","ans":"你可以说，我买 Berkshire Hathaway 的时候就在我的信心圈之外。我，虽然我最初买它其实是想当股票转手卖掉的，但我决定应该进去买下公司控股权的时候，大概也是出了我的信心圈。那是个愚蠢的决定，只不过结果还不错。至于评估你自己的才能和短板，我想，我不知道那是不是天生的，但有些人似乎比其他人强得多。我确实知道有不少 CEO，我觉得他们根本不知道自己的能力圈从哪儿开始、到哪儿结束。但我们有不少经理，我觉得在这方面就特别棒。我是说，他们真的知道什么时候是在自己会赢的游戏里玩，而且他们不会跑出那个游戏。","kind":4},{"y":2014,"at":"03:23:50","ask":"Bunk先生请听。是的，巴菲特先生，芒格先生，我叫Nicholas Erdenberger。我来自美丽的新泽西花园州。我想问题是，（掌声）我想这是对那个问题的追问","ans":"我叫了人来，我不知道是八个还是十个。我周五下午刚到那儿，现在已经是周六早上了，而我们周日晚上就得在东京开业，我得有人来管这个地方。所以我叫了八个人来，我说：“你知道，除了你之外，谁会是管这个的理想人选，为什么？”有一个人告诉我，没人能跟他比。（笑声）几个月内他就离开了公司。但那个，用这个办法不算差。","kind":4},{"y":2014,"at":"04:09:42","ask":"我是来自威斯康星州尼纳的拉塞尔·梅里特。不是又一个包装工队球迷。今晚在这个大厅里的人，都是因为把钱投给了你们，期待并希望你和查理能让这笔投资增值。","ans":"是啊，嗯，我们两边都沾着，因为阿吉特给铁路行业开出了很高的限额，给所有主要铁路公司都报了价，但他们显然不喜欢他的价格。我得说，四大铁路公司确实有财力支付巨额赔偿，如果真的出了什么非常可怕的事。最——你知道，我不知道哪个最危险，他们，他们有所谓的hazmat，危险品，铁路必须运这些。你是公共承运人，你被迫运。铁路公司其实宁愿不运，但他们得运，必须运，而且他们可能永远拿不到足够的、每车厢的运费来真正补偿所承担的风险。","kind":3},{"y":2014,"at":0,"ask":"我是Russell Merritt，来自威斯康星州Neenah。不是又一个Packers球迷。今晚在这个大厅里的人，来这里是因为把你们的钱投了进去，期待并希望你和Charlie能让这笔投资增长。","ans":"但从财务角度来说，这不是让我晚上睡不着觉的那个。大的、总体的、最大的风险是某种非常有效的恐怖主义，或者某个流氓国家在核、化学、生物或网络方面的行动。你知道，战争行为不在保险范围内，但你可能遇到某种恐怖行为造成损害——他们在保险合同下是否承担责任是另一回事——但可能造成我们从未见过的损害。而且，你知道，未来50年里某个时候发生这种事，显然有合理的概率。概率是多少我不知道，但它不是——它不是微不足道的。Charlie？","kind":2},{"y":2014,"at":"04:18:35","ask":"我叫Ed Boyle，来自芝加哥。我问沃伦和查理的问题：你们有没有过任何计划，或者会不会有兴趣买一支职业体育队或者体育用品制造公司，因为","ans":"我拥有过一支小联盟球队四分之一的股份，但那跟我在福布斯400上的位置没关系。你关于买体育队的问题，答案是不买。实际上，如果查理和我，如果你读到我们俩任何一个在买体育队，那可能是该谈谈接班人的时候了。我们，我们，我们确实，体育用品总体上一直不是个很好的生意。你知道，显然Nike在整体运营上做得非常出色，但我们拥有Spalding，我们拥有Russell，而且，你知道，Spalding已经存在很长很长时间了。A.G. Spalding，不管他是什么时候的人，我觉得他当年是想把棒球推广到世界其他地方，在，我不知道，1880年代还是什么时候。","kind":0},{"y":2014,"at":0,"ask":"下午好。我叫Michael Sondag，来自华盛顿特区。我的问题是关于共享经济的。您觉得像Uber和Airbnb这样的公司会对它们所在的行业产生什么更大的影响？还有您认为","ans":"你提到的那些公司，我一点都不了解。我是说，我知道它们是干什么的，但我不知道它们具体的前景，所以我们基本上不碰这类东西。因为我们不知道——我们知道会有变化，但不知道谁会赢。我们尽量待在那些我们知道赢家是谁的生意里，我们知道，我们知道。我们的能源公司、铁路，我们很多业务都非常非常非常可能是赢家。这不意味着它们身上没有变化，但它们会是赢家。然后还有一些领域我们挑不出赢家，那我们就坐着看。我们觉得它们有意思，但不会被诱惑。Charlie？","kind":0},{"y":2014,"at":"05:02:36","ask":"下午好。我叫Diane Wieland，来自佛罗里达州好莱坞。我在公立教育领域工作了35年以上。我的担忧是，我觉得我们需要做更多来主动培养我们的孩子，还有你……","ans":"嗯，当然，当然越早越好。我是说，习惯在每个人的生活里是那么强大的力量，好的理财习惯当然也是。你知道，我，我经常看到这个。我每天都收到信，来自那些犯了某种财务上的荒唐错误的人，但他们不知道那是荒唐的。他们从来没——你知道，他们没被教过，他们父母没教过他们。而从财务无知造成的坑里爬出来，你知道，得花掉你余生。所以我，我非常理解你说的。我们做了一点点，我不知道——你看到展览厅里我们的Secret Millionaires Club展台了吧。你知道，你得在很小的年纪就跟人聊这些。","kind":0},{"y":2015,"at":0,"ask":"行。我叫斯图尔特·凯，来自康涅狄格州斯坦福德，我想接着刚才关于伯克希尔文化和管家精神的问题问，因为我目前是第","ans":"但我们不谈，根本不会提，因为我们不，我们知道我们不知道未来12个月、24个月、30个月，我们知道我们不知道那会是什么样。但这其实没什么区别。如果我们买一个企业是打算持有100年，我们要做的就是弄清楚这个企业长期的平均盈利能力大概是多少，它的竞争护城河有多强，诸如此类。所以人们很难相信这一点。他们以为我们会谈这些。我们觉得任何公司要是养了个经济学家，你知道，那肯定是多养了一个员工。","kind":0},{"y":2015,"at":"01:14:41","ask":"你好，芒格先生和巴菲特先生。我是来自马萨诸塞州黑弗里尔的尼拉夫·帕特尔。如果有人想和有影响力的人建立人脉，但又没有顶尖商学院的校友网络，你会给他什么建议？","ans":"是啊，其实我想说，商学院的训练，尤其是在投资方面，在大概20年前是一种障碍，因为他们那时在宣扬有效市场理论，因为基本上他们告诉你，去搞清楚一家公司值多少钱是没用的，因为市场已经完美地定好价了。你想想，花上，你知道，每年3万或4万美元来听这个。","kind":0},{"y":2015,"at":"01:35:15","ask":"你好，我是莱昂·萨加洛夫斯基。我来自伊利诺伊州芝加哥和加州伯克利。感谢你给我机会问这个问题。这是我第一次参会。我倾向于每50年来一次。还有一个","ans":"是啊。嗯，我们在年报里多次谈过Dexter，我，早在1990年代中期，我看了缅因州Dexter的一家制鞋企业，决定花大约4亿美元买一个注定几年内归零的东西。而我没看出来。然后更糟的是，我用股票支付的收购价，我猜那些股票现在值，我不知道，也许60亿或70亿美元。股票跌的时候我反而感觉好点，因为愚蠢被削减了。不，那事没人以任何方式误导我。我就是看了看，得出了错误答案。但我要说，几乎每次我们发行股票，都是个错误。你不这么认为吗，查理？","kind":4},{"y":2015,"at":"02:05:54","ask":"是啊，我可以，我可以再问您一个问题。我能请您吃午饭吗？（笑声）","ans":"不，我觉得，有些公司他们会做出改变，但我要说，比如GEICO，三万三千名员工还是多少来着，运行效率和3G来管一样高。我要说我们总部25个人，我们完全可以搞一个500人的总部。我们可以有整层楼做战略，整层楼做人力资源，比较我们各家公司的每个人的薪水等等。他们要是走进那种情况，他们会砍掉。我不知道他们能不能砍到我们这25个人。但我们不相信养闲人。我们的报纸，你知道，很不幸，收入一直在缩水，他们不得不裁员。那种因为赚了很多钱就养一个臃肿机构的想法是……","kind":0},{"y":2015,"at":"03:51:59","ask":"先生们，感谢你们带来美好的一天。我叫马克·格罗，是奥马哈这里以马内利愿景基金会的执行董事。今天早些时候我坐在角落里，和我儿子聊了聊，他正在工作，住在……","ans":"现在，也不算多新颖。所以，回到我们的主要观点，我认为，我认为欧元能够而且大概应该存续下去，我认为这需要一些真正的改变，也许还需要一些范例才能让它做到这一点。我希望它真的，我是说，它会朝着更多凝聚或更少凝聚的方向走，而且可能很快。我认为如果我们能想出办法，在整体上实现更多凝聚，那对欧洲会是好事。但它肯定，你知道，它现在的形式，是行不通的。查理，我不知道为什么我又给你一次机会。","kind":2},{"y":2015,"at":0,"ask":"巴菲特先生，在现在这种量化宽松、低利率、股市估值过高的环境下，您觉得以现在这个价格，白银有什么价值？您还关注白银市场吗？","ans":"但人们脑子里决定要不要回购股票的时候，掺杂了太多别的动机，很多情况下这讨论真是又扭曲又有点可笑。查理说得对，你看回购的历史，股价便宜的时候回购就猛跌，股价涨到位了回购反而大幅上升。但我们在Berkshire不这么干。在Berkshire，你知道，我们现在，我们很想以120%的账面价值大把大把地买，因为我们知道它值远不止这个数。我们不知道到底值多少，但我们知道它值多得多。这种机会不常有，但一旦有了，我们就大干一场。但我们不会在200%账面价值的时候买，因为不值，你知道。","kind":0},{"y":2015,"at":"04:11:27","ask":"我说的是他们，但只是个例子。我也在说也许减少深度或者做别的。","ans":"是啊，好吧，我们当然希望的是，我们所谓的多余现金，也就是超过200亿的现金，能拿去收购一家企业。但你没法，你知道，一周一个或者一个月一个。所以这是机会主义的，我不知道下一个交易的那个电话是下周来还是一年后才来。我们会接到电话，我们会把钱投出去。我们，你知道，我们就是没法均匀地投。而且我们，你知道，几乎没有债务。","kind":2},{"y":2015,"at":"04:15:26","ask":"嗨，巴菲特先生和芒格先生。我叫George。我在为我父亲Leing Gal翻译，他来自中国上海。去年是我父亲站在这里提问，今年是我。我觉得太幸运了。我知道","ans":"是啊，我不了解中国经销商的情况。我想说，我前面稍微提到过，我不认为我们在汽车领域买更多门店就能获得显著的规模优势。我就是看不出这优势从哪来。但我们也不需要。我们真正需要的是那些单个经销商的经理，他们自己真金白银投在里面，把店当成一流企业独立来经营。这才是我们要找的。我们不会去找规模。我不了解中国的情况。也许查理知道得更多。我觉得他知道。","kind":0},{"y":2016,"at":"00:25:46","ask":"嗨，早上好。我叫Gaspar。我是西班牙人，从伦敦来。我在很多方面都钦佩你们两位，但我想知道，回头看的话，你们在人生中会有什么不同的做法","ans":"嗯，我85岁了，我想象不出有谁比我更快乐。所以我，不管是偶然还是怎样，我还是，我是说，你知道，我是说，我坐在这里吃 exactly 我想吃的东西，在生活中做 exactly 我热爱做的事，和我爱的人在一起。所以真的没有比这更好的了。而且我……（掌声）","kind":4},{"y":2016,"at":0,"ask":"早上好，巴菲特先生和芒格先生。我叫亚当·伯格曼。我在弗吉尼亚州弗吉尼亚海滩的Sterling Capital工作。在你们2008年的股东信里，你们说，‘衍生品是危险的。它们几乎让……’","ans":"衍生品在大量存在时仍然是危险的。而且我们，我们不会在有抵押的基础上做它们，因为如果出现不连续性，我不确定我们最终会落到什么地步。我永远不会让我们陷入这样一种境地：有人向我们索要资金，而我们无法轻松满足，无法让我睡得安稳。所以我们不会参与。我们有一些在清算中，但到目前为止我们赚了钱，并且十多年或更久以来一直在使用这笔钱，对我们来说非常有吸引力。但这完全不会诱使我去做任何涉及抵押品的衍生品交易。而抵押品并不是必需的。它仍然是系统里的一个潜在定时炸弹。任何存在不连续性的东西，基本上这意味着关闭、停止交易市场运作，任何可能存在不连续性的东西都可能是真正的毒药。","kind":0},{"y":2016,"at":"01:35:51","ask":"查理是我们的校长斯内普，直接又充满正气。长期集中价值投资的魔力是真实的，但就像哈利·波特一样，世界上其他人不相信我们存在。你给我的信……","ans":"是啊，我们赚了钱，但我们本可以赚得多得多。但是，我们不会，我们不认为我们能预测大宗商品，有两个家伙认为我们能预测大豆或玉米或石油或任何其他东西的价格。所以你在我们的投资交易中看到的任何东西，你提到的那些证券有些是Todd或Ted买的，有一个是我买的，但他们和我都不是基于大宗商品价格预测来买那些的，或者如果我们卖掉它们，也是基于……我们不知道怎么做。但是，而且我们在做那些决定时想的是别的事情。查理？","kind":0},{"y":2016,"at":0,"ask":"","ans":"想象一下在一个利率几乎为零的世界里，你知道，美国企业在有形净资产上赚取惊人的回报。我是说，那些是真正投入企业运营的资产。数字令人震惊。你知道，那些把钱放在储蓄账户之类的人，那被摧毁了。但企业的所有者，如果你看有形净资产的回报率，什么时候去查一下，他们并没有受损，而持有固定利息、固定收益工具的人则遭受了巨大损失。","kind":0},{"y":2016,"at":0,"ask":"早上好，沃伦和查理。我是来自菲律宾的Vanda Merced。沃伦，我和我妻子两天前给您的办公室寄了原创画作。希望你们喜欢。谢谢。今天，抱歉。今天，Berkshire的规模","ans":"John Harding以前为我工作，后来成了这里的员工，还有我们一些前合伙人，我以前的合伙人，加入了Sequoia Fund，就是想找一个出色的投资经理，就像我说的，既有能力又有正直品格，能把小笔资金交给他打理。Bill经营Sequoia一直到，我想大概是2005年，他去世那年，做得非常出色。即使现在，如果你看从成立到现在的记录，加上我最近遇到的麻烦，我不知道美国有哪只共同基金有更好的记录。也许有吧，可能有一两只。","kind":4},{"y":2016,"at":0,"ask":"早上好，沃伦和查理。我是来自菲律宾的万达·默塞德。沃伦，我和我妻子两天前把原画寄到了你的办公室。希望你们喜欢。谢谢。今天，抱歉。今天，伯克希尔的规模……","ans":"现在这听起来对对冲基金来说可能是个糟糕的结果，但对对冲基金经理来说并不是糟糕的结果。这些经理，第一，你有一个顶层经理大概收0.5%，我不确定，然后下面你还有经理大概收1.5%到2%。所以如果你每年被切掉几个百分点，那是一大笔钱。我们在伯克希尔有两位经理，每人替我们管理90亿美元。他们之前都经营过对冲基金。如果他们和伯克希尔有2和20的安排，这在对冲基金界并不少见，他们每人每年就能拿到1.8亿美元，你知道，仅仅因为呼吸。那，我是说，那是一种在我看来难以置信的薪酬方案。这也是我打这个赌的原因之一。","kind":1},{"y":2016,"at":0,"ask":"嗨，我叫Matt Claiborne，来自俄亥俄州哥伦布市，感谢你们为我们所有人举办这个活动。我的问题是，你们之前说过你们的角色在继任中会被分成几部分，其中一部分将是，","ans":"但我们，我们对那些想进董事会是因为想每年赚个二三十万美元的人不感兴趣，你知道，花他们10%的时间。我们对那些把这当作声望象征、想去勾勾选项之类的人也不感兴趣。所以我觉得我们，我们有，我们会继续用这个标准：商业头脑、股东导向、对Berkshire有强烈的个人利益。我们股东持有的每一股Berkshire，他们买的方式和这个房间里的每个人一样。","kind":0},{"y":2016,"at":0,"ask":"嗨，我叫Matt Claiborne，来自俄亥俄州哥伦布市，谢谢你们为我们所有人举办这个。我的问题是，你之前说过你的角色在继任时会分成几部分，其中一部分会是，","ans":"部分的，是什么让，部分让我，嗯，我的工作特别轻松，但我周围的人真的让它变轻松了。它轻松的部分原因是我们不，我，我们没有任何委员会。也许有些委员会我不知道，但我从没被邀请参加过任何委员会，我就这么说吧，在Berkshire。我们不，我们也许哪儿有个PowerPoint，我没见过，反正我也不会用。我们就是不做，我们没有那种为了忙而忙的活动。我们可能会一起去看场棒球赛什么的，但那个，我见过另一种运作方式，我更喜欢我们这种，我就这么说吧。查理？","kind":4},{"y":2016,"at":"03:06:18","ask":"你好。你好，Buffett先生和Munger先生。非常感谢你们的洞见、教导，还有做了不起的榜样。我叫Eric Silberger，是纽约市的小提琴手。给你们两位的问题跟……有关","ans":"嗯，查理和我当然，我们读很多东西，所以我们，我们对经济事务和政治事务都感兴趣，所以我们知道很多，或者说我们很熟悉很多，我应该说，几乎所有的宏观经济因素。这不意味着我们知道它们会走向哪里。我们不知道零利率会走向哪里，但我们确实知道正在发生什么。如果我们不知道什么，什么可能……","kind":0},{"y":2016,"at":0,"ask":"是啊，锚定效应，我是说，你怎么应对那个呢？","ans":"大事，目标，查理和我想的是，我们想每年都给公司的正常化每股盈利能力，你知道，正常化的，增加点什么。我们认为我们能做成，因为我们应该能做成。我们每年都有留存收益可以用来完成那件事。有时候看起来我们没做成多少，我们也确实没做成多少。其他年份，我们，发生了大事，而我们事先不知道哪一年会是哪一种。查理？","kind":0},{"y":2017,"at":0,"ask":"您好，巴菲特先生，芒格先生。您经历了成千上万次谈判和商业交易，能不能跟大家说说，哪一次在您印象中最突出，是您最喜欢的，或者特别值得一提的？","ans":"这显然是个包含各种技术的产品，但就预测他们的潜在客户未来会怎么做而言，跟比如说IBM的客户相比，是另一种分析。这不代表它是对的，时间会告诉我们。但这是两类不同的决策。第一个我错了，第二个对不对我们以后会知道。但我不……我不认为它们是一回事，我也不完全认为它们是完全不同的两回事，但有点介于两者之间。Charlie？","kind":2},{"y":2017,"at":"01:50:53","ask":"我是Marcus Burns，来自澳大利亚悉尼。我的问题是，巴菲特先生，我以前买的是轻资本、能产生现金的企业，但现在变成了买低增长、消耗资本的企业。我意识到Berkshire产生","ans":"嗯，我们当然很想找到那样的。我是说，毫无疑问，买一个高资产回报率、非常轻资本、还能增长的企业，比买一个需要大量资本才能增长的东西强太多了。这每天都在变，但我相信——而且我觉得这一点没有被充分认识到——我相信美国市值最大的五家公司，有时候我们在里面有时候不在，假设我们不在吧，某一天它们市值加起来超过2.5万亿美元。这2.5万亿是个大数字。我不知道美国市场的总市值是多少，但这大概已经接近整个美国市值的10%了。","kind":0},{"y":2017,"at":0,"ask":"还有来自Shankar，我来自伊利诺伊州Gurnee。谢谢你们为我们做的一切。我有个问题。你们两位很大程度上通过互相碰想法来避免资本配置的错误。那","ans":"当然了，我们在Berkshire有个优势，就是我们确实知道这有多重要，而且我们确实专注在这上面。在很多公司里，人们是靠能力和销售爬到顶层的。有时候来自法律方面，或者其他方面，各种不同的背景，然后他们手里就有了资本配置的权。他们可能没设战略思考部门什么的，他们可能听投资银行家的话什么的，但他们最好自己能做这件事。如果他们来自不同的背景或者没做过，那就有点像——我在一封信里写过——就像你苦练小提琴终于登上了卡内基音乐厅的舞台，然后人家递给你一架钢琴。我是说，如果放一个在其他领域很有本事但真的没有资本配置能力的人上去，Berkshire不会干得好。","kind":0},{"y":2017,"at":0,"ask":"你好，Warren。这个问题来自中国。我是 James Chen，来自上海的中国养老基金经理。我的问题很简单：在中国复制您伟大投资记录的概率有多大","ans":"所以我不知道我能不能明确地回答这个问题，但我可以告诉你，他们不仅拍照，专注于生产力并且以非常聪明的方式去做，而且他们还极其注重产品改进、创新，以及所有其他你希望管理层关注的事情。我希望在午餐的时候，如果你吃了 Kraft Heinz 的芝士蛋糕，你会同意我的看法，那里的产品改进和创新，和生产力一样，都是 3G 打法的一部分。","kind":0},{"y":2017,"at":"04:00:22","ask":"尽管如此，您最近一直在投资、关注和谈论更多科技公司。我的问题是，也请 Charlie 评论，是什么让您从奥马哈先知变成了科技专家？","ans":"好，我们继续。但这会是，你知道，看看我们会发生什么，这绝对是个引人入胜的话题，但它变得非常非常难以预测。如果在某种程度上，你知道，我们在 GEICO 雇了 36,000 人，你知道，如果某个……如果你能做同样的事……执行所有同样的职能，几乎所有的同样的职能，用五千或一万人来做，而且来得很快，同样的事情在很多其他领域也在发生，你知道，我不认为我们曾经经历过类似的事情，也许我们将来也不会经历。我对 AI 了解不多，但……","kind":2},{"y":2017,"at":0,"ask":"谢谢，下午好。我是 Adam Bergman，来自弗吉尼亚州 Virginia Beach 的 Sterling Capital。今天早些时候，Munger 先生谈到了中国市场与美国市场的估值对比。我想问您的是，我们的市场","ans":"我不知道什么……我不知道 Charlie 对这个有没有看法，但肯定的是……那是我们学习经历中很大的一部分，而且我觉得更大的部分是，从某种意义上说，比起经营、参与好生意，实际上是参与了一些烂生意，然后看到它有多糟糕，你对此几乎无能为力，智商也解决不了问题，还有一大堆事情。我……这是有用的经历，但我不建议经历太多。你觉得呢？Charles 在这儿。","kind":4},{"y":2017,"at":0,"ask":"下午好。我叫Sally Burns。我来自澳大利亚，但目前住在德克萨斯州奥斯汀。我的问题是：巴菲特先生，我听说芒格先生说您最大的天赋是您是一台学习机器，那","ans":"而且他们……每个人都喜欢谈论自己的竞争对手。如果你对10家不同的公司都这么做，你大概会比那些人之中的任何一个都更了解煤炭行业的经济状况。我是说，有办法去搞清楚事情，有时候有用，有时候没用，但有时候非常有用。而且，你知道，就是不断学习更多的这种想法……我比Charlie专注得多，远远比他专注。我是说，他什么都想学，而我只想学跟Berkshire有关的东西。但这是个非常，你知道，这是对待世界的一种非常有用的态度。当然了，我不知道是谁说的，但有人说过，问题不在于接受新想法，而在于摆脱旧想法，这话很有道理。","kind":0},{"y":2018,"at":"00:41:50","ask":"你好，我是来自中国无锡的小肖，资本看到了。我在商场团队12年了。祝你和查理身体健康，这样我们还能看你们主持12年的会议。谢谢。一个简短的问题。我们知","ans":"是啊，顺便说一句，我在年报里写的那部分，我说大致上，没人知道这个答案。我是说，我也可以写下一个数字，别的更聪明的人、保险业的人会写下不同的数字。但我觉得大约有2%的风险，会发生我所说的4000亿级别的史上最大超级灾难。而网络风险就在这个等式里。我是说，不只是地震之类的。坦白说，我不认为我们或任何其他人真正知道他们在写网络保险时在做什么。我是说，我们，这在这个游戏里还非常非常非常早期，我们不知道保单的解释会是什么。我们不知道相关事件会到什么程度，我们现在并不真的认为它们是相关的，或者还没想到那一步。","kind":2},{"y":2018,"at":0,"ask":"你好，我是来自中国无锡的小肖，资本看到了。我在商场团队12年了。祝你和查理身体健康，这样我们还能看你们主持12年的会议。谢谢。一个简短的问题。我们知","ans":"但这是一个我们并不……我们对加州地震的概率、或者三四级飓风袭击佛罗里达的概率之类的，有相当好的判断。但在网络风险上，我们不知道自己在做什么。我们尽量保持，我们不想在这方面当先驱。我们在Berkshire Hathaway确实在这个领域做了一些业务，尤其是。","kind":0},{"y":2018,"at":0,"ask":"Wally Obermeyer，Obermeyer Wood Investment Council，科罗拉多州 Aspen。Warren 和 Charlie，你们两位在私营部门资本配置方面展现了巨大的天赋，向世界展示了这个领域卓越的力量","ans":"你不可能有 377,000 名员工，还指望每个人都像 Ben Franklin 那样行事。而且他们，我们，我不知道就在我们说话的当下，是有 10 件事做错了，还是 20 件，还是 50 件。重要的是，如果能避免，我们不想激励任何这类事情，如果我们发现了，当我们发现它在发生时，我们必须采取行动。这绝对是关键。而 Wells Fargo 没有这么做。","kind":0},{"y":2018,"at":0,"ask":"Wally Obermeyer，Obermeyer Wood Investment Council，科罗拉多州阿斯彭。Warren和Charlie，你们两位在私营部门资本配置上展现了非凡的才能，向世界展示了这个领域追求卓越的力量","ans":"你尽量把它最小化。Charlie说，一盎司的预防不只值一磅的治疗，它值大约一吨的治疗。我们应该扑向每一件事。他这一辈子都在推着我去确保我把令人不快的问题在表面就解决掉，而在其他一切顺利的时候，这有时候不容易做到。在Wells，他们显然，我不知道具体是什么，但他们，他们做了每个机构的人都会做的事，只是被放大到了极端。但我看不出有什么理由认为Wells Fargo往后不是一家非常非常大、经营很好的银行，只是历史上有一段它希望没有过的插曲。但GEICO后来更强了，American Express后来更强了。问题是你发现问题的时候怎么做。Charlie？","kind":0},{"y":2018,"at":"01:55:06","ask":"嗨，早上好，Buffett先生和Monger女士。我叫Stephanie Yu，来自Horizon Insights，一家总部在上海、专注中国的研究公司。我在中国有很多共同基金客户，他们非常年轻，相对","ans":"我觉得那会是很久以后的事。不，答案是我不知道，50年前我也不知道现在会是什么样。我是说，它会建立在某些原则之上，但那会引向哪里，我承认，我们到时候就知道了。会有跟我关注不同东西的人，会有一个不一样的世界。但我们会，我非常希望也相信，我们会，我们会像世界上任何大公司一样以股东为导向。我们会把股东看作合伙人，我们会用我们的钱去做我们对自己钱会做的事，不是想从他们身上占便宜。还有谁，谁知道那时候还会发生什么。Charlie？","kind":2},{"y":2018,"at":"02:01:11","ask":"早上好。嗯，我有个关于债券市场的问题，美国国债市场。我叫Ola Larsen。我住在旧金山湾区，我从没在金融行业工作过。我一开始是买","ans":"是啊，答案是我不知道，好消息是别人也不知道，包括美联储的人，哪儿的人都不知道。这里面变量太多了。我们知道的一件事是，我们觉得长期债券是很糟糕的投资，按现在的利率，或者接近现在利率的任何水平。所以我们基本上所有等着投出去的钱，都放在短期国债里，平均到期期限大概四个月，顶多这样。这些的利率最近上去了，所以2018年，我猜我们至少能比去年这些短期国债多出5亿美元的税前收入。但它们还是，不是因为我们想拿着。我们是在等着做别的事。","kind":2},{"y":2018,"at":0,"ask":"Warren，你和Charlie过去一直批评商学院，批评他们教的价值投资那套。在《格雷厄姆-多德村的超级投资者》里，你展示了 many great investors 的回报","ans":"这，这不是，我们做的不是什么复杂的生意。它得是有纪律的生意，但它不需要超高的智商或者那一类的东西。有几个基本面特别重要，你确实得懂会计，而且出去跟消费者聊聊、在很多方面开始像消费者那样想，在某些行业里，这些都很有帮助。但它就是不需要高深的学问。我，我，我当然，你知道，我本来就不想去上大学，所以我，我也不知道我要是高中毕业就停了，只读我读过的那些书什么的，会做得更好还是更差。","kind":0},{"y":2019,"at":0,"ask":"早上好。我叫Bill Moyer，来自华盛顿州的Vashon Island，我是一个叫Solutionary Rail Project的团队成员。有意思的是，美国货运价值中只有3.5%是通过火车运输的。Berkshir","ans":"Wells这几年成了，你知道，头号案例，但往前推几年，你知道，几乎可以往下数，有一长串银行，人们在那里行为不端，他们，我不会说，我不知道Wells的具体情况。但我在年报里其实写过，他们谈道德风险，如果他们允许人们，Wells的股东付出了代价，Citicorp的股东付出了代价，Goldman Sachs的股东、Bank of America的股东，他们付了数十亿数十亿美元，而他们并没有做那些事。当然也没人坐牢，没有入狱判决，这让人愤怒。但学到的教训不是政府救助，因为政府，政府把钱收回来了，而是各家银行的股东付了许许多多十亿美元。","kind":0},{"y":2019,"at":0,"ask":"是的。首先，我是这所伟大学校的自豪的毕业生，我得亲自感谢你们这些年来来分享你们的见解，自从我1999年毕业以来，来参加这个……已经成了一个传统。","ans":"你看，我们在几个受监管的行业里经营，我们的铁路和我们的公用事业，实际上，它们必须在华盛顿有存在，或者在它们经营的州议会里有存在。所以它们有，我们有，我们有几个，我不知道有多少个，政治行动委员会，这些在我们收购的时候就存在了。我们收购这些公司作为子公司。我觉得，毫无疑问它们会做一些捐款，就是为了获得跟竞争对手一样的渠道。我，如果卡车行业要游说，我肯定铁路行业也要游说。但总的，嗯，规则是，我是说，人们不能用你的钱去追求他们自己的政治利益。这些年来我们有过一两个经理，比如说，会搞一些筹款，向他们的供应商或者类似的人筹款，我一旦发现，马上就停掉。","kind":0},{"y":2019,"at":"01:02:13","ask":"你好，Charlie和Warren Buffett，我的偶像。我是来自上海证券交易所的Terry，想抓住下一个时代最好的投资机会。我的问题是，我们都知道，5G要来了。据说大部分的","ans":"嗯，Berkshire最上面没有什么核心的补充，但是，我们，那些会参与5G相关开发的子公司，或者这个世界上将要发生的各种各样的事情，你知道，铁路里LNG的效用，或者所有这类问题，我们在那些业务里的人比我们懂的多得多。就是，你知道，我们指望我们的经理去预判他们业务里将要发生什么，有时候他们跟我们谈。但我们不是从中央、集中式地管这些。Charlie，你想补充点什么吗？你对5G了解吗？我不了解。你可能对5G了解很多。","kind":0},{"y":2019,"at":0,"ask":"Warren和Charlie，我叫Brent Muio，来自加拿大温尼伯。首先，感谢你们投入这么多时间和精力在教育上。因为你们的努力，我成了更好的投资者，但更重要的是，我成了更好的","ans":"我们有一个非常好的保险业务。花了很长时间才发展起来，很长时间。事实上，我觉得我们可能拥有世界上我所知道的、任何规模下最好的财产意外险业务，综合来看。所以它值很多钱。它大概……我们认为它对我们更值钱，我们尤其认为它放在Berkshire里面更值钱。我们会给它一个非常非常高的估值。我不想给你一个确切的数字，因为我不知道确切的数字，而且，我过去给你的任何数字，结果都会证明是偏低的，我们做到了用别人白给我们的钱赚钱，还有承保的额外收益，然后还有这些巨大的投资收益。它是Berkshire不可分割的一部分。","kind":3},{"y":2019,"at":"03:38:22","ask":"Buffett先生和Munger先生，感谢你们回答我的问题。我叫Feroz Qayyum，来自加拿大密西沙加，现在住在纽约。我的问题是如何最好地效仿你们建立圈子的成功","ans":"是啊，是啊，我们不会改变。我们确实喜欢拥有大量资金，能够非常快速、非常大规模地运作。我们不，也许我们不会，我们知道我们不会经常得到那些机会，我不这么认为。当然，你知道，在未来，你知道，在未来二三十年里，会有两三次天上下金子的时候，你所要做的就是走出去。但我们不知道它们什么时候会发生，而我们有很多钱可以投入。我想说，如果你告诉我，我必须么持有短期国债，要么持有指数基金，就让那笔钱一般性地投资在美国，我会选指数基金。但我们仍然抱有希望。","kind":2},{"y":2019,"at":0,"ask":"嗨。嗨Warren，嗨Charlie。我叫Carrie，这是我女儿Chloe。她11周大。这是她第一次参加Berkshire股东大会。我们来自旧金山，我们有一个关于就业的问题想问你们。作为既是主要的","ans":"我不认为，我不认为你需要担心美国的创造力会用完。我是说，我是说，你看看各种行业里的人，他们喜欢赚钱，但他们真的喜欢，他们喜欢有创造力，你知道，他们喜欢，他们喜欢做事。而这个经济，它运转着，它会继续运转，而且会非常，某些行业非常艰难，会有错位。汽车出现的时候，我们不会再去造那么多马蹄铁之类的。但我们现在确实找到了办法来雇用我们雇用的，1.55亿，不管是多少，百万人，支撑3.3亿人口，而我们起步时是400万人，80%的劳动力在农场就业。所以这个系统运转着，它会继续运转，我不知道下一个大事物会是什么。我确实知道会有下一个大事物。Charlie？","kind":2},{"y":2019,"at":"03:49:41","ask":"嗨。嗨Warren，嗨Charlie。我叫Carrie，这是我女儿Chloe。她11周大。这是她第一次参加Berkshire股东大会。我们来自旧金山，我们有一个关于就业的问题想问你们。作为既是主要的……","ans":"Char，Charlie和我，我们在杂货店干过，有人订罐头的时候，我们有梯子爬上去够罐头，然后放进一个折叠箱，再装上卡车。如果你看看真正从生产者转移到消费者手里的食物量，以及交易中涉及的人数，你知道，那是，我不知道是三分之一还是四分之一还是五分之一，作为现在把食物送到你手上的最好方式。食物更糟。我祖父会，你知道，为这种特定的赊账送货店会被淘汰而难过，它确实被淘汰了，但社会……","kind":4},{"y":2019,"at":0,"ask":"巴菲特先生和芒格先生，非常感谢你们这些年来跟我们分享的智慧。我是纽约的Steven Wood。巴菲特先生，非常感谢您的反馈，您非常慷慨的反馈……","ans":"我觉得Berkshire现在的处境比以往任何时候都好，除了规模拖累业绩这一点。我大概40年前写过……嗯，其实我是在关闭合伙基金不接受新资金的时候写的，当时我们大概有4000万美元。我就说，真的，新的、额外的资本会从一个4000万美元的基数上拖低回报。所以你可以想象，现在Berkshire有3680亿美元的资本基数，我是什么感觉。但这个文化很特别。它能行得通。跟很多其他企业比，它远不会是复合增长率最高的。我觉得它会，它会是最稳妥的赚钱方式之一，随着时间赚到不错的钱。但那要看跟在我们后面的人。Charlie？","kind":2},{"y":2019,"at":0,"ask":"Buffett先生和Munger先生，非常感谢你们多年来与我们分享的智慧。我是来自纽约的Steven Wood。Buffett先生，非常感谢您的反馈，您非常慷慨的反馈，","ans":"所以我不会，我不，我不知道我们会不会跑赢S&P 500。我知道我们会用股东的钱表现得跟我们用自己的钱完全一样，我们会，我们基本上会把我们在生活中的命运跟这个企业绑在一起，我们会非常清楚不做任何可能以任何重大方式毁掉价值的事。但我们大概会，如果从现在起出现一个非常强的牛市，我们那段时间大概会跑输。如果市场5年后或10年后在这个水平或更低，那大概会跑赢。但我不，我，我不认为我想，我不太理解这个问题，说到S&P 10年期的总回报时，Berkshire内在价值的增长会跑赢。我不知道那会不会发生。Charlie？","kind":2},{"y":2019,"at":"05:06:11","ask":"Warren、Charlie你们好。我是巴拿马的Luis Kobo。我十年前成为Berkshire Hathaway的股东，很自豪，我一直在看See's Candies，我是它们的忠实粉丝，我也看到Charlie……","ans":"我觉得这恰恰说明，所有这些公式，你学的那些，或者有什么战略计划去用整个资本主义……有些生意只在相当有限的区域里行得通，有些真的能铺开。Dr Pepper，你知道，有个，我不知道现在百分比是多少，但在达拉斯可能是10%或12%的市场份额之类的，也许是8%，然后你到Detroit或者……就只有，就只有不到1%。我不确定现在的数字，但你会以为在一个流动的社会里，Dr Pepper从1886年Coke创立那会儿就有了，有些东西能传播，有些东西传播不了，真是奇妙。","kind":1},{"y":2020,"at":0,"ask":"","ans":"说实话，有些人就是不太谨慎，有些人比别人更容易恐惧。这就像病毒，它对有些人的打击要凶猛得多。而恐惧这东西，我在财务上真的从没感觉到过，我想查理也没有。但有些人的心理能扛得住。如果你心理上扛不住，那你真的不该碰股票，因为你会在错误的时间买进卖出。而且你不该指望别人来告诉你。你应该做你自己懂的事。如果你自己都不懂，那你就会被下一个跟你说话的人影响。所以你得处在能拿得住的位置上。我不知道今天是不是买股票的好日子。我知道二三十年下来会行得通。我完全不知道两年下来会怎样。你周一早上买的股票或者大盘，你是赚是亏，我一点概念都没有。","kind":0},{"y":2022,"at":0,"ask":"早上好。我叫Ole Pollem。我住在德国汉诺威。这是我第一次来奥马哈。我的问题是关于伯克希尔在美国以外整体收购公司。有过几家，Iscar，大概是第一家，Louis","ans":"现在想象一下……想象你有一个农场，你有640英亩，你每年耕种，赚了点小钱，享受耕种，不知怎么的，20来年后，它变成了1100或1200英亩。我是说，你会说，你知道，这是搞了多久了？你知道，为什么……还能有什么……你知道，这是美国式的，还是别的什么？我是说，这，你知道，是不是合理地满足它的资本成本，等等等等等等。而那，如果你在合适的价格做，没有什么比买你自己的生意更好的了。","kind":0},{"y":2022,"at":"01:37:05","ask":"你好，沃伦和查理。很高兴见到你们两位和出色的伯克希尔经理们。感谢你们所做的一切。我叫Rajiv Agarwal，来自新泽西。我的问题是关于择时的。你们","ans":"我们想先给你提供份工作。有意思的是，你知道，我们显然对股市周一开盘会怎么走毫无头绪。我们从来没有过，查理和我，我想在我们共事的所有时间里，我们从来没做过一个决定，是其中哪个人说过或者想过我们该根据市场会怎么走来买。没有，或者就那而言，根据经济会怎么走。我们不知道。","kind":0},{"y":2022,"at":0,"ask":"你好，沃伦和查理。很高兴见到你们两位和出色的伯克希尔经理们。感谢你们所做的一切。我叫Rajiv Agarwal，来自新泽西。我的问题是关于择时的。你们","ans":"我们在判断什么时候钱花得够值这方面还算不错，而我们买任何东西的时候都毫无头绪。嗯，我们总是希望它先跌一阵子，好让我们多买点，我们甚至希望在我们买完、钱花光之后，如果它还便宜，公司会继续回购，实际上等于提高我们的权益。我是说，这东西你四年级就能学到，但学校不教这个。","kind":0},{"y":2022,"at":"01:52:38","ask":"你好，Warren和Charlie。很高兴见到你们两位和出色的Berkshire经理们。感谢你们所做的一切。我叫Rajiv Agarwal，来自新泽西。我的问题是关于择时的。你们","ans":"对，嗯，前半段，从1945年8月起每一天，每一天，而且当第二个大国有了杀死数百万人的能力时急剧加速，又被那个不可思议的因子放大了。事实是每天都有风险。那是个非常非常小的风险，但就像Ajit，这桌上任何人都能告诉你，如果你一直掷，嗯，他们有过，他们有过一对拉斯维加斯Desert Inn的骰子，放在玻璃罩下放了一阵，有人连掷出32次过。我不知道，也许赔率是八百万比一，或者四百万，四十亿比一。但是，你知道，你只要一直掷骰子，你知道，什么都会发生。","kind":4},{"y":2022,"at":0,"ask":"你好，Warren和Charlie。很高兴见到你们两位和出色的Berkshire经理们。感谢你们所做的一切。我叫Rajiv Agarwal，来自新泽西。我的问题是关于择时的。你们","ans":"而人类其实还没有想出什么能对抗技术的东西。我是说，你回头看穴居时代，如果你是个反社会的人什么的，你朝隔壁洞里那家伙扔块石头，你知道，就那么回事。我是说，那大概跟……成比例的，然后我们一直在发展。后来就有了这个突破，技术完全跑到了人类前面，我们会看到会发生什么。但到目前为止还好。Berkshire没有答案，我们不知道。有些东西我们不出保单，因为反正我们也赔不起，你知道，那个，而且所有人都知道我们赔不起。所以我们不，我们，你有那个风险，Berkshire保护不了你。我们到目前为止一直很幸运。Ajit，有人问过你问题吗？","kind":2},{"y":2022,"at":0,"ask":"……而且在通胀中要有韧性，你会选哪只，具体是什么让那只股票表现那么好，而且很可能是一个艰难的市场？","ans":"是啊，没人等着退休或者期权归属，也没人想着，我们没有谁在想，我是不是该换个工作？就不是，你看，他们在做自己人生中想做的事。那也不是因为，你知道，我们在出比别人高的价，或者猎头跑来说我们想要这个人那个人，要什么条件才能挖到他们。他们挖不走。我是说，但现在这个，我不知道我们还能不能再建起来，但我们已经有了。","kind":3},{"y":2022,"at":0,"ask":"……并且在通胀中保持韧性，你会选哪个，具体是什么让那只股票表现那么好，而且很可能是一个艰难的市场？","ans":"然后我读到一章，其实我读到的是一段，在《聪明的投资者》第8章，我想是第8章，它就告诉我，我看的不是鸭子，我看的是，你知道，现在变成兔子了，不管是什么吧。你叫它灯泡也好，你叫它，你知道，顿悟时刻也好，不管是什么，这事发生过，在林肯市发生在我身上。我是说，它改变了我的人生。如果我没读那本书，我不知道我还会花多久去找头肩形态、200日移动平均线、零股比率还有一大堆东西。我热爱那类东西，只不过那不是，我看错了东西。","kind":4},{"y":2022,"at":0,"ask":"嗨沃伦和查理，我是Jeff McMalloy，来自旧金山的股东。近年来美国公司在政治领域扮演了更积极的角色，不管是公开反对某些法案还是——","ans":"但标题写的是，如果标题写巴菲特在买这个，如果写Berkshire Hathaway，会吸引更多人，而我们不知道那只是为他工作的人还是他本人。标题就是为了把人吸引进这个故事里。所以这种混淆很糟糕。最简单的做法基本上就是闭嘴，不要让一堆人承受他们一开始根本没要求面对的后果。所以，我很高兴你问了这个问题。","kind":0},{"y":2022,"at":"02:58:27","ask":"哦，谢谢沃伦和查理。我叫Tong Yao，来自中国，现在在芝加哥大学读书。我真的很敬佩你们两位，尤其是查理。你是我从小到大的榜样。我的问题是——","ans":"通胀，通胀是……问题是多大，问题是你能不能定在2%然后保持住。答案是没人知道。你看，我是说，你不知道，也没人知道。你听各种各样的说法，但他们不，没人知道未来10年、20年、50年或者下个月通胀会有多少。人们一直在谈这个，因为你想知道你这个问题的答案，但他们不知道答案。但有很多人，只要你给够钱，他们就会告诉你他们知道答案；还有些人免费告诉你，因为我觉得这能抬高他们的声望，让他们显得更有价值。但答案是，他们不知道，我们也不知道。","kind":0},{"y":2022,"at":0,"ask":"你提到过公司得到的是它们配得上的股东，在今年信里你提到你很大的一个满足感是为长期个人股东工作。随着影响力越来越大","ans":"当然，真正疯狂发展出来的流程是，人们跟，比如说，分析师群体讲话，你知道，金融界的高级祭司那种。你知道，有些公司一个月不止一次。你想，如果你在那家公司工作，去那家公司上班，每个月人们都在重复关于他们公司的这些东西，说重要的是我们每个客户要有更多服务，6.2，我们得做到7，或者什么的。他们一个月一个月一个月地说，这就变成了一套教义问答，CEO说，他或她的代表说，然后就……你下个月怎么接着说，顺便说一下，我们之前真的错了，这才是我们应该做的？你不会那么说。","kind":0},{"y":2022,"at":0,"ask":"你提到过公司得到的是它们配得上的股东，在今年的信里你提到你很大的一个满足感是为长期个人股东工作。随着影响力越来越大","ans":"但是，如果一件事是有破坏性的，该做的就是别开始。而预测盈利，我想不出还有什么比这更有破坏性的。我手下有36万人，他们知道我在不在撒谎，很多人知道，他们知道自己报上来的是什么数字，然后数字被改了。你知道，你这是在传递什么信息？我们有一个很戏剧性的例子就在……就是，你知道，我们想，你要是开始撒谎，你就有大麻烦了。就这么简单。如果你开始跟你的团队说，你有个工作，叫股东关系，你的工作就是出去告诉所有人我们的股票是几千个选择里每天最值得买的，那，那是疯了。那你跟他们说什么呢？他们就想，你知道，看看风往哪边吹，琢磨该跟人说什么，然后他们就想说。","kind":0},{"y":2022,"at":0,"ask":"在今年的信里你谈到了保险浮存金，浮存金的演变，每股浮存金，回购对提高每股浮存金的影响。关于回购，我要说谢谢你，因为你","ans":"现在，大概有，有3亿，有3亿，有1亿，美国有3.3亿人。这么看吧。3.3亿人，流通中的货币差不多2.3万亿，人均7000美元。每个男人、女人、孩子理论上都有7000美元的现金。嗯，你知道那不对，但你确实知道美联储的账本基本是对的。他们有那么多在外面。我不知道，在哪儿。我是说，我不知道是在俄罗斯，不知道是在南美，不知道在哪儿。你知道，我不知道是不是查理全拿着。我是说，这是个惊人的数字。你知道，现金已死，可我们平均每个美国人就有7000美元。","kind":1},{"y":2022,"at":"04:06:08","ask":"尊敬的巴菲特先生和芒格先生，我是来自加拿大蒙特利尔的Eli Abushakar。我想感谢你们为我们这些股东所做的一切。我的问题是关于GAAP规则的。如果你改变——","ans":"我，我不知道我会怎么写这些规则。我是说，我见过一些人，我会很乐意他们住我隔壁，你看，如果我要出门两周，我的孩子待在别人家，待在他们家我没问题。如果我钱包丢在什么地方又找回来了，他们会还给我。但他们玩，他们会拿送到手上的任何数字玩游戏。当然，在一家有人玩弄数字的公司当审计委员会成员是很尴尬的事，而且他们不想要你，如果你闹起来，你会有各种麻烦。","kind":4},{"y":2022,"at":0,"ask":"尊敬的巴菲特先生和芒格先生，我是来自加拿大蒙特利尔的Eli Abushakar。我想感谢你们为我们这些股东所做的一切。我的问题是关于GAAP规则的。如果你改变——","ans":"我是说，反正，有那几个缺陷，你看，它明年或者五年、十年是涨是跌，我不知道。但有一件事我比较确定，就是它不会，它不会自我增殖，不生产任何东西。它有一种魔力，人们给很多东西都附上了魔力。我是说，华尔街的目标，了不起的魔力，你看，“我们不是保险公司，我们是科技公司。”好吧，他们是保险公司，但我们自己十几个人也募了很多钱。他们就说，“别管我们卖保险这个事实，我们是科技公司。”好吧，最后他们写的是保险，而且从那以后绝大多数都亏了很多钱。你可以编出一些东西，在从别人那里拿钱方面很管用，这就是为什么……","kind":0},{"y":2023,"at":0,"ask":"你好。我是Marvin Blum，德州沃思堡的遗产规划律师，你的很多公司都在那儿。其实，沃伦，我是在我们敬爱的Paul Andrews的追悼会上见到你的，他是TTI的经理。我想得到你","ans":"但我知道有一个例子，一个特别有钱的家伙，他每年把孩子们聚在一起吃顿饭，想尽办法让他们在空白所得税申报表上签字，因为他不想让他们知道他们有多少钱什么的。嗯，那行不通。我是说，我不知道为什么一定，跟他来真的，但如果你想，你知道……但查理和我说过，你知道，如果你想想清楚你想怎么过你的人生，你就写好你的讣告然后倒推。我是说，你知道。","kind":4},{"y":2023,"at":0,"ask":"谢谢您，先生。现在我的问题。您时不时提醒我们不要做空美国。您认为让美国保持强大最重要的东西是什么？而在风险方面，如果这个国家的实力","ans":"这不是因为我们在……方面有什么不可思议的优势。当年人们试图通过统治海洋来统治世界的时候，两边各有一个大洋是好事。但，你知道，而且我们在加拿大和墨西哥有好的邻居。但这是个奇迹。你说，我们怎么保住这个制度好的部分，同时指出我们明显的缺陷？我们做这事的方式非常磕磕绊绊，但净下来看，美国，是个更好的居住地，但在我出生的时候，就已经好太多了。我是说，我一周前刚做了根管治疗，我就在想，我连谁发明了奴佛卡因都不知道，但我支持他。你知道，我是说，在无数方面。我是说，你可以回顾，你可以把过去浪漫化，但算了吧。","kind":4},{"y":2023,"at":0,"ask":"谢谢您，先生。现在我的问题。您时不时提醒我们不要做空美国。您认为美国保持强大最重要的因素是什么？而在风险方面，如果这个国家的实力","ans":"所以这是一个令人兴奋的世界。这是一个充满挑战的世界。而且我，你知道，我不知道这些问题的解决方案。我确实认为我们确实需要思考不同的解决方案，关于我们如何解决重要问题，而且我们不要自欺欺人地认为会发生什么神奇的事情，或者所有人会聚在一起，我们就都欢呼，然后到2050年它们就消失了什么的。它，以及我们适应得如何，我们拭目以待。我会说到目前为止看起来不太乐观，但我确信当林肯看待它的时候，内战时期的情况看起来也不太乐观。所以我认为美国有能力做出非凡的事情，而且我认为，如果他们再次做到，我不会感到惊讶。夏洛特，查理，Maiden 你是？","kind":2},{"y":2023,"at":0,"ask":"首先，谢谢你们让我们的生活变得更好。我叫Bogumil Baranowski。我是纽约的创始合伙人。我们管理多代家族财富，所以我的问题是。巴菲特先生，1976年，在您的 tribu","ans":"而他，某种程度上，你知道，查理和我们在生活中见过这一点。我是说，那种有准备的头脑，那种意愿，在需要行动时去行动，以及无视世界上每一个推销员的意愿，还有那条必须遵守的规范，就是一两件事让你做出正确的决定。如果你在配偶上做出了正确的决定，我是说，你就赢了这场游戏。他们，你知道，那是极其重要的决定，而且一直都有时间，我是说，在这个世界上，我们现在比小时候有更多时间来做那个决定，而且，你知道，我不知道是三分之一还是什么比例的人搞砸了那一个。你知道，这真的很有意思。要做的事就是不断努力把事情想透，不要做太多蠢事，迟早你会遇到一个Lollapalooza，夏洛特会这么说。好，Becky。","kind":0},{"y":2023,"at":"02:55:56","ask":"嗨，Warren和Charlie。我叫James，来自马来西亚。鉴于美国大银行面临的挑战，您对银行业整体的前景怎么看？您怎么评估这里的风险和机会？","ans":"我们得出了那个结论，我不知道Glass-Steagall是什么时候通过的什么的，但后来他们又想回去。你们有多少人知道，也许我记错了，我最近没看，但美联储其实被赋予了设定保证金要求的责任，他们改过很多次保证金要求，因为大家都知道，借钱太多的人会给银行系统带来危险，如果这种人太多之类的。结果呢，银行想出了上千种办法让你可以百分百保证金借贷，你知道，各种……我是说，通过衍生品什么的。他们完全扭曲了……所有从29年崩盘中得到的教训。","kind":0},{"y":2023,"at":0,"ask":"嗨，Warren和Charlie。我叫James，来自马来西亚。鉴于美国大银行面临的挑战，您对银行业整体的前景怎么看？您怎么评估这里的风险和机会？","ans":"嗯，如果我们不……我们不知道会发生什么，你知道，因为当前的情况可能引出很多事情。储户不会亏钱。控股公司的股东和债权人，他们应该亏钱。还有那些借钱投……投商业地产的人，现在贷款不……贷款不续了，他们该走人。这挺糟的。我是说，这就是百分百保证金借贷的一部分，人们就是这么干的，商业地产里就是这么干的。得让惩罚落到那些制造问题的人头上，如果他们承担了不该承担的风险，就得让他们承受，这样才能改变人们未来的行为方式。好，Becky。","kind":2},{"y":2023,"at":0,"ask":"嗨，Warren和Charlie。我叫James，来自马来西亚。鉴于美国大银行面临的挑战，您对银行业整体的前景怎么看？您怎么评估这里的风险和机会？","ans":"我们卖了银行，银行股，在过去……嗯，疫情爆发时我们先卖了一批，然后最近六个月又卖了一些。我们不知道大银行的股东，或者地区银行的股东，或者任何人，到底会走向哪里。我自己的银行……我自己的个人资金，我大概超过了FDIC的限额。我存在一家本地银行，我觉得……我一点都不担心。但就持有银行股而言，事件会决定它们的未来，有政客掺和进来，有很多人并不真正理解这个系统怎么运作。我得说，各种人跟美国公众之间的沟通，算不上完美。所以美国公众对银行业的困惑大概跟以往一样深，这会有后果，没人知道后果是什么，因为每个事件都会重新制造出不同的动态。","kind":2},{"y":2023,"at":0,"ask":"Buffett先生和Munger先生，嗨，我叫Daphne。我13岁，这是我第六次参加Berkshire Hathaway的年度大会，过去几年我有幸向你们两位提问。我今天的问题是","ans":"我们在遏制通胀预期方面不如以前了，通胀预期会自我实现，我们不知道……不如早先那样。而Berkshire对这种时期的准备比大多数投资都好。但我在年报里说过，我们也不是准备得完美，因为没法完美准备。你不知道会采取什么行动。现在这是个非常政治化的决定。某种程度上是部落式的决定。你只能希望领导层真能做点事，认识到问题。","kind":2},{"y":2023,"at":0,"ask":"巴菲特先生和芒格先生，你们好，我叫达芙妮。我13岁，这是我第六次参加伯克希尔·哈撒韦的股东大会，过去几年我有幸向你们两位提问。我今天的问题是","ans":"我们发现，如果我们足够喜欢这门生意、足够喜欢这些人，我们就会用不同的方式来量身定制。但我们的偏好是开一张支票，把整个地方买下来，让管理层继续留任。不，是啊，我希望……看着像亚当·赖特这样的人工作，真是太好了。我是说，基本上，你知道，我不知道他母亲挣多少钱，但他上了北高中，那大概离这儿四五英里，公立学校毕业，一路打拼上来，去太平洋煤气电力公司待了很短一段时间，然后我们把他们带回家来经营Pilot。","kind":0},{"y":2023,"at":"03:30:02","ask":"下午好，巴菲特先生、芒格先生。我叫 JC。我 15 岁，来自俄亥俄州。这是我第四次现场参加伯克希尔股东大会。我从你们的演讲、采访和文章中学到了很多，充满热情。……","ans":"是啊。你把它最小化了，但你没法……我是说，这毫无疑问。但查理那天给了一个回答，我觉得简直是攻击大师级的，他说：“你总是要跟行为端正的人打交道。”他说：“当然，对家人你得有些例外。”但这个……但这是真的。而且，你知道，你真的……我不知道那是什么感觉，你知道，一个酗酒的、你知道，粗暴的，大概是父亲，但一般就是父母。我是说，那……你知道，你怎么应对？","kind":0},{"y":2023,"at":0,"ask":"嘿，沃伦和查理。下午好。我叫阿肯色，沃尔玛的家乡。我从2019年起就是股东，我的女儿们从2020年起也是股东。我的问题是……这是我第一次来参加股东大会，","ans":"所以我和查理观察过，各种各样的东西。产品太多了，零售的方法太多了，我们真的认为我们懂不少，懂很多，同时我们也知道我们在这上面有多少不懂的。这并不意味着我们想自己去做零售，但这确实意味着我们在某种程度上学会了该避免什么。我们也学会了什么时候某人真的有东西。Garanimals就有东西。只是，你知道，沃尔玛在为我们做分销方面做得很好，这对沃尔玛是好产品，对我们也是好产品。至于Fruit of the Loom，他们能解决很多种内衣，他们能做很大的量，但我们不会赚那么多钱，按投入资本之类的算，因为产品有一大堆竞争对手。","kind":0},{"y":2023,"at":0,"ask":"下午好。我叫汉娜·海斯，我是爱荷华州的一名高中生。您今天早些时候说，向可再生能源转型有人力和资本来支持它。那么，如果有足够的投资和可再生能源","ans":"但我不会……我会说，我们在风能和太阳能上的记录，美国任何一家公用事业公司都教不出来。当然，这得益于大多数公用事业公司把70%或80%的收益作为股息派发出去，而我们没有从……一点点优先股里拿过普通股息，你知道，20年没拿过普通股息了。我们重新投资了，我不知道多少十亿。这就是为什么他们的收益从2亿美元变成了40亿美元。但我们赚的资本回报率并不比我们起步时高。我们只是往这些生意里投入了多得多的资本。我们一路走来，不断把资本再投资进去。所以我希望格雷格能告诉你更多细节，但，但我会说，我们会拿出，我们真的会把伯克希尔·哈撒韦能源的记录跟美国任何一家公用事业公司比。石油，你看着吧。","kind":3},{"y":2023,"at":"04:19:19","ask":"非常感谢你们的一切，沃伦和 Buff，沃伦·巴菲特和查理·芒格。你们彼此之间有什么从没讲过的、最好笑的故事？还有，你们生意里最难的部分是什么？","ans":"……你问题的第二部分，是，我们没有什么核心业务。我们热爱我们的生意。每天早上我起床，感觉很好。我不知道那天会发生什么。也许什么都不会发生，但也许会发生点什么，要是别的没有，我就滚点 T-bills 什么的。但，但，我工作，我和你能想象到的最棒的一群人一起工作。我是说，我们，我们喜欢彼此，没人惦记别人的职位或者类似的东西。这是理想的工作条件，而且离我家大概五分钟，所以我这辈子没花时间通勤。我简直想象不出还能有什么更好的。而且，查理有很多你没听过的搞笑故事，但我们看看她能想出什么来。","kind":0},{"y":2023,"at":0,"ask":"非常感谢你们所做的一切，Warren和Buff，Warren Buffett和Charlie Munger。你们彼此之间从未讲过的最有趣的故事是什么？还有，你们业务中最难的部分是什么？","ans":"但这并不意味着它能办成。如果，如果我给了这个国家，在这个例子中是英国，想要阻止它，他们比美国更有能力阻止它。但世界就是这样运转的，而且这不能通过提供更多钱之类的来解决。它，它，我不知道它，它结果会怎样。但如果它没通过，我不认为是因为微软或Activision的任何不足。但不是所有应该发生的事都会发生。","kind":2},{"y":2023,"at":0,"ask":"你好，我叫Humphrey Liu，来自弗吉尼亚州夏洛茨维尔。首先，我想问，想加上我对您和Munger先生、Buffett先生以及整个Berkshire的感谢，感谢每年举办这个盛会。L","ans":"但任何人认为现金是垃圾，自动，看看，看看美联储的资产负债表。实际上你可以看看有多少5美元钞票、2美元钞票和1美元钞票等等，而动静一直在100美元钞票上。我是说，这，100美元钞票扩散的方式简直令人震惊。而且，当然，我们不知道，我不知道它们在哪里，而且我认为美联储也无法确切知道，但他们可能比我猜得准得多。但我确实知道发生了什么，你可以每周观察，你会看到流通中的货币大概会增长一点。而且，相信我，现金不是垃圾。查理？","kind":0},{"y":2024,"at":"00:51:46","ask":"嗨，乔，我从旧金山来。您怎么看技术进步，尤其是生成式AI，对传统行业的影响？谢谢。","ans":"对，我点第四个人的时候搞错了，但我待会儿会回到那两个。我对AI一无所知，但我确实有……这不代表我否认它的存在或重要性之类的。去年我说过，我们发展核武器的时候，等于把精灵从瓶子里放了出来，那个精灵最近干了些可怕的事。那个精灵的力量，你知道，把我吓坏了。然后我不知道有什么办法能把精灵塞回瓶子里。","kind":2},{"y":2024,"at":0,"ask":"嗨，乔，我从旧金山来。您怎么看技术进步，尤其是生成式AI，对传统行业的影响？谢谢。","ans":"我需要你电汇5万美元。”我是说，诈骗一直是美国社会的一部分，但这会让我，如果我有兴趣投资诈骗行业的话，[觉得]这将是史上最大的成长型行业，而且它被赋能的方式……显然，AI也有做好事的潜力，但我不知道你怎么……根据我最近看到的那一个，我 practically 会为了某个离谱的[套路]把钱汇给自己。","kind":2},{"y":2024,"at":0,"ask":"嗨，乔，我从旧金山来。您怎么看技术进步，尤其是生成式AI，对传统行业的影响？谢谢。","ans":"然后到了某个时候，我听到一个投资者电话，它让我把事情串起来了……这不代表我知道自己稳赢之类的。我不知道明年油价会是多少，但我知道这事值得动手。所以我们做了，我们很高兴做了，而我们到现在也还是不知道明年油价会是多少。","kind":4},{"y":2024,"at":0,"ask":"嗨，乔，我从旧金山来。您怎么看技术进步，尤其是生成式AI，对传统行业的影响？谢谢。","ans":"那一下子就成了连接点。所以回答你的问题，我不知道现在相当于Moody's Manuals的东西是什么，但我会尽量把每件小事都了解透，我会找到点什么。有一百万美元，你一年能赚50%。但你得爱上这个题目。你不能只爱钱。你真得就是找到它，像个真正的……你知道，本质上，就像，你知道，人们在别的领域找到别的东西，就是因为他们爱找。生物学家找东西是因为他们想找到点什么，这刻在……我不知道人脑是怎么运作的，我觉得也没人太懂人脑是怎么运作的。但就是有不同的人，觉得在某个领域扩展知识很带劲。","kind":0},{"y":2024,"at":0,"ask":"嗨，乔，我从旧金山来。您怎么看技术进步，尤其是生成式AI，对传统行业的影响？谢谢。","ans":"想象一下，如果这个房间里的每个人都听从某个人的投资建议，那人说：“你知道，每年1%，我就告诉你该怎么投资你的钱。”1950年我们起步的时候，1965年，他们会说：“嗯，买Berkshire Hathaway，”如果他们活到现在，看到那1%的安排，他们每年会从那些没从我们这儿拿到任何股息的人那里收80亿美元。所以他们对跟你谈成的这种合同的利益诉求，跟你的会不一样。最好的做法就是一次性付他们佣金，然后持有股票。","kind":1},{"y":2024,"at":0,"ask":"嗨，乔，我从旧金山来。您怎么看技术进步，尤其是生成式AI，对传统行业的影响？谢谢。","ans":"但不管怎么说，这挺有意思的……有一点是，在座的每个人，我不知道从别的国家来的那些人怎么样，但你应该有一份遗嘱，因为如果你没有遗嘱，你其实还是有遗嘱，那就是州里说了算。这太惊人了。四位美国总统去世时没留遗嘱。四位。你知道，我们总共才45位。想象一下当上了美国总统却没留遗嘱。但你可以查查最近某个人，我想，林肯，我确定林肯是那四位之一。而这是个人物，我是说，我不知道你总能怎么说……好吧，他没顾上办这事，但很难想象亚伯拉罕·林肯为什么会没留遗嘱就去世了。我肯定在座有些林肯学者，会后会写信给我解释原因，我会很有兴趣收到他们的信。","kind":4},{"y":2024,"at":"01:42:07","ask":"嗨，乔，我从旧金山来。您怎么看技术进步，尤其是生成式AI，对传统行业的影响？谢谢。","ans":"约翰·梅纳德·凯恩斯读起来真是太好了，[而且有]了不起的头脑。但大概在我出生那会儿，他写了一本书讲可能会发生什么。我不知道是未来一百年还是多久。他正确地预测了人均产出会以那种惊人的速度增长，确实如此。但要说推测人们会拿这个干什么，我是说，这家伙聪明得难以置信，但事情并没有完全按他预测的那样发展。他对要进入方程式的变量判断对了，但他没搞清楚结果到底会是什么。所以真的是……嗯，我们开发炸弹的时候并不知道，很可能很快就会有九个国拥有他们拥有的东西，其中三个我们得特别担心，但我们当时真的没有别的选择。","kind":4},{"y":2024,"at":"01:45:20","ask":"嗨，乔，我从旧金山来。您怎么看技术进步，尤其是生成式AI，对传统行业的影响？谢谢。","ans":"嗯，我会说答案当然是，我不知道，但我最好的推测是，美国债务在很长很长时间内都会被接受，因为没什么替代品。但问题不在数量。国债在很长很长一段时间里都不值一提。问题不在数量。而在于通胀会不会以某种方式失控，真正威胁到整个世界经济形势。而美元作为储备货币真的没有替代品。会有很多人给你做很多演讲讲这个，但答案真的就是这个。","kind":2}]};
